window.__D("text/torat-shmuel/c029",{"p":[[2000450328,"קוב\"ה מצד עצמותו ומהותו ית' לא שייך עליו מלת אחד שהרי<sup data-n=\"3363\">*60</sup> הוא יחיד כו' ובפ' מקץ<sup data-n=\"3364\">60</sup> בהביאור ע\"פ כי אתה נרי בענין מלך יחיד חי העולמים, ובלק\"ת פ' ואתחנן בד\"ה ענין ק\"ש ושם פ\"ב גבי וזהו חד ולא בחושבן כו', וכשישים האדם כו' בבחי' יחידה שבנפש כו'].\n<b>והנה</b> מבואר זה במ\"א עד\"מ שהשכל במוח הוא בבחי' או\"פ וכלי<sup data-n=\"3365\">61</sup> שהרי קלקול המוח גורם קלקול השכל כמבואר בספרי הרפואה מזה מוכח שהוא בחי' כלי לאור פנימי המצומצם בו שהוא השכל כו', ועד\"ז מדות בלב ונפש בכבד כו', משא\"כ בחי' הכתר שהוא הרצון אין לו כלי שיגבילנו והוא אינו נתפס בכל חלקי אברי הגוף<sup data-n=\"3366\">*62</sup> וגם הנה הוא מושל ושליט בכל חלקי הקטנים שבאברי הגוף כו' [וע' מזה ג\"כ בלק\"ת פ' צו בד\"ה להבין מפני מה יו\"ט דפסח ובד\"ה ויקח קרח ושם ספ\"א ובד\"ה נשא את ראש בני גרשון דרוש השני פ\"ב]. וזהו שאמר בכתר עליון דאיהו תפיס בכולהו עלמין<sup data-n=\"3367\">62</sup> ולית מאן דתפיס בי' כו'. ואמנם הנה מזה הטעם שאין בחי' כלי הגבלה כלל לבחי'<sup data-n=\"3368\">63</sup> יחידה אלא הן אורות מקיפים בלבד מבלתי הגבלה כלל לכך אין מן ההכרח שיתגלו ושיתפשטו למטה ע\"י התעוררות מלמטה אלא הן באין ונמשכין להתגלות למטה מאליהם, כי היא הנותנת דלפי שאין להם אחיזה ושייכות למטה בכלים ואורות אין להם ערך עמהם עד שיהיו הם מעוררים אותם אלא לאחר שנשלם תיקון דכלי באים ממילא ושורים עליו כו', משא\"כ בחי' אור פנימי דלפי שהוא יש לו שייכות וקשר וחיבור עם הכלי שהרי הוא מוגבל בכלי לכך יש לו ערך ג\"כ עמו עד שלא ישרה בו רק לפי ערך ההכנה והוא לפי ערך ההעלאת מ\"ן כידוע. והיינו הטעם שאנו אומרים ברוך אתה כו' ממילא יתברך כי מעצמות יבוא אור המקיפים מטעם זה אך הנה לא יבוא ממילא רק אחר שיש בחי' שלימות בתיקון הכלי דוקא [(וכענין יריעות המשכן וכל כליו לאחר שהוכנו בשלימות אז ירד כבוד ה' בענן המקיף ממילא כו' וכמ\"ש במ\"א באריכות)] [וע' בלק\"ת בשה\"ש<sup data-n=\"3369\">64</sup> בד\"ה להבין ביאור הדברים ע\"פ אני ישינה ולבי ער ושם פ\"ב בענין פתחי לי כחודה של מחט ואני אפתח לך כפתחו של אולם יעו\"ש]. (ויובן זה עוד מההיפך ממ\"ש בלעם את שבעת המזבחות<sup data-n=\"3370\">65</sup> ערכתי ואעל כו' והיינו שעשה הכנה שישרה עליו דבר הנבואה, וע' בלק\"ת מהאריז\"ל פ' בלק<sup data-n=\"3371\">66</sup> ענין בלעם שהי' מהמקיף, וי\"ל שלפי שבלעם ראה שהקב\"ה אוהב א\"י וע\"י בחי' הפנימי' בודאי לא יוכל להם שהגם שהזכיר חטאותם למקומותם<sup data-n=\"3372\">67</sup> עכ\"ז כו', ולכן ניסה א\"ע אולי",[["3363","*60","<b>אחד שהרי</b>: בתו\"א: אחד כלל שהרי."],["3364","60","<b>ובפ' מקץ</b>: מא, ב."],["3365","61","<b>שהשכל במוח. . או\"פ וכלי</b>: בהבא לקמן ראה מאמרי אדה\"א במדבר ח\"א ס\"ע קפג ואילך."],["3366","*62","<b>הרצון. . בכל חלקי אברי הגוף</b>: ראה גם (בנוסף להמצויין בפנים) לקמן (בחלק ההנחות) בהנחה כאן ובהערה 50-51."],["3367","62","<b>דאיהו תפיס בכולהו עלמין</b>: ראה זהר רע\"מ פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670220\" data-slug=\"torat-chaim\" data-id=\"2300670220\">תו\"ח נח סו, ג</a> הערה 30."],["3368","63","<b>לבחי'</b>: במאמרי אדה\"ז תקס\"ה ח\"ב ע' תשטז כאן: לחי'. ראה גם לקמן הערה 75."],["3369","64","<b>בלק\"ת בשה\"ש</b>: לה, ג."],["3370","65","<b>את שבעת המזבחות</b>: בלק כג, ד."],["3371","66","<b>בלק\"ת מהאריז\"ל פ' בלק</b>: ד\"ה ענין בלק ובלעם הא'."],["3372","67","<b>שהזכיר חטאותם למקומותם</b>: ראה רש\"י בלק כד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380410\" data-slug=\"likkutei-torah\" data-id=\"4001380410\">לקו\"ת נשא כה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380871\" data-slug=\"likkutei-torah\" data-id=\"4001380871\">תצא לח, ג</a>. מאמרי אדה\"א דברים ח\"ב ע' תרמג ובהנסמן שם [<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316610352\" data-slug=\"or-hatorah-hb\" data-id=\"8316610352\">אוה\"ת תצא ע' תתקפא</a> ואילך — ראה הערה במאמרי אדה\"א שם ע' תרמב]."]]],[2000450329,"בבחי' המקיף ששם אם חטאת<sup data-n=\"3373\">68</sup> כו' אם צדקת<sup data-n=\"3374\">69</sup> כו', ומה גם כי אתם המעט<sup data-n=\"3375\">70</sup> כו', שהגם שלגבי המקיף אינו תופס מקום המספר עכ\"ז כו', ולכן עשה הכנה כנ\"ל וילך שפי<sup data-n=\"3376\">71</sup> שזהו לעו\"ז דתפלה בלחש. אבל מלבד שלא אבה כו' לשמוע<sup data-n=\"3377\">72</sup> משמע שהי' מקום לשמוע שזהו מצד בחי' האו\"פ סדר השתלשלות, אלא שגם ויהפוך ה' אלקיך ע\"ס שבמאציל לך את הקללה לברכה זדונות נעשו כזכיות כמ\"ש בפ' תצא בד\"ה ולא אבה<sup data-n=\"3378\">73</sup>, ולכן כתי' אח\"כ וירא בלעם<sup data-n=\"3379\">74</sup> כי טוב בעיני ה' לברך, פי' שגם בעיני ה' שהוא בחי' ההבטה שהוא בחי' או\"מ כמשי\"ת ג\"כ טוב הוא לברך את ישראל, ולכן לא הלך כפעם בפעם לעשות הכנה כנ\"ל. ועכ\"פ מובן מזה איך שבקדושה צ\"ל ג\"כ הכנה, וכאשר יש הכנה ממילא שורים המקיפים שלא לפי ערך ההכנה כלל שאינו בדרך אתעדל\"ת כנ\"ל כו').\n<b>וזהו</b> שאומר גם כאן לאחר שנעשה שרש תיקון הפרצופים דזו\"נ דאצי' ע\"י תושב\"כ ותושבע\"פ כנ\"ל דהיינו ואת כל אלה ידי עשתה ויהיו כל אלה נאום ה' ואל זה אביט כו', פי' אביט הוא בחי' הארות אור המקיפים דבחי'<sup data-n=\"3380\">75</sup> יחידה שבא ומאיר ממילא אחר שיש תיקון שלם באורות וכלים דנר\"נ ע\"י העשי' ובפרט ע\"י הדבור שהוא עיקר תיקון הנוק'<sup data-n=\"3381\">76</sup>, וזהו פי' נאום ה' שהוא בחי' תיקון הנוק' כו' [(לפי שכל המקיפים נמשכים למל'<sup data-n=\"3382\">77</sup> יותר מטעם שהיא סופא דכל דרגין<sup data-n=\"3383\">78</sup> צריכה שמירה ביותר וכמ\"ש על חומותיך ירושלים הפקדתי שומרים כו' וכמ\"ש במ\"א הטעם שהמל' יש לה ז' מקיפים<sup data-n=\"3384\">79</sup> )], [ועיין מזה בבה\"ז ר\"פ בראשית<sup data-n=\"3385\">80</sup> במאמר כשושנה בין החוחים בפי' אלקי' יחננו ויברכנו יאר פניו, ומזה יובן מ\"ש תילים סי' מ\"ב<sup data-n=\"3386\">81</sup> צמאה נפשי כו' מתי אבוא ואראה פני אלקים, ועיין זח\"ב פ' תרומה קנ\"ח ב' ע\"פ בזאת אני בוטח, כ\"א בזאת יתהלל<sup data-n=\"3387\">82</sup>, וזאת הברכה]. וזהו אל זה אביט בבחי' ההסתכלות דראי' דוקא והוא ע\"פ הידוע בכתבי האריז\"ל<sup data-n=\"3388\">83</sup> בעליית ז\"א בא\"א כשמסתכל ז\"א בא\"א במצחא דא\"א מקבל שע\"ה נהורין<sup data-n=\"3389\">84</sup> כו'",[["3373","68","<b>אם חטאת</b>: איוב לה, ו."],["3374","69","<b>אם צדקת</b>: איוב שם, ז."],["3375","70","<b>כי אתם המעט</b>: ואתחנן ז, ז."],["3376","71","<b>וילך שפי</b>: בלק כג, ג."],["3377","72","<b>שלא אבה כו' לשמוע</b>: תצא כג, ו. ראה גם מאמרי אדה\"א דברים ח\"ב ס\"ע תרמג ואילך."],["3378","73","<b>ויהפוך. . ע\"ס שבמאציל. . הקללה. . כזכיות כמ\"ש בפ' תצא בד\"ה ולא אבה</b>: תצא שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380875\" data-slug=\"likkutei-torah\" data-id=\"4001380875\">לקו\"ת שם לט, סע\"ג</a> ואילך."],["3379","74","<b>וירא בלעם</b>: בלק כד, א."],["3380","75","<b>דבחי'</b>: במאמרי אדה\"ז תקס\"ה ח\"ב ע' תשטז כאן: דחי'. ראה גם לעיל הערה 63."],["3381","76","<b>הנוק'</b>: במאמרי אדה\"ז תקס\"ה כאן: הגוף."],["3382","77","<b>למל'</b>: במאמרי אדה\"ז תקס\"ה כאן: לנוק'."],["3383","78","<b>למל'. . סופא דכל דרגין</b>: ראה זהר בשלח נו, א. פקודי רכו, סע\"א."],["3384","79","<b>שהמל' יש לה ז' מקיפים</b>: ראה גם לקמן בסיום מאמר זה. (ובחלק ההנחות) בסיום ההנחה. מאמרי אדה\"ז תקס\"ה כאן. תקס\"ו ע' שפו בשם הע\"ח."],["3385","80","<b>בבה\"ז ר\"פ בראשית</b>: א, ב."],["3386","81","<b>תילים סי' מ\"ב</b>: פסוק ג."],["3387","82","<b>בזאת אני בוטח, כ\"א בזאת יתהלל</b>: בזהר שם: כ\"א בזאת יתהלל. . בזאת אני בוטח."],["3388","83","<b>בכתבי האריז\"ל</b>: ראה ע\"ח שער א\"א שי\"ג, פי\"ד."],["3389","84","<b>שע\"ה נהורין</b>: בע\"ח [שבהערה שלפנ\"ז]־ זהר־ תו\"א ולקו\"ת [שבהערה שלאח\"ז]: ש\"ע. וראה גם לקמן בהקיצור. אבל כ\"ה גם במאמרי אדה\"ז תקס\"ה ח\"ב ע' תשיז כאן. מאמרי אדה\"א קונטרסים ע' רצז.\nראה לקמן (בהחלק ההנחות) בהנחה כאן על יד הערה 77: פי' שנמשך ש\"ע וה' נמשכים ממילא. וראה גם ש\"א יד, א הערות 12-14. אוה\"ת (יהל אור) תהלים ע' שנב. וישלח כרך ז ע' 2462. בלק כרך ו ע' א'תתקטז [ובמהדורת תשנ\"ח ע' א'יד]."]]],[2000450330,"וכשמסתכל בפנים דא\"א מקבל ק\"נ נהורין כו' [וכמ\"ש מזה בפ' ויחי בהביאור ע\"פ חכלילי עינים<sup data-n=\"3390\">85</sup>].\n<b>וביאור</b> הדברים לפי שבחי' א\"א הוא בחי' הכתר עליון, והנה ידוע ע\"פ והחכמה מאין תמצא<sup data-n=\"3391\">86</sup> שהכתר נק' בחי' אין<sup data-n=\"3392\">87</sup> להיותו ממוצע כנ\"ל ולכך נחשב הוא עדיין מעולם הא\"ס כי מבחי' מל' דא\"ס נעשה בחי' הכתר לכל ההשתלשלו' ע\"ד כלל כידוע<sup data-n=\"3393\">88</sup>, וע\"כ כאשר המדות דאצי' הנק' ז\"א עם המל'<sup data-n=\"3394\">89</sup> שעולה עמו ואינה יורדת כו' מסתכלים במצחא דא\"א דהיינו לקבל מהארת המצח שבכתר ששם הוא בחי' אור הא\"ס מתבטלים זו\"נ דאצי' ממציאות הגבלתם באור וכלי כנ\"ל ונעשים גם הם למעלה מגדר כלי כמו אור המקיפים דחיה יחידה מפני בחי' ההתכללות שלהם שמתכללים בבחי' הכתר בהסתכלות הזאת וזהו כמ\"ש עיניך יונים<sup data-n=\"3395\">90</sup> כו' עיניו כיונים<sup data-n=\"3396\">91</sup> כו' כמשל היונה שהזכר מביט<sup data-n=\"3397\">92</sup> כו' וכמ\"ש במ\"א והוא לפי שא\"א שיקבלו זו\"נ ההארה בבחי' הכלי כמו שהן למטה לפי שבחי' יחידה אין שם בחי' הכלי כלל כנ\"ל לכך אין היחוד אלא בבחי' הסתכלות בלבד וכמשל ההסתכלות שהמביט מקיף אותו הדבר שהוא מביט עליו מכל צדדיו וכו' [ועמ\"ש מזה בלק\"ת ע\"פ ואתחנן אל ה' ושם ספ\"ד<sup data-n=\"3398\">93</sup> ובהביאור פ\"א ובפ' ראה ע\"פ כי תשמע בקול בד\"ה ביאור הדברים גבי דפי' עיני ה' שהוא התחברות ויחוד ב' השגחות]. וכ\"ז אינו אלא לאחר התיקון דזו\"נ<sup data-n=\"3399\">94</sup> באורות וכלים שאז ממילא באה בחי' ההבטה מא\"א למטה בזו\"נ להעלותם בעילוי הכתר עי\"ז כו' [ועמ\"ש בת\"א פ' תצוה סד\"ה ועשית בגדי קדש גבי במקום שיש משפיע ומקבל כו' וכמ\"ש זכר ונקבה בראם ויברך אותם<sup data-n=\"3400\">95</sup>].",[["3390","85","<b>בפ' ויחי בהביאור ע\"פ חכלילי עינים</b>: תו\"א שם מח, ב ושם מציין: לאד\"ר — ראה זהר אד\"ר נשא קכח, ב [וכן צ\"ל בפלח הרמון דבסמוך]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380698\" data-slug=\"likkutei-torah\" data-id=\"4001380698\">לקו\"ת מסעי צג, סע\"ג</a>. וש\"נ. פלח הרמון שמות ע' שסב בהערה. המשך תער\"ב ח\"ב ע' א'רה."],["3391","86","<b>והחכמה מאין תמצא</b>: איוב כח, יב. ראה מאמרי אדה\"א דברים ח\"ג ע' תשעט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670072\" data-slug=\"torat-chaim\" data-id=\"2300670072\">תו\"ח בראשית ז, ד</a> ובהערה 49. בא ח\"א קא, ג. וש\"נ."],["3392","87","<b>שהכתר נק' בחי' אין</b>: ראה זהר שלח קנח, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תנח. וש\"נ. הנחות תקע\"ז ע' ב. וש\"נ."],["3393","88","<b>ע\"ד כלל כידוע</b>: אולי הכוונה שמל' שבעליון נעשה כתר לתחתון — ראה שעה\"י קטז, ב ובהערה 25."],["3394","89","<b>המל'</b>: במאמרי אדה\"ז תקס\"ה ח\"ב ע' תשיז כאן: הנוק'."],["3395","90","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381288\" data-slug=\"likkutei-torah\" data-id=\"4001381288\">לקו\"ת שה\"ש מ, א</a>."],["3396","91","<b>עיניו כיונים</b>: שה\"ש ה, יב."],["3397","92","<b>כמשל היונה שהזכר מביט</b>: ראה גם לקמן מאמר ד\"ה אני לדודי על יד הערה 99. מאמרי אדה\"ז תקס\"ד ע' קלז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381186\" data-slug=\"likkutei-torah\" data-id=\"4001381186\">לקו\"ת שה\"ש יד, ב</a>. תו\"ח ח\"ש קלב, סע\"א ואילך ובהנסמן לשם. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תקפז."],["3398","93","<b>ספ\"ד</b>: אוצ\"ל: רפ\"ד."],["3399","94","<b>דזו\"נ</b>: במאמרי אדה\"ז תקס\"ה ח\"ב ע' תשיז כאן: דנוק'."],["3400","95","<b>זכר ונקבה בראם ויברך אותם</b>: בראשית ה, ב."]]],[2000450331,"<b>וזהו</b> ואל זה אביט עני<sup data-n=\"3401\">96</sup> ונכה רוח וחרד כו', פי' עני דלית לי' מגרמי' כלום הוא בחי' נוק' דז\"א<sup data-n=\"3402\">*97</sup> דסיהרא<sup data-n=\"3403\">97</sup> לית לה מגרמה כלום<sup data-n=\"3404\">*98</sup> כידוע וכמ\"ש תפלה לעני<sup data-n=\"3405\">98</sup> כו' כידוע בזהר<sup data-n=\"3406\">99</sup> ובע\"ח, ונכה רוח הוא בחי' ז\"א שנק' רוח בכלל לגבי המל' שנק' נפש<sup data-n=\"3407\">100</sup> כידוע. ולהיות שהן באים לקבל ההארה מבחי' הכתר כנ\"ל א\"א כ\"א שיתבטלו ויופשט מכל בחי' כלי והוא להיות בתכלית הביטול במציאות וזהו כמו ונכה רוח ועני דלית לי' מגרמי' כלום כו' אז אל זה אביט בבחי' ההסתכלות דאור המקיף להקיף מכל צד כו'<sup data-n=\"3408\">101</sup>. וזהו ג\"כ ענין כריעות והשתחוואות דשמו\"ע<sup data-n=\"3409\">102</sup> ולזקוף בשם ולכרוע בברוך<sup data-n=\"3410\">103</sup> דוקא כידוע לפי שפי' הוי' אלקינו ידוע דהיינו בחי' זו\"נ<sup data-n=\"3411\">104</sup> דאצי' ובתיבת ברוך שמוריד המשכות אור המקיף שיבוא ממילא ומעצמו דוקא כנ\"ל הטעם צריך לכרוע בבחי' הביטול הגדול לפי שלא יוכלו לקבל האור המקיף כ\"א ע\"י בחי' הביטול בלבד ולא בשום דבר זולתו מפני טעם הנ\"ל דבחי' המקיפים אין בחי' כלי תופס מקום כלל וכלל (וחרד על דברי י\"ל שזהו כמ\"ש בחבירי דניאל, אבל חרדה גדולה נפלה עליהם<sup data-n=\"3412\">105</sup> וכמ\"ש בכ\"ד וע' בפ' במדבר בביאור וידבר דעה\"ד<sup data-n=\"3413\">106</sup> בענין מזלייהו חזי).\n<b>וזהו</b> ג\"כ שרש הדברים במה שמצד בחי' זו דאל זה אביט כנ\"ל נאמר לא הביט און ביעקב<sup data-n=\"3414\">107</sup> ולא ראה עמל כנ\"ל<sup data-n=\"3415\">108</sup>, כי הנה ידוע בפי' י\"ג מדה\"ר אל<sup data-n=\"3416\">109</sup> רחום וחנון כו' ששרשם הוא בבחי' אורות המקיפי' דחי' יחידה הנ\"ל שלפני כל האצי'<sup data-n=\"3417\">110</sup>, אך שם הן בבחי' ההעלם הגדול והיינו בבחי' האין דכתר דא\"א כו' וצריך שיבאו",[["3401","96","<b>ואל זה אביט עני</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תשיז ולקמן ע' תשכה: אל זה אביט אל עני. ראה גם שע\"ת בהקדמה ב, א. ד\"ח ו, א."],["3402","*97","<b>עני. . נוק' דז\"א</b>: ראה גם לקמן (בהחלק ההנחות) בהנחה כאן ובהערה 88."],["3403","97","<b>עני. . דסיהרא</b>: ראה גם לעיל המשך אם כסף תלוה פי\"ד ובהערה 299."],["3404","*98","<b>דסיהרא לית לה מגרמה כלום</b>: ראה זהר בראשית לג, ב. תולדות קלה, סע\"ב. ויחי רלו, ב. רמט, ב. ויקהל רטו, א. בחוקותי קיג, ב. מאמרי אדה\"ז הקצרים ע' שפג."],["3405","98","<b>תפלה לעני</b>: תהלים קב, א."],["3406","99","<b>בזהר</b>: ראה זהר וישלח קסח, ב. אוה\"ת ר\"ה ס\"ע א'שצא ואילך."],["3407","100","<b>רוח. . ז\"א. . המל' שנק' נפש</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ז. פרדס שער מהות והנהגה ש\"ח, פי\"ג. מאמרי אדה\"ז תקס\"ה כאן. מאמרי אדה\"א במדבר ח\"ב ע' תקעב. וש\"נ. דברים ח\"ג ע' תתעא. אוה\"ת בלק ע' א'לג."],["3408","101","<b>כו'</b>: במאמרי אדה\"ז תקס\"ה כאן ניתוסף: (ומ\"ש חרד על דברי הוא לאחר התיקון דנוק' ע\"י הדבור ובבחי' הביטול דוקא וזהו חרד כי חרדה מסלק הדמים כידוע) וד\"ל."],["3409","102","<b>דשמו\"ע</b>: במאמרי אדה\"ז תקס\"ה כאן: שבכל ברכה. ולהעיר מש\"א כד, רע\"א ובהנסמן במ\"מ לשם."],["3410","103","<b>ולזקוף בשם ולכרוע בברוך</b>: ראה ברכות יב, סע\"א."],["3411","104","<b>הוי' אלקינו. . זו\"נ</b>: ראה גם מאמרי אדה\"ז תקס\"ה כאן."],["3412","105","<b>אבל חרדה גדולה נפלה עליהם</b>: דניאל י, ז."],["3413","106","<b>בפ' במדבר בביאור וידבר דעה\"ד</b>: לקו\"ת שם יז, א."],["3414","107","<b>לא הביט און ביעקב</b>: בלק כג, כא."],["3415","108","<b>כנ\"ל</b>: במאמר שלפנ\"ז ד\"ה גדול יהי' על יד הערה 57."],["3416","109","<b>י\"ג מדה\"ר אל</b>: תשא לד, ו. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041347\" data-slug=\"likkutei-sichot\" data-id=\"1300041347\">לקו\"ש אלול כרך ד ע' 1348</a> ואילך. ובאג\"ק שלו ח\"ב ע' שסט ואילך. לקמן מאמר ד\"ה אני לדודי ובהערה 6."],["3417","110","<b>י\"ג מדה\"ר. . שלפני כל האצי'</b>: ראה גם אגה\"ת פ\"ח. מאמרי אדה\"ז תקס\"ה ח\"א ע' שצב. מאמרי אדה\"א דברים ח\"ג ע' תשטו. קונטרסים ע' של. בהערות הבאות."]]],[2000450332,"לידי גילוי מן ההעלם דהיינו שיומשכו מאין ליש והוא ע\"ד שיהי' נמצאים ממש בבחי' גילוי גם למטה בעולם האצי' כו'. וזהו ענין ב' שמות הוי' שלפני הזכרת י\"ג מדה\"ר באמרו ויעבור ה' על פניו<sup data-n=\"3418\">111</sup> ויקרא הוי' הוי' אל רחום כו' וידוע דפסיק טעמא בין הוי' להוי'<sup data-n=\"3419\">112</sup> כי הוי' הראשונה הוא הויות י\"ג מדה\"ר כמו שהן לפני האצי' בבחי' העלם<sup data-n=\"3420\">*113</sup> והאין כנ\"ל, והוי' הב' הוא הויות הי\"ג מדה\"ר גם למטה באצי' להיות נק' אל רחום ממש [ע' בד\"ה והי' ביום ההוא<sup data-n=\"3421\">113</sup> יתקע בשופר גדול ושם פ\"ד] כי הנה ידוע דאית חסד ואית חסד<sup data-n=\"3422\">114</sup> כו', דחסד שבאצי' הוא חסד סתם אבל חסד שבי\"ג מדה\"ר שנק' ורב חסד כשנמשכים מאין ליש בבחי' האצי' הנה אז הוא מוחל וסולח לעוונות וכמ\"ש נושא עון ועובר על פשע<sup data-n=\"3423\">115</sup> כו', שמפני מצד החסד הגדול שלפני ההשתלשלות אין כל ההשתל' דאבי\"ע תופסים מקום כלל ואם צדקת מה תתן לו כו' לכך נושא עון כו' וכמ\"ש במ\"א<sup data-n=\"3424\">116</sup>, ולכך כשמאיר הארה זו דרב חסד באצי' ג\"כ בבחי' גילוי אז<sup data-n=\"3425\">*117</sup> גם שנעשה פגם וחסרון ע\"י העון שם נתמלא ואינו פוגם כלל ולכך נא' אז דוקא לא הביט און ביעקב ולא ראה כו', ג\"כ שאינו רואה את העון להיות תופס מקום כלל מטעם הזה כו', כי ה' אלקיו עמו פי' עמו כי ממילא בא מלמעלה כנ\"ל ולכך הוא עמו ממילא והוא ע\"י בחי' הביטול דוקא והיינו דוקא ע\"י בחי' הסתכלות דז\"א בא\"א כנ\"ל דע\"ז נא' ואל זה אביט אל עני כו' לכך לא הביט און ביעקב להיות כי ההבטה זו באה בבחי' מקיף מלמעלה להקיף מכל צד ופינה כנ\"ל ואז ממילא לא הביט האון כו' כי אינו תופס מקום כלל כנ\"ל [ועמ\"ש ג\"כ בלק\"ת בשה\"ש בהביאור ע\"פ לבבתיני אחותי כלה ושם פ\"ב].\n<b>קיצור</b> ואת כל אלה ידי עשתה זהו תשב\"כ ע\"ש אלה החוקים ויהיו כל אלה נאום ה' זהו תשבע\"פ ושורשם זו\"נ דאצי', והנה יש נרנח\"י יחידה בכתר חד ולא בחושבן הרצון אור מקיף ולפי שאין להם כלים א\"א להמשיך בחי' זו ע\"י אתעדל\"ת ואעפ\"כ נמשך מאליו כאשר יש שלימות למטה באתעדל\"ת ואתעדל\"ע, ועמ\"ש במ\"א בענין מתנה טובה<sup data-n=\"3426\">117</sup> יש לי בבית גנזי ושבת שמה, מתנה דוקא, ומ\"מ אין נותנים המתנה אלא למי שטרח<sup data-n=\"3427\">118</sup> בע\"ש<sup data-n=\"3428\">119</sup>, והמשכה זו זהו ענין ואל זה אביט",[["3418","111","<b>ויעבור ה' על פניו</b>: תשא לד, ו."],["3419","112","<b>דפסיק טעמא בין הוי' להוי'</b>: זהר אד\"ר נשא קלח, רע\"א. ראה לעיל המשך אם כסף תלוה ספי\"ד ובהערה 320."],["3420","*113","<b>העלם</b>: במאמרי אדה\"ז תקס\"ה כאן: ההעלם."],["3421","113","<b>הוי' הראשונה. . והוי' הב'. . בד\"ה והי' ביום ההוא</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380955\" data-slug=\"likkutei-torah\" data-id=\"4001380955\">לקו\"ת ר\"ה נט, סע\"א</a> ואילך."],["3422","114","<b>דאית חסד ואית חסד</b>: זהר ויחי ריט, א. ראה אגה\"ק ס\"י. סי\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תשעז. וש\"נ."],["3423","115","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח. ראה גם לעיל המשך חייב אדם לברך פ\"ל על יד הערה 1167."],["3424","116","<b>וכמ\"ש במ\"א</b>: ראה גם לקמן מאמר ד\"ה זה עני על יד הערה 113 (ובהנסמן בריש המאמר שם). לקו\"ת שהובא בסמוך בפנים. וראה סה\"מ תרכ\"ז ע' תמג. תרל\"ב ח\"ב ע' תז ואילך."],["3425","*117","<b>אז</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תשיח: גמור."],["3426","117","<b>מתנה טובה</b>: שבת י, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381226\" data-slug=\"likkutei-torah\" data-id=\"4001381226\">לקו\"ת שה\"ש כד, ב</a>. סה\"מ תרל\"ו ח\"ב ע' שסד. לקמן מאמר ד\"ה אני לדודי על יד הערה 121."],["3427","118","<b>אין נותנים המתנה אלא למי שטרח</b>: ראה מגילה כו, ב. גיטין נ, ב. ב\"מ טז, א. ב\"ב קנו, א."],["3428","119","<b>למי שטרח בע\"ש</b>: ע\"ז ג, א."]]],[2000450333,"הסתכלות דע\"ק בז\"א<sup data-n=\"3429\">120</sup> ועי\"ז נמשך לו ש\"ע נהורין והבטה זו אל עני סיהרא, ונכה רוח שם מ\"ה ביטול, וזהו ענין הכריעות דשמו\"ע כורע בברוך ועי\"ז זוקף בשם שמחבר ב' השמות הוי' דע\"ק וז\"א ומזה נמשך לא הביט און ביעקב ע\"י המשכת י\"ג מדה\"ר ויקרא הוי' הוי' אל רחום וחנון כו'.\n<b>ועפ\"ז</b> יובן ענין השומרים שע\"ג החומה דירושלים, דהנה ירושלים הוא כמ\"ש כי מציון תצא תורה<sup data-n=\"3430\">121</sup> ודבר ה' מירושלים שזהו ב' בחי' דתושב\"כ ושבע\"פ, ב' הבחי' דידי עשתה ונאום הוי', והחומה זהו ענין השתחוואות דשמו\"ע בחי' הכנה לקבל המקיף, דהגם שהחומה שומר עכ\"ז אם ה' לא ישמור שוא<sup data-n=\"3431\">122</sup> כו', או י\"ל שזהו מהמקיפי' דנר\"נ שיש להם או\"מ ג\"כ כנ\"ל, והשומרים זהו בחי' המקיף דאו\"מ דח\"י כו' ולכן אמר זה בנחמה הז' שזהו בהפטרה דשוש אשיש, כי ז' דנחמתא י\"ל זהו נגד ז' מקיפי' שבמל', ומתחילי' נחמו כו' ומסיימי' שגם על החומה יומשך המקיף דיחידה עד אשר יכונן למטה כו'. ובעבודה י\"ל שכסדר המדרגו' צ\"ל ידי עשתה לימוד תושב\"כ שנק' עשי' מל' גט מעושה<sup data-n=\"3432\">124</sup> מל' כפי'<sup data-n=\"3433\">123</sup> והכרח שלכאו' נדמה לו הלא יודע הנא' בתושב\"כ ול\"ל ללמוד אבל באמת אינו כן שצריכים<sup data-n=\"3434\">125</sup> ללמוד בכ\"י תושב\"כ עפ\"י רש\"י<sup data-n=\"3435\">126</sup> שזהו<sup data-n=\"3436\">127</sup> תרומות מדרשי רז\"ל, ונאום הוי' תושבע\"פ כמ\"ש בה' ת\"ת<sup data-n=\"3437\">128</sup> ובאגה\"ק<sup data-n=\"3438\">129</sup> שלכה\"פ צריך כ\"א ללמוד מס' גמרא בשנה, ואם גם העביר את הדרך ולא למד עכ\"ז לא יאמר נואש שאין לך דבר שעומד בפני התשובה<sup data-n=\"3439\">130</sup>, בכל מאדך<sup data-n=\"3440\">131</sup> בחילא יתיר<sup data-n=\"3441\">132</sup>, שלמעלה מהגבלת הכלי וה\"ז הכנה שישרה עליו אור המקיף דח\"י בחי' שומרים הנ\"ל כו'.",[["3429","120","<b>הסתכלות דע\"ק בז\"א</b>: ראה זהר ויקרא טו, סע\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380812\" data-slug=\"likkutei-torah\" data-id=\"4001380812\">לקו\"ת ראה כד, א</a>-ב."],["3430","121","<b>כי מציון תצא תורה</b>: ישעי' ב, ג. ראה גם לקלו\"י הערות לתניא ע' יט."],["3431","122","<b>אם ה' לא ישמור שוא</b>: תהלים קכז, א [בדילוג]."],["3432","124","<b>גט מעושה</b>: גיטין פח, ב (במשנה)."],["3433","123","<b>עשי'. . כפי'</b>: ראה גם לקמן מאמר ד\"ה בראשית על יד הערה 17. מאמרי אדה\"א קונטרסים ע' ח. וש\"נ. אוה\"ת בחוקותי כרך ד ע' א'קסט. סה\"מ תרל\"ו ח\"ב ע' רפט. תער\"ב ח\"ב ס\"ע תתקטז. תרע\"ח ע' קכא. ע' קצב. תרצ\"ט ע' 191. ע' 197. (תש\"ח ע' 227). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291100\" data-slug=\"likkutei-sichot\" data-id=\"1300291100\">לקו\"ש שופטים כרך כט ע' 100</a> הערה 42."],["3434","125","<b>שצריכים. . בשנה</b>: נעתק ב”היום יום\" יח אדר שני. לקו\"ד ח\"ד ע' תקצח. סה\"ש תשנ\"ב ח\"ב ע' 476. רשימות חוב' קפד ע' 5."],["3435","126","<b>עפ\"י רש\"י</b>: ב”היום יום\" וברשימות: עם פירש\"י. בלקו\"ד ובסה\"ש: עם פרש\"י."],["3436","127","<b>שזהו</b>: בלקו\"ד ובסה\"ש: שהוא."],["3437","128","<b>בה' ת\"ת</b>: בסה\"ש מציין: רמב\"ם הל' ת\"ת פ\"א הי\"א-יב. טושו\"ע הל' ת\"ת יו\"ד סרמ\"ו ס\"ד. הל' ת\"ת לאדה\"ז רפ\"ב. ושם: חייב הוא לשלש זמן למידתו שבכל יום ויום שליש במקרא שליש במשנה כו' ושליש בתלמוד כו' וראה תוד\"ה לא — קידושין ל, א."],["3438","129","<b>ובאגה\"ק</b>: קו\"א ד\"ה הוכח תוכיח (תניא ע' קסג)."],["3439","130","<b>שאין לך דבר שעומד בפני התשובה</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061066\" data-slug=\"likkutei-sichot\" data-id=\"1300061066\">לקו\"ש בא כרך ו ע' 66</a> הערה 54."],["3440","131","<b>בכל מאדך</b>: ואתחנן ו, ה."],["3441","132","<b>בחילא יתיר</b>: לשון <a class=\"ft-cite\" href=\"#/read/torah-or/3901370030\" data-slug=\"torah-or\" data-id=\"3901370030\">תו\"א בראשית ח, א</a>. ועוד. זהר שמות ג, ב."]]],[2000450334,"<h3>ישמח משה במתנת כו'</h3>\n<b>בס\"ד ש\"פ עקב ל\"ח</b>\n<b>ישמח</b> משה<sup data-n=\"3442\">1</sup> במתנת חלקו<sup data-n=\"3443\">2</sup>, ופי' בסידור האריז\"ל<sup data-n=\"3444\">3</sup>, שאותם האלף אורות שנטלו ממשה בחטא העגל כמארז\"ל ע\"פ לך רד, רד מגדולתך כלום נתתי<sup data-n=\"3445\">4</sup> כו'. ולכאו' צ\"ל הלא משה אמר ונחנו מה<sup data-n=\"3446\">5</sup> שכפשוטו זהו מצד עבודת עצמו, ומ\"ע כלום נתתי כו' אלא כו'. וגם צ\"ל מ\"ש בני בכורי ישראל<sup data-n=\"3447\">6</sup>, וכתי' בנים אתם<sup data-n=\"3448\">7</sup>, וברא כרעא דאבוהא<sup data-n=\"3449\">8</sup> בחי' רגל, ושם ישראל מורה על לי ראש כמארז\"ל<sup data-n=\"3450\">9</sup>, וארז\"ל תפילין דמארי עלמא<sup data-n=\"3451\">10</sup> מה כתי' בהן<sup data-n=\"3452\">11</sup> ומי כעמך כישראל<sup data-n=\"3453\">12</sup> כו', שזהו בחי' המשכת מוחין דגדלות שבז\"א. והענין הוא דכתי' ואהבת וצ\"ל איך שייך ציוי על אהבה<sup data-n=\"3454\">13</sup> כו' אלא שהציוי",[["3442","1","<b>ישמח משה</b>: מאמר זה הוא דרוש השני (מההמשך) שמבאר שני פיסקאות (ד\"ה והנה שרש ענין שמע־ ועתה יש להבין) מביאור הראשון (על מאמר ד\"ה השמים כסאי) ד\"ה להבין שרשי הדברים הנ\"ל שנדפס במאמרי אדה\"ז תקס\"ה ח\"ב הנחת כ\"ק אדמו\"ר האמצעי ע' תשיח — תשכא (עד ד\"ה ובכל זה יובן). והוא דרוש הששי מההמשך שבו נתבארו הדרושים דהשמים כסאי וביאוריו שנאמרו בשנת תקס\"ה כמצויין לעיל ברד\"ה ואשא אתכם.\nהפתיחה נכתבה בבוך זה 1089. ורק ההגהות נרשמו בבוך 1162. אודות ביכלאך אלו ראה המצויין לעיל בריש ד\"ה ואשא אתכם.\nהמאמר (מלבד הפתיחה, וכן הערות שבתוך ההחצע\"ג שנכתבו בגוכתי\"ק) הוא לשון מאמרי אדה\"ז תקס\"ה הנ\"ל עם הגהות הצ\"צ שבאים בתוך חצאי ריבוע. וההגהות שבהחצע\"ג הם מכ\"ק אדמו\"ר מהר\"ש. והדברים המובאים בתוך חצאי עיגול שהם בתוך חצאי מרובע [( )] הם מכ\"ק אדמו\"ר האמצעי שנכתבו במאמרי אדה\"ז הנ\"ל בין חצאי עיגול.\nהמאמר מלבד הפתיחה נדפס בלקו\"ת לג\"פ ו, ג. אוה\"ת בראשית כרך ו ע' תתרלג ואילך פ\"ב (פרט להגהה הראשונה שנדפסה שם בע' 2064 בסופו, שגם היא נעתקה בבוך זה 1089 אלא שאח\"כ השמיטה). פ\"ג.\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות (ומשם נעתקה הכותרת שמופיע בריש המאמר — פרט לתיבת בס\"ד).\nמאמר זה נזכר לקמן בד\"ה בנים אתם על יד הערה 4."],["3443","2","<b>ישמח משה במתנת חלקו</b>: נוסח תפלת העמידה לשבת."],["3444","3","<b>ופי' בסידור האריז\"ל</b>: במקומו — ר\"ש רשקוב (ד\"ה משה). קול יעקב. ראה גם לעיל מאמר ד\"ה ומקנה רב הערה 49."],["3445","4","<b>לך רד. . כלום נתתי</b>: תשא לב, ז. ברכות לב, א. רש\"י תשא שם."],["3446","5","<b>ונחנו מה</b>: בשלח טז, ז. ח. ראה גם מאמרי אדה\"א בראשית ע' כב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540049\" data-slug=\"torat-chaim\" data-id=\"2300540049\">תו\"ח שמות ח\"א מג, א</a>. וש\"נ."],["3447","6","<b>בני בכורי ישראל</b>: שמות ד, כב."],["3448","7","<b>בנים אתם</b>: פ' ראה יד, א."],["3449","8","<b>וברא כרעא דאבוהא</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א בשם רז\"ל. מאמרי אדה\"א קונטרסים ע' שלט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550364\" data-slug=\"torat-chaim\" data-id=\"2300550364\">תו\"ח ויקהל ח\"ב שצו, א</a> הערה 118."],["3450","9","<b>ישראל. . לי ראש כמארז\"ל</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. לעיל המשך חייב אדם לברך פ\"ט הערה 274."],["3451","10","<b>תפילין דמארי עלמא</b>: ראה ברכות ו, א. ראה מאמר ד\"ה את הוי' האמרת ח\"י אלול תש\"ל הערה 10 [קונט' ח\"י אלול תשמ\"ז — סה\"מ מלוקט ב ע' פז]."],["3452","11","<b>בהן</b>: לקמן (בפנים בין הערות 86-7 וכן בהקיצור) ובברכות שם: בהו."],["3453","12","<b>ומי כעמך כישראל</b>: שמו\"ב ז, כג. בברכות שם הובא הכתוב דהי\"א יז, כא (ומי כעמך ישראל — וכ\"ה לקמן בפנים בין הערות 86-7). אבל כהנוסח דבפנים הובא גם ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381308\" data-slug=\"likkutei-torah\" data-id=\"4001381308\">לקו\"ת שה\"ש מה, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550347\" data-slug=\"torat-chaim\" data-id=\"2300550347\">תו\"ח יתרו ח\"ב רנט, ג</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תסז בהערה. אוה\"ת בהר כרך ד ע' א'קמד. סה\"מ תרל\"ב ח\"א ע' רפא."],["3454","13","<b>ואהבת. . ציוי על אהבה</b>: ואתחנן ו, ה. ראה גם לקו\"ת ואתחנן יא, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשלו ואילך (ובהנסמן שם ע' תשלז). הנחות תקע\"ז ע' שטז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670248\" data-slug=\"torat-chaim\" data-id=\"2300670248\">תו\"ח נח מט, ג</a> ובהנסמן במ\"מ לשם. ויקהל ח\"ב שצה, ג. וש\"נ. המשך והחרים תרל\"א ע' סו. סה\"מ תרכ\"ו ע' צד ואילך (ובהנסמן שם ס\"ע ). תרכ\"ז ע' עד. וש\"נ. תר\"ל ע' קמט. שיחת ש\"פ ויקהל ש\"מ אד\"ש תשמ\"ו."]]],[2000450335,"הוא על ההתבוננות, וענין ההתבוננות הוא בתי' שמע שם עיי\"ן והעיי\"ן הוא עיי\"ן רבתי<sup data-n=\"3455\">14</sup>.\n<b>ויובן</b> זה ע\"פ הידוע בע\"ח דשרש הז' מדות דאימא עילא' הוא הנק' ע' רבתי והוא בחי' ז\"ת דאימא<sup data-n=\"3456\">15</sup>, והענין הוא כך להיות ידוע דהתפעלות המדות חג\"ת כו' כמו שהן בלב הרי הן באים ונמשכי' מן השכל, ומי הוא הממשיך אותן מן השכל וההתבוננות הוא הדעת כי הוא המתפשט בהמדות להחיותן<sup data-n=\"3457\">16</sup> כידוע [(ולכך ימצא הרבה שינויי אופני ההתפעלות במדות מפעם לפעם והכל רק משכל והתבוננו' א' לפי שתלוי בדעת המוליד הולדת ההתפעלות כו')], והנה ההתפעלו' של המדות כבר היו בשכל<sup data-n=\"3458\">17</sup> והתבוננות אך שירדו מן ההעלם לגילוי בלב כי אנו רואים שיש התפעלות אהבה גם בשכל עדיין אך ורק שאיננה בגשמיות רק בבחי' הרוחניות של השכל הרוחני אבל מ\"מ בשם<sup data-n=\"3459\">18</sup> מדה היא נקראת אלא שהיא נק' מדה שבשכל דהיינו התפעלות השכל בחסד או התפעלות השכל לדין זהו הנק' חסד וגבורה שבבינה שבמוח כמו ב' תלמידים זה מטה כלפי חסד בשכלו וסברתו וזה נוטה כלפי גבורה כענין ב\"ש וב\"ה הללו מטין כלפי חסד כו' וכמ\"ש במ\"א [וע' מזה בסידור בדרושי החתונה בהביאור ע\"פ כי על כל כבוד חופה<sup data-n=\"3460\">19</sup> גבי ביאור ענין תפארת דאימא שנעשה כתר לז\"א ובשחרית דשבת<sup data-n=\"3461\">20</sup> ע\"פ אין אומר ואין דברים ובלק\"ת פ' מסעי<sup data-n=\"3462\">21</sup> בד\"ה לבאר ענין המסעות ושם פ\"ב גבי לא יחפוץ כסיל בתבונה כ\"א בהתגלות לבו]. ונמצא מובן שהמדות בהיותם עדיין בכח השכלי הן הנק' מדות שבשכל והוא בחי' ז\"ת דאימא ומהם מסתעפים הולדת הז' מדות בגילוי בלב הנק' גדולה וגבורה כו', ועל בחי' המדות שבשכל נא' לך הוי' הגדולה<sup data-n=\"3463\">22</sup>, לך בבחי' הביטול וההתכללות, לפי שהן כלולים בבחי' השכל וההתבוננו' עדיין ואינם ניכרים ליש ודבר ממהות",[["3455","14","<b>שמע שם עיי\"ן. . רבתי</b>: זהר פינחס רלו, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשמא ואילך. וש\"נ. סה\"מ תרל\"ג ח\"א ע' רב. וש\"נ. לעיל מאמר ד\"ה ואשא אתכם על יד הערה 82 ואילך."],["3456","15","<b>דשרש הז' מדות. . ז\"ת דאימא</b>: ראה גם לעיל מאמר ד\"ה ואשא אתכם על יד הערה 82 ואילך. שע\"ת קד, ד הערה 32."],["3457","16","<b>הדעת. . המתפשט בהמדות להחיותן</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 17 ואילך. מאמרי אדה\"ז אתהלך לאזניא ע' קעו. תקס\"ה ח\"א ע' רמט וע' רסז (נוסחא שני'). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680140\" data-slug=\"torat-chaim\" data-id=\"2300680140\">תו\"ח ויצא קע, סע\"ב</a>. משפטים ח\"ב רפב, ג. ויקהל תלח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' שנד."],["3458","17","<b>המדות כבר היו בשכל. . וכמ\"ש במ\"א </b>[במאמרי אדה\"ז תקס\"ה כאן ניתוסף: באריכות]: ראה גם סידור שחרית נג, א. שער הק\"ש עז, ג. כוונת המקוה קנז, ד. שער התקיעות רמד, ד. סדר הגדה רצה, א. ביאוה\"ז ויחי לו, ב. תשא נג, א. בלק קג, ב. ג. קד, א. ג. לקו\"ת ואתחנן יב, ד נעתק לעיל בהמשך חייב אדם לברך פ\"מ על יד הערה *1788. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיח ואילך. ע' תשיב. בהערות הבאות. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 16 ואילך."],["3459","18","<b>בשם</b>: במאמרי אדה\"ז תקס\"ה כאן: ליתא."],["3460","19","<b>בסידור בדרושי החתונה בהביאור. . חופה</b>: קל, ב."],["3461","20","<b>בסידור. . ובשחרית דשבת</b>: קפא, ב."],["3462","21","<b>ובלק\"ת פ' מסעי</b>: צ, א ואילך."],["3463","22","<b>לך הוי' הגדולה</b>: דהי\"א כט, יא."]]],[2000450336,"התפעלות מדה עדיין כו' [וע' בזהר פ' אמור דצ\"ב ע\"א שפי' כן הפסוק והי' שבעת ימים תחת אמו<sup data-n=\"3464\">23</sup> דכתי' לך ה' הגדולה והגבורה] [(והיינו לך לפי שהן הנק' חמשים<sup data-n=\"3465\">24</sup> שערי בינה<sup data-n=\"3466\">25</sup> כו')]. והנה בחי' ז\"ת דאימא הנ\"ל הוא הנק' ע' רבתי להיותם בבחי' גדלות והרחבה גדולה ברוחב ההתבוננות עצמה מפני שהבינה נקראת רחובות הנהר<sup data-n=\"3467\">26</sup> כידוע [ועמ\"ש מזה בלק\"ת פ' ואתחנן בד\"ה שמע ישראל ובד\"ה ואהבת את פ\"א ובסדור שער הק\"ש בד\"ה פתח ר' שמעון ואמר שמע ישראל]. (ויובן ביאור הדברים, דהנה בחי' מדות שבמוחין אם<sup data-n=\"3468\">27</sup> היות שנושאי' ע\"ע שם מדה עכ\"ז עיקרם הוא בחי' מוחי', וע\"ד שנת' במ\"א בענין שילוב ה' באד' ואד' בהוי' שהעיקר הוא אות הראשון, שגובר כו' כמ\"ש באריכות בכ\"ד וע' בדרושי ש\"ש בביאור שובה השני<sup data-n=\"3469\">28</sup>, וכמ\"כ יובן כאן שמאחר שבחי' הבינה היא בעצם בחי' מוח הבינה שענינה היא בחי' התרחבות, וכענין רחובות הנהר לגבי צמצום המעיין כ\"ה התרחבות הבינה לגבי בחי' ברק המבריק<sup data-n=\"3470\">29</sup> דחכ' כו', ולכן גם המדות שבה אם היות כי נופל עליהם ש' מדה עכ\"ז הנם בבחי' התרחבות כמו עצם הבינה כו'. אך לכאו' ענין הרוחב אינו שייך למה שהם באים בהתכללות כ\"א מיו\"ד, והצ\"ל שהם ז' רחבי' ומ\"ע<sup data-n=\"3471\">30</sup> ע' רבתי שרומז לז\"מ כ\"א כלולה מיו\"ד, אמנם באמת כל ענין ההתכללות זהו גם מצד ההרחבה, וכמו שהוא<sup data-n=\"3472\">31</sup> בר שכל רחב הנה מצד היותו בבחי' מוחין דגדלות יוכל לסבול היפוכו לגמרי, משא\"כ מי שמוחו קצר כו' אינו יכול לסבול היפוכו כלל, ועד\"ז הוא ענין ההתכללות שזהו מצד רוחב כלי המוחין דבינה שמחמת זה באים בהרחבה ובבחי' ההתכללות ג\"כ כו', שענינם אחד הוא כו'). [(ועוד לפי שהשבירה הי' בשם ס\"ג<sup data-n=\"3473\">32</sup> שבבינה<sup data-n=\"3474\">33</sup> כו'<sup data-n=\"3475\">34</sup> ולפני השבירה היו הז' מדות דבינה גדולים בהתפשטות ולכך נק' ע' רבתי והו\"ע ע' אומות<sup data-n=\"3476\">35</sup> למטה, וע' נפש דיעקב<sup data-n=\"3477\">36</sup> הוא התיקון שלהם כמ\"ש יצב גבולות עמים למספר בנ\"י<sup data-n=\"3478\">37</sup> כו')]. (וטעם זה הוא רק בחי' התפשטות לבד",[["3464","23","<b>והי' שבעת ימים תחת אמו</b>: אמור כב, כז."],["3465","24","<b>לך. . חמשים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550228\" data-slug=\"torat-chaim\" data-id=\"2300550228\">תו\"ח פקודי ח\"ב תמג, ד</a>. וש\"נ. בהערה הבאה."],["3466","25","<b>חמשים שערי בינה</b>: ר\"ה כא, ב. ראה גם שעה\"י קלא, ב ובהערה 34. סה\"מ תרכ\"ז ע' קעב. וש\"נ."],["3467","26","<b>שהבינה נקראת רחובות הנהר</b>: וישלח לו, ז. ראה זהר אד\"ר נשא קמב, א."],["3468","27","<b>אם</b>: ראה גם לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["3469","28","<b>שילוב ה' באד' ואד' בהוי'. . שובה השני</b>: ראה לקו\"ת ש\"ש סה, ד [ביאור לשובה הראשון]."],["3470","29","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לעיל המשך כי תשא פי\"ג ובהערה 358."],["3471","30","<b>והצ\"ל. . ומ\"ע</b>: באוה\"ת כאן ס\"ע תתרלג: והי' צ\"ל. . ומהו ענין."],["3472","31","<b>וכמו שהוא</b>: באוה\"ת כאן ר\"ע 2066: וכמו מי שהוא."],["3473","32","<b>שהשבירה הי' בשם ס\"ג</b>: ראה מבוא שערים ש\"ב ח\"א, פ\"א. מאמרי אדה\"א דברים ח\"ב ע' שעט. וש\"נ."],["3474","33","<b>ס\"ג שבבינה</b>: ראה ע\"ח שער הכללים פ\"ח. שער רפ\"ח ניצוצין שי\"ח, פ\"ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' שנג."],["3475","34","<b>כו'</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תשיט: דעקודים נקודים כו'."],["3476","35","<b>ע' אומות</b>: סוכה נה, ב. במד\"ר פ\"ט, יד. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380837\" data-slug=\"likkutei-torah\" data-id=\"4001380837\">לקו\"ת ראה ל, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380841\" data-slug=\"likkutei-torah\" data-id=\"4001380841\">לא, ב</a>."],["3477","36","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830020\" data-slug=\"or-hatorah-hb\" data-id=\"8158830020\">וע' נפש</a> דיעקב</b>: ויגש מו, כז. ראה זהר שמות ה, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300246\" data-slug=\"or-hatorah-hb\" data-id=\"8316300246\">אוה\"ת במדבר ע' כ</a>. ביאוה\"ז — להצ\"צ — יתרו כרך א ס\"ע רמו ואילך."],["3478","37","<b>יצב גבולות עמים למספר בנ\"י</b>: האזינו לב, ח."]]],[2000450337,"ולא התכללות כי בתהו לא הי' בהם ההתכללו' כ\"א התפשטות לבד. ולכן למעלה הם זמ\"ל<sup data-n=\"3479\">38</sup> לבד ולמטה נתהוה מזה ע', ועש\"ז הוא ע', והיותו רבתי שבשרשו הם זמ\"ל ז' מדות שבס\"ג שהם בבחי' ההתפשטות, משא\"כ מספר בנ\"י שהם ע' שזהו מצד ההתכללות ג\"כ כנ\"ל). [וע' זח\"ב פ' בשלח דס\"ב ע\"ב ע\"פ ויבאו אלימה ושם שתים עשרה עינות מים ושבעים תמרים וע' בלק\"ת פ' ראה בד\"ה וכל בניך למודי הוי' ושם פ\"ג ובהביאור פ\"ב] וכאשר הז' מדות שבבינה מתפשטי' למטה אין ההארה מהם רק בחי' שם והוא הארה שבבחי' האותיות והכלים בלבד [ע' מזה בתו\"א פ' יתרו בד\"ה זכור את יום השבת לקדשו דרוש הראשון גבי ונקרא אותיות מלשון תרגום ואתא<sup data-n=\"3480\">39</sup><sup data-n=\"3481\">45</sup> ובלק\"ת<sup data-n=\"3482\">40</sup> בד\"ה את שבתותי תשמורו ושם פ\"ב מענין שם]. [(ולהיות<sup data-n=\"3483\">41</sup> כי ידוע דרפ\"ח ניצוצין<sup data-n=\"3484\">42</sup> הוא שנפלו בעולם הבריאה מבחי' ע' רבתי הנ\"ל וידוע דבינה הוא שם ס\"ג והמל' הוא שם ב\"ן<sup data-n=\"3485\">43</sup> וע\"כ מספר הכולל דרפ\"ח ושם ב\"ן בהגיעם למטה הוא מספר שם<sup data-n=\"3486\">44</sup> )] (דקדק לומר לשון למטה הוא מספר שם, דכמו שהם למעלה הרי ש' ב\"ן עם בחי' הרפ\"ח ניצוצי' אינם בבחי' חיבור להחשב מספר אחד זע\"ז רק למטה הם מספר א' גימ' שם). וזהו שם ע' רבתי כלומר כי זהו מספר הבירורים דרפ\"ח עם שם ב\"ן כשעולים למעלה מעלה בשרש מקור חוצבם והוא בע' רבתי [ע' מזה בלק\"ת ד\"ה זאת חקת התורה ספ\"ב] והיינו עליות המל' בשרשה בז' מלכין קדמאין שנא' בהם לפני מלוך<sup data-n=\"3487\">47</sup> מלך<sup data-n=\"3488\">46</sup> כו' [וההתבוננו' בכ\"ז וכיוצא בזה זהו ענין בינה להבין דבר מתוך דבר<sup data-n=\"3489\">48</sup>, ועי\"ז נמשך להיות ואהבת בכל לבבך, וכתי' אם ישים אליו לבו<sup data-n=\"3490\">49</sup> רוחו ונשמתו אליו יאסוף, והמשכה זו זהו ענין השמים כסאי<sup data-n=\"3491\">50</sup> וע' זח\"ב פ' וארא דכ\"ז ע\"א בכל לבבך דא ימינא ושמאלא שהם חו\"ג לכן עי\"ז נמשך ג\"כ ההמשכה בבחי' אש ומים שהם חו\"ג<sup data-n=\"3492\">51</sup> שלשם נמשך התורה מבחי' אלפים שנה<sup data-n=\"3493\">52</sup> ואהי' שעשועים יום",[["3479","38","<b>זמ\"ל</b>: ראה לעיל המשך חייב אדם לברך פכ\"ג הערה 864."],["3480","39","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370311\" data-slug=\"torah-or\" data-id=\"3901370311\">תו\"א</a> פ' יתרו. . תרגום ואתא</b>: סט, ד ד\"ה והנה."],["3481","45","<b>שם)]</b>: הסוגר ניתוסף ע\"פ בוך 1162. במאמרי אדה\"ז תקס\"ה כאן־ ובבוך זה 1089: שם — בלי סוגר (וראה לעיל הערה 41). באוה\"ת כאן ע' 2066 מופיע הסוגר בסמוך אחרי תיבות: גימ' שם). )]. אבל לכאורה זהו טעוה\"ד כי הסוגר הבא זהו הגהת כ\"ק אדמו\"ר מהר\"ש. וראה לעיל בהערה 1 ד\"ה המאמר מלבד."],["3482","40","<b>ובלק\"ת</b>: בהר."],["3483","41","<b>[(ולהיות</b>: במאמרי אדה\"ז תקס\"ה כאן: ולהיות — בלי סוגר —. וראה בסמוך הערה 45."],["3484","42","<b>דרפ\"ח ניצוצין</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151537\" data-slug=\"likkutei-sichot\" data-id=\"1300151537\">לקו\"ש וישב כרך טו ע' 524</a> (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["3485","43","<b>והמל' הוא שם ב\"ן</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג. שעה\"י קמה, א. הערה 14."],["3486","44","<b>דרפ\"ח ושם ב\"ן. . שם</b>: פע\"ח שער הק\"ש ש\"ח, פ\"ט."],["3487","47","<b>לפני מלוך מלך</b>: במאמרי אדה\"ז תקס\"ה כאן: בחי' מל' דב\"ן דכתיב וימלוך וימת כו' וד\"ל."],["3488","46","<b>לפני מלוך מלך</b>: וישלח לו, לא."],["3489","48","<b>בינה להבין דבר מתוך דבר</b>: ראה חגיגה יד, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> פ\"ג. אגה\"ק סט\"ו (קכד, רע\"א). וראה גם סה\"מ תרכ\"ט ע' רטז. וש\"נ."],["3490","49","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["3491","50","<b>השמים כסאי</b>: ישעי' סו, א."],["3492","51","<b>אש ומים שהם חו\"ג</b>: ראה ס\"י פ\"א, מי\"א-יב ובמפרשים שם. לעיל המשך חייב אדם לברך פ\"ה הערה 122."],["3493","52","<b>התורה מבחי' אלפים שנה</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."]]],[2000450338,"יום<sup data-n=\"3494\">53</sup> כו', והנה ענין רוחו ונשמתו זהו המשכת הארה מבחי' חיה יחידה שהם בחי' מקיף עליון שאינו מתלבש בכלי כלל כנ\"ל<sup data-n=\"3495\">54</sup> ובחי' רוח ונשמה זהו המאיר בבחי' כלי ע\"י עסק התורה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ענין שמע שם ע' ע' רבתי היינו ז\"ת דאימא ששם הן אתוון רברבין<sup data-n=\"3496\">55</sup> בחי' לך ה' הגדולה והגבורה וההמשכה שנמשך מהמדות להחיות העולמות הוא רק בבחי' שם בהבראם בה' בראם<sup data-n=\"3497\">56</sup> ה' זעירא<sup data-n=\"3498\">57</sup>, שם העלאת ב\"ן ורפ\"ח לשורשם ע\"י אם ישים אליו לבו, להבין דבר מתוך דבר ואהבת בכל לבבך ימינא ושמאלא ועי\"ז רוחו ונשמתו אליו יאסוף, והמשכה זו זהו ענין השמים כסאי כו', אש ומים הם חו\"ג, וזהו וידבר ה' אל משה<sup data-n=\"3499\">58</sup> שהוא בבחי' מן המים משיתיהו<sup data-n=\"3500\">59</sup> כי גם שמים עיקרו מים והאש נרמז רק בשין<sup data-n=\"3501\">60</sup> ונק' תורת חסד ופיה פתחה בחכמה<sup data-n=\"3502\">61</sup> ששם ההמשכה בבחי' חסד כו', וזהו חכמות בנתה ביתה<sup data-n=\"3503\">62</sup> חצבה עמודיה שבעה במד\"ר ר\"פ ויהי ביום השמיני.</span>\n<b>והנה</b> המשכה זו דבחי' השמים כסאי זהו ע\"י ואהבת בכל לבבך וע\"י עסק התורה, ואח\"כ והארץ הדום רגלי זהו ע\"י מעשה המצות וע\"י ואהבת בכל נפשך, והענין כי פי' הדום רגלי הוא בחי' עליות המל' שנק' רגל<sup data-n=\"3504\">63</sup>, ועיין מענין עליות המל' בהביאור ע\"פ כי אתה נרי<sup data-n=\"3505\">64</sup> בענין ארוממך אלקי המלך, ולכאו' רגל הם בחי' נה\"י כמ\"ש בענין שלש רגלים תחוג לי<sup data-n=\"3506\">65</sup>, אך י\"ל כמו שהמל' נקראת",[["3494","53","<b>ואהי' שעשועים יום יום</b>: משלי ח, ל."],["3495","54","<b>כנ\"ל</b>: במאמר ד\"ה על חומותיך על יד הערה 50."],["3496","55","<b>ז\"ת דאימא. . אתוון רברבין</b>: ראה רמ\"ז ר\"פ ויקרא. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקכד ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"א ע' רפד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200012\" data-slug=\"or-hatorah-hb\" data-id=\"8159200012\">אוה\"ת ויקרא כרך ג' ע' תשכד</a>. סה\"מ תרכ\"ז ר\"ע שנ. ובהנסמן שם."],["3497","56","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["3498","57","<b>בהבראם. . ה' זעירא</b>: ראה זהר לך צג, א. אנציק' תלמודית מערכת ה כרך ח ע' לה הערה 121. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010122\" data-slug=\"or-hatorah-hb\" data-id=\"8159010122\">אוה\"ת</a> בראשית כרך ג ע' 1030 ספ\"ד. ר\"ע תקטז. בלק ע' תתקיט. ישעי' כרך ג' ע' א'ריח. מאמרי אדמו\"ר הצ\"צ תרט\"ו ע' רכה."],["3499","58","<b>וידבר ה' אל משה</b>: וארא ו, י."],["3500","59","<b>משה. . מן המים משיתיהו</b>: שמות ב, י."],["3501","60","<b>שמים עיקרו מים והאש. . בשין</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשנט הובא לקמן במאמר ד\"ה פי' פתחה בחכמה על יד הערה 60. ו(בחלק ההנחות) בהנחה שם על יד הערה 53. סה\"מ תרכ\"ז ע' קעא. תרכ\"ט ע' לב. תרל\"ג ח\"א ע' כג. ח\"ב ע' שסו."],["3502","61","<b>תורת חסד ופיה פתחה בחכמה</b>: ע\"פ משלי לא, כו."],["3503","62","<b>חכמות בנתה ביתה</b>: משלי ט, א."],["3504","63","<b>המל' שנק' רגל</b>: ראה גם (בנוסף על המצויין בפנים) סהמ\"צ להצ\"צ ז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ריז. מאמרי אדה\"א נ\"ך ע' תיב. המשך תער\"ב ח\"א ע' מד. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381301\" data-slug=\"likkutei-torah\" data-id=\"4001381301\">לקו\"ת שה\"ש מג, ב</a>."],["3505","64","<b>בהביאור ע\"פ כי אתה נרי</b>: תו\"א מקץ מא, ב."],["3506","65","<b>רגל. . נה\"י. . שלש רגלים תחוג לי</b>: משפטים כג, יד. ראה טעמי המצות להאריז\"ל ס\"פ משפטים. מאו\"א שהובא בסמוך בפנים. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 70. ד\"ה שלש רגלים על יד הערה 7. ד\"ה הנ\"ל שנדפס בהוספה על יד הערה 5. אוה\"ת משפטים ס\"ע א'קעד ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381279\" data-slug=\"likkutei-torah\" data-id=\"4001381279\">לקו\"ת שה\"ש לז, ד</a>."]]],[2000450339,"בכל ע\"ש המדה הנק' כל כמ\"ש הרמב\"ן פ' חיי שרה ע\"פ וה' ברך את אברהם בכל<sup data-n=\"3507\">66</sup> כן נקראת על שמו ג\"כ רגל וכ\"מ בזהר פ' וירא דקי\"ג א' ע\"פ רגלי חסידיו ישמור<sup data-n=\"3508\">67</sup> וע' במאו\"א אות ריש סעי' מ'<sup data-n=\"3509\">68</sup> שהמל' נק' רגל כי היא עומדת נגד<sup data-n=\"3510\">69</sup> הרגלים גם כי היא עיקר עמידתה נגד<sup data-n=\"3511\">70</sup> עקב דעתיקא עכ\"ל וע' פרד\"ס<sup data-n=\"3512\">*71</sup> ערך רגלים<sup data-n=\"3513\">71</sup> ג\"כ דהיינו במל', וכדי להבין ענין הדום רגלי, צ\"ל תחלה ענין הנז\"ל בפנים<sup data-n=\"3514\">*72</sup> שיש מעלה יתירה ברגל מה שאין בראש]. כי<sup data-n=\"3515\">72</sup> הנה עיקר<sup data-n=\"3516\">73</sup> ענין ההפרש בין עולם התהו לעולם התיקון<sup data-n=\"3517\">74</sup> ידוע להיות כי בעולם התהו עדיין אין שם בחי' פרצוף משא\"כ בתיקון שהוא בבחי' פרצוף והיינו שבבחי' התהו כל האורות הם זת\"ז כו' ובבחי' התיקון האורות כלולים זה בזה כו', וביאור הדברים הוא עד\"מ בפרצוף אדם הנה הכחות של הנפש קודם התלבשותן באברי הגוף הרי הראש עד\"מ למעלה לגמרי מהרגל<sup data-n=\"3518\">75</sup> [עמ\"ש מזה בת\"א פ' שמות<sup data-n=\"3519\">76</sup> בד\"ה מי שם פה לאדם] משא\"כ כשנכנסו ונתלבשו באברי הגוף אז מצד האברים שהם כלולים זמ\"ז כמו שידוע שיש גידי הראש ברגל וגידי הרגל בראש כו', גם הכחות מתכללים זמ\"ז בתכלית ההתכללות עד שנעוץ סופן בתחלתן<sup data-n=\"3520\">77</sup> ותחב\"ס מבלי שימצא בהן ראש וסוף כלל שהרי אנו רואים ששפע חיות המוח השכלי מתחזק כאשר ירפאו אבר הרגל ויעשו להראש רפואות ע\"י הרגל<sup data-n=\"3521\">78</sup> כו', ולהיות כן ימצא ג\"כ שיהי' מעלה ומדריגה יתירה באבר התחתון מה שבעליון אינו במציאות והעליון יושלם בפעולה זו ע\"י התחתון כמו פעולת ההליכה שלא יפעל הראש כלל גם כשירצה במוח שבראשו אך ע\"י הרגלים יפעול פעולת ההליכה ונמצא ע\"י הרגל הולך גם הראש מה שאין ביכולתו להלוך בעצמו והרי נק' הרגל ראש בבחי' זו והראש נק'",[["3507","66","<b>וה' ברך את אברהם בכל</b>: ח\"ש כד, א."],["3508","67","<b>רגלי חסידיו ישמור</b>: שמו\"א ב, ט. ראה לקמן (בחלק ההנחות) בההנחה כאן על יד הערה 73."],["3509","68","<b>מ'</b>: וכ\"ה באוה\"ת בראשית ע' תתרלד כאן. וכנשצ\"ל: ט — כבאוה\"ת משפטים ע' א'קעה."],["3510","69","<b>נגד</b>: כ\"ה גם באוה\"ת כאן. במאו\"א: כנגד."],["3511","70","<b>נגד</b>: כ\"ה גם באוה\"ת כאן. במאו\"א־ ובאוה\"ת משפטים: כנגד."],["3512","*71","<b>פרד\"ס</b>: באוה\"ת כאן: פרדס. אבל ראה לעיל המשך חייב אדם לברך פ\"ט ובהערה 293."],["3513","71","<b>פרד\"ס ערך רגלים</b>: בשעה\"כ שכ\"ג, פ\"כ."],["3514","*72","<b>הנז\"ל בפנים</b>: מאמר ד\"ה ומקנה רב על יד הערה 23 ואילך."],["3515","72","<b>כי</b>: במאמרי אדה\"ז תקס\"ה כאן: ועתה יש להבין שרש ענין השמים כסאי והארץ הדום רגלי כו' הנה שרש ענין הדום רגלי הוא בחי' עליי' המל' שנק' רגלי כו'. וראה לעיל בפנים על יד הערה 63."],["3516","73","<b>עיקר</b>: באוה\"ת כאן: ליתא."],["3517","74","<b>ההפרש בין עולם התהו לעולם התיקון</b>: ראה ע\"ח שער הכללים פ\"א. פ\"ב. שער דרוש עגוי\"ו ש\"א, ענף ד. שער טנת\"א ש\"ה, פ\"א. שער התיקון ש\"י, פ\"ה. וראה גם (בנוסף ל) מאמרי אדה\"ז תקס\"ה ח\"ב כאן ע' תשיט ואילך. ע' תשמח ואילך. ח\"א ע' קעט ואילך. תו\"א שבהערה 76. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380570\" data-slug=\"likkutei-torah\" data-id=\"4001380570\">לקו\"ת חוקת סג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380670\" data-slug=\"likkutei-torah\" data-id=\"4001380670\">מטות פז, א</a> ואילך. שה\"ש יט, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' סט ואילך. תקס\"ב ח\"א ע' קפט ואילך. מאמרי אדה\"א דברים ח\"ג ע' תתצד ואילך. תו\"ח שמות ח\"א מד, ג ואילך. סה\"מ תרכ\"ח ע' קסג ואילך. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 75."],["3518","75","<b>קודם התלבשותן. . מהרגל</b>: במאמרי אדה\"ז תקס\"ה כאן: מחולקים ומפורדים זמ\"ז הי' קודם כניסה שלהם לאברי הגוף ואין לו שייכות והתחברות עם חבירו."],["3519","76","<b>בת\"א פ' שמות</b>: נא, סע\"ד ואילך."],["3520","77","<b>שנעוץ סופן בתחלתן</b>: ראה ס\"י פ\"א, מ\"ז."],["3521","78","<b>הרגל</b>: במאמרי אדה\"ז תקס\"ה כאן ניתוסף: ולהרגל יעשה רפואות ע\"י הראש."]]],[2000450340,"סוף בפעולה<sup data-n=\"3522\">79</sup> זו ובפעולת ההשכלה שבמוח נק' הרגל סוף מה שיפעול סוף מעשה המכוין בהשכלתו כו' אמנם כלולים זמ\"ז ומה שיש בראש יש בסוף כי נעוץ סופן כו' וגם נעוץ תחלתן כו' וא\"כ אין כאן החלט<sup data-n=\"3523\">80</sup> גמור לראש וסוף מאחר שיש גם בהסוף בחי' שנחשב עי\"ז ראש<sup data-n=\"3524\">81</sup> [ע' מזה בד\"ה אתם נצבים היום כולכם<sup data-n=\"3525\">82</sup>], והנמשל מכ\"ז יובן למעלה שזהו עיקר ענין התיקון בבחי' פרצוף למעלה בעולם האצי' דהיינו מה שיהיו האורות ע\"י בחי' הכלים והאותיות הנק' אברים כלולים זמ\"ז בתכלית עד שהמוחין עליונים מקבלים מבחי' נה\"י ומשום שנעוץ תחב\"ס ונעוץ סופן כו', משא\"כ בחי' התהו שלפני התיקון היו האורות זה תחת זה פי' בבלתי התכללות זמ\"ז כלל<sup data-n=\"3526\">83</sup> אלא כאו\"א ענין בפ\"ע ומאחר שנשתלשל השפע בהם מאור לאור במדריגת עילה ועלול<sup data-n=\"3527\">84</sup> עד למטה מטה כו' כידוע הרי בהכרח הי' לפ\"ז שיהי' מי שהוא במדרגות ובשפלות היותר אחרון<sup data-n=\"3528\">85</sup> בהשתלשלו' היותר אחרון שישאר כך בשפלות ולא יעלה לעולם ובהיפוך שמי שהוא עליון במדריגה בסדר ההשתל' לא ירד לעולם כי הרי הן זת\"ז מבלתי התכללות זע\"ז כו', אבל ע\"י בחי' התיקון שהוא בחי' ההתכללות של האורות ע\"י הכלים נעשה העליון תחתון ותחתון עליון ויוכל הנמוך להתעלות והעליון יורד כי נעוץ כו'. [וע' מזה בסידור אחר עלינו לשבח בד\"ה ביאור למ\"ש בסש\"ב פנ\"ב וע' בסידור בד\"ה למנצח על השמינית גבי ועכ\"ז<sup data-n=\"3529\">86</sup> יובן מה שאנו רואים שהתינוק אע\"פ שיגדל מעט כו' לא יכול עדיין להלוך ברגליו כו' לפי ששרש ההילוך מגיע בבחי' עצמות הנפש כו'. וזהו ענין שכנס\"י נק' רגל ברא כרעא דאבוה ונק' ג\"כ ישראל לי ראש כי תפילין דמארי עלמא מאי כתיב בהו ומי כעמך ישראל גוי אחד בארץ כו' שבהם ועל ידם נמשך המוחין דגדלות לז\"א ע' זח\"ג ואתחנן דרס\"ב ע\"ב. ויובן ג\"כ ענין זה מענין משה שאמר לו הקב\"ה לך רד כלום נתתי לך גדולה אלא בשביל ישראל]. והנה<sup data-n=\"3530\">87</sup> טעם הדבר שהי' למשה אלף אורות ע\"י זכות בנ\"י דוקא יובן ע\"פ משל אור נר קטן המונח בקרקע הבית ולמעלה בגג הבית כנגדו ממש תלוי כלי מנורות זכוכית בהירה מאד הנה האור והשלהבת העולה מהנר הקטן שמונח למטה בקרקע<sup data-n=\"3531\">88</sup> בוקע ועולה עד הכלי מנורה של הזכוכית הבהירה שעומדת סמוך לגג וקורת הבית ומאירה אותה עד שהזכוכית להיותה מקבלת האור בכי טוב נתמלאה כולה אור מאותה האור שקיבלה מהנר הקטן<sup data-n=\"3532\">89</sup> שלמטה ואותו האור שהזכוכית מאירה מזה הוא בודאי אור בהיר מאד ומתפשט למרחק גדול, וא\"כ מאור קטן מאד יוצא אור גדול ע\"י סיבה זו שהונח האור הקטן למטה וטבע האור להתעלות",[["3522","79","<b>בפעולה</b>: שם ע' תשכ: בבחי'."],["3523","80","<b>החלט</b>: שם: בירור."],["3524","81","<b>גם בהסוף. . ראש</b>: שם: לכאו\"א בחי' ראש ובחי' סוף כו' וד\"ל."],["3525","82","<b>בד\"ה אתם נצבים היום כולכם</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380895\" data-slug=\"likkutei-torah\" data-id=\"4001380895\">לקו\"ת נצבים מד, א</a>."],["3526","83","<b>זמ\"ז כלל</b>: במאמרי אדה\"ז תקס\"ה כאן: כלל זמ\"ז."],["3527","84","<b>ועלול</b>: שם ניתוסף: מעילה לעילה."],["3528","85","<b>היותר אחרון</b>: שם: ליתא."],["3529","86","<b>בסידור. . ועכ\"ז</b>: שער המילה קמא, א."],["3530","87","<b>והנה</b>: במאמרי אדה\"ז תקס\"ה כאן ישנו קטע נוסף שלא הועתק כאן."],["3531","88","<b>בקרקע</b>: שם ע' תשכא: ליתא."],["3532","89","<b>מהנר הקטן</b>: שם: מן הנר."]]],[2000450341,"למעלה מעלה ובאותו מקום יש כלי טוב שיקבל האור ושיתפשט במרחב גדול כו'. והנמשל מובן למשכיל למעלה בהיות שאמר משה שש מאות אלף רגלי<sup data-n=\"3533\">90</sup> העם אשר אנכי בקרבו וא\"כ היו כנס\"י כולם רק בחי' נה\"י שבו שהרי קראם רגלי ואמר אשר אנכי בקרבו בבחי' ראש ומוחין כו'. והנה הגם שהיו<sup data-n=\"3534\">91</sup> לגבי משה רק כמו ערך<sup data-n=\"3535\">92</sup> הרגל לגבי הראש, אבל מ\"מ האיר נפשו ג\"כ מחמת הארת כללות כנס\"י<sup data-n=\"3536\">93</sup> במעשיהם כי נעוץ סופן בתחלתן וכנ\"ל שהראש ג\"כ יתעלה<sup data-n=\"3537\">94</sup> ע\"י הרגל כו'. ולכך היו עי\"ז אלף אורות במשה שהאיר בו מסיבת הארת כנס\"י דוקא, ומה שלא האירו אותן האלף אורות בכנס\"י עצמן הוא לפי שלא היו בבחי'<sup data-n=\"3538\">95</sup> הכלי שלהם ראוי לאותה ההארה הגדולה וכלי נשמת משה הי' ראוי לכך, ומפני שהי' להם לבחי' ראש ומוחין ע\"כ האירו בו דוקא ולא בישראל, וה\"ז ממש כמשל הנ\"ל בכלי נר קטן שעומדת למטה שהאור ממנו מאיר למעלה בכלי הזכוכית שמקבלת בכי טוב האור ההוא ומאירה בשפע רב ובאור הבהיר מאד כו', כך ישראל נמשלו לבחי' הנר הקטן למטה ונשמת משה עומד עליהם למעלה הרבה בגובה ומ\"מ מחמת כנס\"י דוקא הוא שהאירו בו אלף האורות ולכך ע\"י החטא שלהם נטלו ממנו כו', וכך<sup data-n=\"3539\">96</sup> הדוגמא מכ\"ז בכללות נש\"י ששרשם למעלה מבחי' מל' דאצי' שנק' רגל כידוע שבבחי' תיקון שלה נתקן למעלה בבחי' ראש ביתר שאת הרבה וכפי משל הנ\"ל שהראש מתחזק ע\"י הרגל [וכמארז\"ל בזמן שישראל עושים רצונו ש\"מ מוסיפי' כח בגבורה שלמעלה במד\"ר באיכה ע\"פ ויצא מן בת ציון<sup data-n=\"3540\">97</sup>, ועמ\"ש בלק\"ת בשה\"ש בד\"ה צאינה וראינה בנות ציון דרוש הראשון פ\"ב בפי' שאו ידיכם קדש וברכו את ה', והיינו כמשל הנ\"ל שהראש מתחזק ע\"י הרגל בתיקונו. ויובן זה עוד עפ\"י המבואר בפע\"ח בהקדמה שיש ב' מדרגות בע\"ס דאצי' הא' כמו שהן בתחלת אצילותן מהמאציל באו\"כ שנמשך להן מן המאציל המשכה תמידית לצורך קיומן העצמי ומה שיסתעף מהן בעולמות כדי סיפוקם בצמצום בלתי תוס' וריבוי מכמו שהן בעצם בתחלה כו'. והב' כאשר הן באים בתוספות דהיינו שנמשך להם בחי' גילוי אור מהמאציל בבחי' תוס' וריבוי אור יתר על המדה מכמו שהן מתחלת אצילותן מן המאציל כו', ותוס' וריבוי הזה הנה אינו בא רק מסיבת המעשה התחתונים בהעלאות מ\"נ כו', משא\"כ מדרגת עצמותם כמו שהן א\"צ למעשה התחתוני' אלא בתמידות יבוא להם שפעם ממילא כנ\"ל בשביל קיום העולמות כו'<sup data-n=\"3541\">98</sup> [הג\"ה, וע\"ש בפע\"ח בהקדמה<sup data-n=\"3542\">99</sup> דבחי' זו זהו הנק' בחי' יחוד וזיווג",[["3533","90","<b>שש מאות אלף רגלי</b>: ראה גם לעיל מאמר ד\"ה ומקנה רב ובהערה 53."],["3534","91","<b>שהיו</b>: במאמרי אדה\"ז תקס\"ה כאן: שהי' זכות בנ\"י כולם קטן מאד."],["3535","92","<b>רק כמו ערך</b>: שם: עצמו כדוגמת."],["3536","93","<b>כנס\"י</b>: שם: נש\"י."],["3537","94","<b>יתעלה</b>: שם: מתברר."],["3538","95","<b>היו בבחי'</b>: שם: הי' בחי'."],["3539","96","<b>וכך</b>: שם: וכל."],["3540","97","<b>במד\"ר באיכה ע\"פ ויצא מן בת ציון</b>: איכה א, ו. איכ\"ר פ\"א, לג. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600679\" data-slug=\"or-hatorah-hb\" data-id=\"8316600679\">אוה\"ת איוב כרך א ע' תרעט</a> ואילך."],["3541","98","<b>המבואר בפע\"ח. . כו'</b>: לשון מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשסא. הובא גם לקמן במאמר ד\"ה מה יפו על יד הערה 40 ואילך."],["3542","99","<b>בפע\"ח בהקדמה</b>: השוה חסד לאברהם מעין ראשון נהר ו."]]],[2000450342,"ר\"ל המתקת וביסום הגבורות בחסדים והמשכת והשפעת הדעת באלקות וזהו ומלאה הארץ דעה את ה'<sup data-n=\"3543\">100</sup> ונמשך מבחי' והאדם ידע את חוה<sup data-n=\"3544\">101</sup> אדם זהו תשב\"כ ידע את חוה זהו תושבע\"פ<sup data-n=\"3545\">102</sup> ע\"ש ולילה ללילה יחוה דעת<sup data-n=\"3546\">103</sup> ר\"ל ההשפעה מח\"ע בח\"ת, והנה בחי' היחוד הנ\"ל נק' הילוך כמ\"ש במאו\"א אות ה' סעי' יו\"ד, וזהו ענין מעלת הרגל שבה ועל ידה דוקא הוא ענין ההילוך דהיינו ע\"י הבירורי' שלמטה ממשיכים בחי' והתהלכתי בתוככם<sup data-n=\"3547\">104</sup> שהוא תוס' וריבוי האור מסוכ\"ע בממכ\"ע ע\"ד אני אענה את השמים<sup data-n=\"3548\">105</sup> והם יענו את הארץ כדפי' בזח\"ב יתרו דפ\"ה סע\"ב עכ\"ה].\n<span data-k=\"ks\"><b>קיצור.</b> ענין והארץ הדום רגלי זהו ע\"ד ארוממך אלקי המלך<sup data-n=\"3549\">106</sup> כי הנה ע\"י נעוץ סופן בתחלתן יש מעלה ברגל מה שמקבל הראש ממנו ולכן תפילין דמארי עלמא מאי כתיב בהו, כשעושים רצונו של מקום מוסיפים כח, וזהו כלום נתתי לך גדולה אלא, והיינו כי יש בע\"ס ב' בחי' הא' מה שיש להם חיות קצוב מהמאציל הב' מה שנמשך בהם תוס' אור והתוס' מרובה על העיקר, וזהו הנק' והתהלכתי בתוככם ונק' מדלג על ההרים<sup data-n=\"3550\">107</sup> ומקפץ על הגבעות, וזהו הנמשך ע\"י האתעדל\"ת מכנס\"י הנק' רגל וזהו ענין ההילוך ע\"י הרגל דוקא משא\"כ בהראש מצד עצמו.</span>",[["3543","100","<b>ומלאה הארץ דעה את ה'</b>: נסמן לעיל בהמשך חייב אדם לברך פכ\"ד הערה 883."],["3544","101","<b>והאדם ידע את חוה</b>: בראשית ד, א."],["3545","102","<b>אדם זהו תשב\"כ. . חוה זהו תושבע\"פ</b>: ראה לעיל המשך חייב אדם לברך פכ\"ו ובהערה 987."],["3546","103","<b>ולילה לילה יחוה דעת</b>: תהלים יט, ג."],["3547","104","<b>והתהלכתי בתוככם</b>: בחוקותי כו, יב."],["3548","105","<b>אני אענה את השמים</b>: נסמן לעיל המשך חייב אדם לברך ספל\"ב הערה 1295."],["3549","106","<b>ארוממך אלקי המלך</b>: תהלים קמה, א."],["3550","107","<b>מדלג על ההרים</b>: ע\"פ שה\"ש ב, ח."]]],[2000450343,"<h3>בנים אתם כו'</h3>\n<b>בס\"ד ש\"פ ראה ל\"ח</b>\n<b></b>עלית נה\"י כו' תחום שבת כו' צדקה תרומם גוי\nראה\n<b>בנים</b> אתם<sup data-n=\"3551\">1</sup> לה' אלקיכם<sup data-n=\"3552\">2</sup> לא תתגדדו ולא כו' כי עם קדוש אתה ובך כו' לעם סגולה<sup data-n=\"3553\">3</sup> כו' ונת\"ל שאם היות שברא כרעא<sup data-n=\"3554\">6</sup> כו' עכ\"ז הוא לי ראש כי בתיקון הסוף הוא ג\"כ ראש כמ\"ש במא' הקודמי'<sup data-n=\"3555\">4</sup>, ולכאו' צ\"ל במה שמזהיר כאן על מל\"ת והטעם כי בך בחר, ועם סגולה שלכאו' שזהו ע\"י עשה ול\"ת וכאן הזכיר רק ל\"ת לבד. אך הענין יובן בהקדם ענין הנ\"ל דאם<sup data-n=\"3556\">5</sup> היות שבתיקון גם הסוף הוא ראש מ\"מ הנה הרגל נשפל למטה מאד ולכן צריכים להגביה אותם, וזהו דכתיב והארץ<sup data-n=\"3557\">7</sup> הדום רגלי<sup data-n=\"3558\">8</sup> היינו שצ\"ל<sup data-n=\"3559\">9</sup> בחי' שרפרף שנק' הדום להרים ולהגביה בחי' הרגל הנ\"ל וזהו ענין אחר והוא משום דגם שנעוץ תחלתן בסופן כו'<sup data-n=\"3560\">10</sup> אבל מ\"מ בחי' הרגל ירד ונשתלשל מאד בירידות המדרגות למטה מטה כמשל מי שיושב על הכסא שרגליו יורדים ונשפלים למטה ביותר ויוכלו מחמת זה להתחלש כחם כו', וצריך שיגביהו אותם דהיינו לסעדם ולתמכם בשרפרף קטן כנ\"ל. כך הנמשל למעלה דכמו שירדה כנס\"י למטה בגופים גשמיים כו' (והיינו שכנס\"י הוא בחי' מל'<sup data-n=\"3561\">11</sup>, וכמ\"ש במ\"א שנק' כנס\"י ע\"ש שכונס אורות בחי' ישראל דלעילא בתוכה<sup data-n=\"3562\">12</sup>, ולכן המשילם שכמו כנס\"י שלמטה כ\"ה בבחי' כנס\"י דלעילא והיינו בבחי' המל'), כך בחי' מל' דאצי' למעלה יורדת למטה בבי\"ע להחיות רוח שפלים<sup data-n=\"3563\">13</sup> כו' בירידת המדרגות מאד עד להחיות",[["3551","1","<b>בנים אתם</b>: מאמר זה הוא דרוש השלישי (מההמשך) שמבאר ארבע פיסקאות (ד\"ה ובכל זה־ וזהו ג\"כ־ וזהו והארץ־ והנה לנגד) מביאור הראשון (על מאמר ד\"ה השמים כסאי) ד\"ה להבין שרשי הדברים הנ\"ל שנדפס במאמרי אדה\"ז תקס\"ה ח\"ב הנחת כ\"ק אדמו\"ר האמצעי ע' תשכא — תשכה (עד ד\"ה וכ\"ז בבחי'). והוא דרוש השביעי מההמשך שבו נתבארו הדרושים דהשמים כסאי וביאוריו שנאמרו בשנת תקס\"ה כמצויין לעיל ברד\"ה ואשא אתכם.\nמאמר זה (מלבד הפתיחה והסיום, וכן הערות שבתוך ההחצע\"ג שנכתבו בגוכתי\"ק) הוא לשון מאמרי אדה\"ז תקס\"ה הנ\"ל עם הגהות הצ\"צ שבאים בתוך חצאי ריבוע. וההגהות שבהחצע\"ג הם מכ\"ק אדמו\"ר מהר\"ש. ונדפס גם — בלי הפתיחה והסיום — בלקו\"ת לג\"פ ח, א. אוה\"ת בראשית כרך ו ע' תתרלה ואילך פ\"ד. פ\"ה.\nהפתיחה וכן הסיום נכתבו בבוך זה 1089. ורק ההגהות נרשמו בבוך 1162. אודות ביכלאך אלו ראה המצויין לעיל בריש ד\"ה ואשא אתכם.\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות (ומשם נעתקה הכותרת שמופיע בריש המאמר — פרט לתיבת בס\"ד)."],["3552","2","<b>בנים אתם לה' אלקיכם</b>: פ' ראה יד, א."],["3553","3","<b>כי עם קדוש. . סגולה</b>: שם יד, ב (בדילוג)."],["3554","6","<b>שברא כרעא</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א בשם רז\"ל. מאמרי אדה\"א קונטרסים ע' שלט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550364\" data-slug=\"torat-chaim\" data-id=\"2300550364\">תו\"ח ויקהל ח\"ב שצו, א</a> הערה 118."],["3555","4","<b>ונת\"ל. . במא' הקודמי'</b>: ד\"ה ומקנה רב וד\"ה ישמח משה."],["3556","5","<b>שאם. . דאם</b>: כ\"ה בכ\"מ — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["3557","7","<b>והארץ</b>: מכאן ועד לקמן על יד הערה 20. הוא לשון [ביאור שני] מאמרי אדה\"ז תקס\"ה כאן ע' תשסב"],["3558","8","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["3559","9","<b>היינו שצ\"ל</b>: במאמרי אדה\"ז תקס\"ה: פי' שיש."],["3560","10","<b>שנעוץ תחלתן בסופן כו' </b>[תיבת כו': ליתא במאמרי אדה\"ז תקס\"ה]: ראה ס\"י פ\"א, מ\"ז."],["3561","11","<b>שכנס\"י. . מל'</b>: ראה זהר בלק קצז, א."],["3562","12","<b>כנס\"י ע\"ש שכונס. . בתוכה</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה אם בחוקותי ובהערה 38."],["3563","13","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."]]],[2000450344,"ג\"כ שרים<sup data-n=\"3564\">14</sup> דנוגה דעשי' ויוכל להיות שם יניקת הקליפות ביותר וכמ\"ש רגליה יורדות כו'<sup data-n=\"3565\">15</sup> [וע' מזה בזהר ויחי דרכ\"א ע\"ב ובפ' בשלח דמ\"ח<sup data-n=\"3566\">16</sup> ועיין מזה בסדור בד\"ה מזמור לתודה<sup data-n=\"3567\">17</sup> ועיין מזה בזח\"ב פקודי דרמ\"א ע\"א<sup data-n=\"3568\">18</sup> שלכן צריך להרגלים העלאה והגבהה למעלה באיזה סעד בכדי שלא ירדו בחי' הרגלים למטה כ\"כ, וזהו ענין השרפרף הנק' הדום רגלי כו' והוא בחי' המצות שנק' ארץ<sup data-n=\"3569\">19</sup> (שכללותה היא הצדקה כמ\"ש וצדקה תהי'<sup data-n=\"3570\">20</sup> כו' כל המצוה, שעי\"ז תתרומם כנס\"י כמ\"ש) וצדקה תרומם<sup data-n=\"3571\">21</sup> וכן ע\"י תושבע\"פ וזהו ע\"ד] מ\"ש<sup data-n=\"3572\">22</sup> בע\"ח שבהיות תיקון<sup data-n=\"3573\">23</sup> הנוק' קיפל א\"א את רגליו כו' [כמ\"ש בע\"ח שער ז\"א פ\"ב<sup data-n=\"3574\">24</sup> ושער הכללים פ\"ב]. פי' כי הנה ידוע דבדרך כללות ההשתל' נק' בי\"ע הדום רגליו דא\"א לפי שבחי' נה\"י דא\"א ודע\"י מתלבשים בבי\"ע<sup data-n=\"3575\">25</sup> וכאשר נה\"י מתעלים ונכללים בחג\"ת וחג\"ת מתעלים ונכללי' בחב\"ד כו' זהו שרש בחי' ענין התיקון כו' והיינו מ\"ש דא\"א קיפל את רגליו כו' [וצ\"ע דבסידור סד\"ה למנצח על השמינית כתב<sup data-n=\"3576\">26</sup> והנה הגם שיש פרסא בין כל עולם ועולם כו' וא\"א דאצי' מסתיים נה\"י שבו בפרסא שבין אצי' לבריאה כו', אבל בחי' נה\"י דא\"ק מגיעים עד סוף העשי' וכ\"כ בת\"א פ' משפטים<sup data-n=\"3577\">27</sup> בהביאור ע\"פ ותחת רגליו כמעשה לבנת הספיר וז\"ל והפרצופי' דעגולים ויושר מסתיימים לפני הפרסא שבין אצי' לבריאה אלא שנה\"י דא\"ק בוקע את הפרסא ומתלבשים בבי\"ע כי ענין א\"ק הוא מחשבה אנא אמלוך<sup data-n=\"3578\">28</sup> כו', יעו\"ש. וא\"כ צ\"ע מש\"כ שנה\"י דא\"א מתלבשים",[["3564","14","<b>שרים</b>: במאמרי אדה\"ז תקס\"ה כאן: ע' שרים."],["3565","15","<b>וכמ\"ש רגליה יורדות כו'</b>: משלי ה, ה. במאמרי אדה\"ז תקס\"ה כאן באים תיבות אלו במוסגר."],["3566","16","<b>דמ\"ח</b>: ע\"ב."],["3567","17","<b>בסדור בד\"ה מזמור לתודה</b>: שחרית מה, א ואילך. וראה גם פיה\"מ צה, ד ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600564\" data-slug=\"or-hatorah-hb\" data-id=\"8316600564\">אוה\"ת משלי כרך א ע' תקסד</a> ואילך."],["3568","18","<b>בזח\"ב פקודי דרמ\"א ע\"א</b>: ראה לעיל במאמר ד\"ה ומקנה רב על יד הערה 101. לקמן מאמר ד\"ה מה יפו על יד הערה 57."],["3569","19","<b>המצות שנק' ארץ</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370003\" data-slug=\"torah-or\" data-id=\"3901370003\">תו\"א בראשית א, ב</a>. ג. לקמן בפנים בין הערות 106-107. מאמר ד\"ה מה יפו על יד הערה 13. ד\"ה בראשית על יד הערה 35. ד\"ה שלש רגלים (בהוספה) על יד הערה 15. לעיל מאמר ד\"ה ומקנה רב — פיסקא והנה להיות. מאמרי אדה\"א ויקרא ח\"ב ע' תרטז."],["3570","20","<b>המצות. . וצדקה תהי'</b>: ואתחנן ו, כה. ראה לקמן מאמר ד\"ה מה יפו על יד הערה 78. ד\"ה בראשית על יד הערה 16. ו(בחלק ההנחות) בהנחה ד\"ה ומקנה רב על יד הערה 125. ד\"ה בנים אתם על יד הערה 55. מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540914\" data-slug=\"torat-chaim\" data-id=\"2300540914\">תו\"ח שמות ח\"א יד, א</a> ובהערה 628."],["3571","21","<b>וצדקה תרומם</b>: משלי יד, לד [ושם צדקה — אבל כ\"ה גם לעיל בהמשך כי תשא פט\"ו ובהערה 378]."],["3572","22","<b>מ\"ש</b>: מכאן מתחיל מאמרי אדה\"ז תקס\"ה כאן ע' תשכא."],["3573","23","<b>תיקון</b>: במאמרי אדה\"ז תקס\"ה כאן: בחי' תיקון."],["3574","24","<b>קיפל א\"א. . פ\"ב</b>: שם כ' אסף והכל א' — <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450606\" data-slug=\"or-hatorah-hb\" data-id=\"8316450606\">אוה\"ת עקב ע' תרו</a>. ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 32."],["3575","25","<b>בבי\"ע</b>: במאמרי אדה\"ז תקס\"ה כאן ניתוסף: (ובכל שבת שיש עליי' לכל ההשתל' נאמר אם תשיב משבת רגליך כו')."],["3576","26","<b>דבסידור. . כתב</b>: שער המילה קמא, סע\"ב ואילך."],["3577","27","<b>בת\"א פ' משפטים</b>: עח, ב. וראה גם אוה\"ת אוה\"ת בלק ע' תתקעג [נדפס גם באוה\"ת על ענינים ס\"ע פט, ואילך]."],["3578","28","<b>אנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ע' ז: וכמ\"ש בזהר בפי' וימלוך אנא אמלוך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד."]]],[2000450345,"בבי\"ע, ואולי זה הי' קודם התיקון שקיפל א\"א את רגליו. ואיך שיהי' מ\"מ הענין נכון וכמ\"ש בביאור שע\"פ ותחת רגליו כי מ' דאצי' נעשה עתיק לבריאה<sup data-n=\"3579\">29</sup> כו', וא\"כ מובן ממילא שבחי' בי\"ע שנחלקים לג' מדרגות חב\"ד חג\"ת נה\"י חב\"ד מאירים בבריאה וחג\"ת ביצי' כו' כולן אינן אלא בחי' נה\"י דאצי' לפי שבחי' נה\"י דז\"א דאצי' כולל כל בחי' הע\"ס דמל' חב\"ד חג\"ת נה\"י המתלבשי' בבי\"ע כו', וזהו ענין ותחת רגליו כמעשה כי עד\"מ הרגלים יורדים למטה מבחי' כסא הכבוד כו', והיינו שנמשכים בבי\"ע וכנ\"ל, וא\"כ א\"ש מ\"ש כאן שבחי' נה\"י מתלבשים בבי\"ע, וע' בלק\"ת<sup data-n=\"3580\">30</sup> מהרח\"ו ז\"ל פ' בשלח במצות תחומין וז\"ל והענין כי בשבת נכללים ג' תחתוני'<sup data-n=\"3581\">31</sup> נה\"י ועולין במקום ג' אמצעים חג\"ת<sup data-n=\"3582\">32</sup> כו' ע\"ש. וזהו ענין אם תשיב משבת רגליך<sup data-n=\"3583\">33</sup> כדי להעלות בחי' נה\"י וע' בזח\"ב פ' בשלח דמ\"ז ע\"א ודס\"ג סע\"ב.\n<span data-k=\"ks\"><b>קיצור.</b> לבאר ענין הדום רגלי ע\"ד שבשבת הוא עליות נה\"י למקום חג\"ת וזהו ענין תחום שבת תחום אותיות חותם<sup data-n=\"3584\">34</sup> עמ\"ש בענין חותם בברוך בד\"ה ענין הברכות<sup data-n=\"3585\">35</sup>].</span>\n<b>וביאור</b> הדברים. הנה עד\"מ כשהאדם אוכל מאכל גשמי יתחזק כח ההילוך ברגלים והחי נושא את עצמו<sup data-n=\"3586\">36</sup> שיוכל לנשאות כל גופו ביתר שאת [משא\"כ אם לא אכל ימים הרבה]<sup data-n=\"3587\">37</sup> וממילא יתחזק גם כח השכל שבמוח דהיינו שיוכל להתפלל בכוונה ולהגביה גם חומריות<sup data-n=\"3588\">38</sup> מדת גופו הבהמית ע\"י ההתבוננות בשכלו וזהו מחמת כח האכילה שאכל א\"כ ה\"ז מסיבת הבירורים שנתברר המאכל ונהפך לחיות בלב ומוח כידוע [וכמ\"ש באליהו וילך בכח האכילה ההיא במ\"א סי' י\"ט ט']. וכמו\"כ למעלה מסיבת העלאת הבירורים דלבושי' דנוגה שמתבררים מהן הרפ\"ח ניצוצים<sup data-n=\"3589\">39</sup> כו' נתחזק ונתעלה הכח האלקי שהוא בבחי' אצי' היותר אחרון והוא בחי' נה\"י דאצי'<sup data-n=\"3590\">40</sup> שמתלבש בבי\"ע ע\"ד החי נושא את עצמו כנ\"ל מבלתי יפול גם מהחיצוניות ללבושי' והיכלות דקליפה ולא יהי'<sup data-n=\"3591\">41</sup> רגלי' יורדות כו' [ועמ\"ש במ\"א בענין מה יפו פעמיך בנעלים<sup data-n=\"3592\">42</sup>] מאחר שנתעלו בחי' נה\"י דקדושה, והיינו ע\"י ענין",[["3579","29","<b>מ' דאצי' נעשה עתיק לבריאה</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב."],["3580","30","<b>בלק\"ת</b>: בטעמי המצות. ראה גם לקמן מאמר ד\"ה מה יפו על יד הערה 70 ואילך. ד\"ה בראשית על יד הערה 39 ואילך."],["3581","31","<b>תחתוני'</b>: שם: תחתונות."],["3582","32","<b>חג\"ת</b>: שם: ליתא."],["3583","33","<b>אם תשיב משבת רגליך</b>: ישעי' נח, יג. ראה פע\"ח שבהערה הבאה. שם שער השבת שי\"ח, פ\"י."],["3584","34","<b>תחום אותיות חותם</b>: טעהמ\"צ (לקו\"ת) כאן. פע\"ח הקדמה לשער השבת שי\"ח, פ\"א."],["3585","35","<b>בד\"ה ענין הברכות</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370024\" data-slug=\"torah-or\" data-id=\"3901370024\">תו\"א בראשית ו, ג</a>. לעיל המשך חייב אדם לברך פל\"ד."],["3586","36","<b>והחי נושא את עצמו</b>: שבת צד, א."],["3587","37","<b>[משא\"כ. . הרבה]</b>: במאמרי אדה\"ז תקס\"ה ע' תשכב כאן: משא\"כ. . הרבה."],["3588","38","<b>חומריות</b>: שם: את חומריות."],["3589","39","<b>הרפ\"ח ניצוצים</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151537\" data-slug=\"likkutei-sichot\" data-id=\"1300151537\">לקו\"ש וישב כרך טו ע' 524</a> (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["3590","40","<b>דאצי'</b>: במאמרי אדה\"ז תקס\"ה כאן: דא\"א דאצי'."],["3591","41","<b>ולא יהי'</b>: שם: כמ\"ש."],["3592","42","<b>מה יפו פעמיך בנעלים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381303\" data-slug=\"likkutei-torah\" data-id=\"4001381303\">לקו\"ת שה\"ש מג, ד</a>."]]],[2000450346,"הדום רגליו שהוא כמשל השרפרף שמגביה את הרגלים כו' וזהו ע\"י הבירורים דרפ\"ח כו' שע\"י המצות מעשיות כמשי\"ת בסמוך. והיינו והארץ הדום רגלי וענין עליות הרגלים באמרו קיפל את רגליו<sup data-n=\"3593\">43</sup> היינו שמתעלים בחג\"ת וחג\"ת בחב\"ד. והענין [מה<sup data-n=\"3594\">44</sup> שצ\"ל הדום רגליו היינו כדי שלא יתפשטו יותר מדאי במקום החיצוני' כמובן ממ\"ש בזח\"ב פ' פקודי דרמ\"א ע\"א בפי' והארץ הדום רגלי, וע' מזה בכה\"ג בבה\"ז פ' קרח על המאמר שם דקע\"ח ע\"א בשעתא דבעי יומא לאתקדשא הוו נפקין<sup data-n=\"3595\">45</sup> רוחיהון דשדין כו' ואתקדש יומא ולא אתבריאו וזהו ע\"ד הדום רגלי וע' מזה בזח\"א פ' בראשית בסוף ההקדמה דף י\"ד ע\"א], ויובן זה עד\"מ<sup data-n=\"3596\">46</sup> בהיות שאנו רואים שע\"י המאכל או בעסקו במו\"מ כל היום מפני שמתגשם הרבה עי\"ז העסק או ע\"י האכילה הגסה הנה יוכל להיות שאע\"פ שבשעת התפלה הי' מתפלל בכוונה שלימה בנקודת הלב באהוי\"ר מן רוחב ההתבוננו' כו' עכ\"ז בעת העסק במו\"מ נעשה נפרד לגמרי מיחודו ואחדותו ודביקותו ונשאר בהבלי עוה\"ז כשאר אנשי העולם ממש ואין זה רק מפני שבשעת התפלה הי' גילוי השכל וההתבוננו' מאיר בתכלית והמדות אהוי\"ר היו כלולים בהתכללות בתכלית ההתבוננו' והיו לאחדים ואחר התפלה הוא שנפרדו המדות מן השכל מפני שנסתלק מהם השכל ונשארו המדות בבחי' הפירוד למטה ואז ממילא מתלבשי' בענינים גשמיים ונעשה כשאר אנשי העולם, משא\"כ בשעת התפלה שהי' עליות המדות בשכל כו' [ועמ\"ש בסידור<sup data-n=\"3597\">47</sup> בפי' הללו יה להמשיך המוחין הנק' י\"ה בהמדות ובלק\"ת ד\"ה ראה אנכי נותן פ\"ג וע' בת\"א פ' וישב<sup data-n=\"3598\">48</sup> בד\"ה שיר המעלות בשוב ה' את שיבת ציון היינו כחולמים ועמ\"ש במ\"א בענין יוסף שהי' פותר חלומות<sup data-n=\"3599\">49</sup> שלא להיות בבחי' היינו כחולמים כו'], וא\"כ עיקר הסיבה בנפילה וירידה למטה הוא רק מפני בחי' הפירוד המדות מהשכל<sup data-n=\"3600\">50</sup>, אבל בבחי' העלייה והוא התכללות לא הי' ירד לעולם למטה כו', ועד\"מ זה יובן ג\"כ למעלה דהלא ידוע דו' ימי המעשה בבחי' האצי' הוא רק בחי' נה\"י בעיקרן ושרשן בלבד והוא בחי' שפע האלקי' שיורד להתלבש למטה בעשרה מאמרות להבראות יש מאין שהוא כמשל העשי' מיד האדם וכדומה כו' ובחי' חג\"ת דאצי' מתלבשים ומתעלמים תוך נה\"י הללו ובחי' חב\"ד מתעלמי' בחג\"ת כו' ולכך נק' בזהר תלת גו תלת<sup data-n=\"3601\">51</sup> כו' והוא ע\"פ",[["3593","43","<b>רגליו</b>: במאמרי אדה\"ז תקס\"ה כאן ניתוסף: (וכענין הכתוב וישא יעקב רגליו ארצה בני קדם כו' כידוע)."],["3594","44","<b>היינו שמתעלים. . והענין [מה</b>: בבוך 1162: [היינו. . והענין מה. והחצי ריבוע שקודם תיבת מה נמחק. וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450566\" data-slug=\"or-hatorah-hb\" data-id=\"8316450566\">אוה\"ת כאן ע' תתרלו</a> — התיבות: היינו. . והענין מובא במאמרי אדה\"ז תקס\"ה כאן — אבל כן הוא בבוך זה 1089. וראה גם לקמן הערה 118."],["3595","45","<b>בשעתא דבעי. . נפקין</b>: בזהר [וכן הובא לעיל במאמר ד\"ה ומקנה רב על יד הערה 104] בההיא שעתא דבעא. . נפקי. בביאוה\"ז שם צד, ד: בההיא שעתא דבעי. . נפקין."],["3596","46","<b>ויובן זה עד\"מ</b>: במאמרי אדה\"ז תקס\"ה כאן: והענין יובן עפ\"י משל — ראה הערה 48."],["3597","47","<b>ועמ\"ש בסידור</b>: שחרית נו, ב ואילך."],["3598","48","<b>בת\"א פ' וישב</b>: כח, ד."],["3599","49","<b>בענין יוסף שהי' פותר חלומות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770136\" data-slug=\"or-hatorah-hb\" data-id=\"8316770136\">אוה\"ת שה\"ש ח\"ב ע' תקב</a>. (יהל אור) תהלים ע' תצב. מקץ כרך ו ע' תתשג."],["3600","50","<b>המדות מהשכל</b>: במאמרי אדה\"ז תקס\"ה כאן: ליתא."],["3601","51","<b>תלת גו תלת</b>: ראה זהר תוספתא בשלח נ, סע\"א. ע\"ח שער הכללים פ\"ג. ביאוה\"ז בשלח מז, ג ואילך. שעה\"י קל, ב הערה 18."]]],[2000450347,"סדר הידוע דהנצח ענף החסד<sup data-n=\"3602\">52</sup> והחסד ענף החכמה<sup data-n=\"3603\">53</sup> בקו הימין<sup data-n=\"3604\">54</sup> ועד\"ז בקו השמאל אבל עיקר הגילוי למטה אינו אלא בחי' נצח והוד כו', ולהיות כן גם את זה לעו\"ז עשה האלקי'<sup data-n=\"3605\">55</sup> כו' והן היכלות נוגה דבי\"ע כו' [כי מנה\"י לפי שהם לבר מגופא ושם הביטול מועט יותר משם יוכל להיות יניקה כמ\"ש כי לא יכול לו<sup data-n=\"3606\">57</sup> ויגע בכף יריכו כמ\"ש מזה בד\"ה ויאבק איש עמו<sup data-n=\"3607\">58</sup> ובלק\"ת בד\"ה אלה מסעי דרוש השני פ\"ב] אבל לא כן<sup data-n=\"3608\">59</sup> כשבחי' נה\"י הללו שנק' ו' ימי המעשה עולין ונכללין בבחי' חג\"ת דאצי'<sup data-n=\"3609\">60</sup> הרי אז לא יש שום יניקה מבחי' נה\"י<sup data-n=\"3610\">61</sup> כי גם<sup data-n=\"3611\">62</sup> אז לא ימצאו במדות חג\"ת ג\"כ שום בחי' פירוד כלל שמסיבתו ירד השפע למטה מטה כ\"כ שהרי גם חג\"ת מתעלים ונכללים עד\"ז בבחי' חב\"ד כו' [וזהו ע\"ד שהשם שלם ע' בלק\"ת<sup data-n=\"3612\">63</sup> ד\"ה ראה אנכי נותן] וא\"כ ה\"ז כמשל המדות אהוי\"ר בעת התפלה שמפני שנכללים ועולים בחב\"ד לא ירדו ויפלו למטה בענין עשי' גשמי' כו' כנ\"ל במשל.\n<b></b>[קיצור. אך צ\"ל שרפרף לבחי' רגל שלא יהי' ח\"ו בבחי' רגליה יורדות אלא כמ\"ש רחצתי את רגלי<sup data-n=\"3613\">64</sup> ע' בתרגום שם ואנא קדשת<sup data-n=\"3614\">65</sup> ית רגלי ע\"י וצדקה תרומם וע\"י תושבע\"פ, וע\"ד המבואר במד\"ר תצוה פל\"ו<sup data-n=\"3615\">66</sup> ע\"פ נר לרגלי דבריך וכ\"ה בילקוט בתלים<sup data-n=\"3616\">67</sup> סי' קי\"ט ע\"פ נר לרגלי וע\"פ הקבלה זהו ענין שכדי להיות עולם התיקון קיפל א\"א את רגליו וע\"ד ענין תחום שבת לפי שבשבת הוא עליות נה\"י לחג\"ת וחג\"ת בחב\"ד<sup data-n=\"3617\">68</sup> הפך ענין היינו כחולמים וזהו ענין שתכלה רגל מן השוק<sup data-n=\"3618\">69</sup> מבחי' טורי דפרודא<sup data-n=\"3619\">70</sup> ג\"כ ע\"י בחי' נר לרגלי כו'].",[["3602","52","<b>דהנצח ענף החסד</b>: ראה זהר רע\"מ פינחס רמג, סע\"א. הנסמן במאמרי אדה\"א קונטרסים ע' רכח."],["3603","53","<b>והחסד ענף החכמה</b>: ראה זהר ואתחנן רסב, סע\"א. לך צד, א. תרומה קעה, ב. במדבר קיח, ב."],["3604","54","<b>דהנצח. . והחסד. . החכמה בקו הימין</b>: ראה גם לעיל המשך אם כסף תלוה פ\"ה הערה 98."],["3605","55","<b>גם את זה לעו\"ז עשה האלקי'</b>: קהלת ז, יד. ראה גם לעיל המשך חייב אדם לברך פי\"ט על יד הערה 693 ואילך.\n56)מנה\"י. . לבר מגופא: ראה ע\"ח שער הולדת או\"א וזו\"ן שט\"ז, רפ\"ד."],["3606","57","<b>כי לא יכול לו</b>: וישלח לב, כו."],["3607","58","<b>בד\"ה ויאבק איש עמו</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370123\" data-slug=\"torah-or\" data-id=\"3901370123\">תו\"א וישלח כו, ג</a>."],["3608","59","<b>לא כן</b>: במאמרי אדה\"ז תקס\"ה כאן: ליתא."],["3609","60","<b>דאצי'</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תשכג ניתוסף: (כי בדרך כללות ההשתלשלות הוא מא\"א שרש כל הנאצלים כו' עד רגלי העשי' כו')."],["3610","61","<b>הרי אז. . נה\"י</b>: בבוך 1162 וכן באוה\"ת כאן ע' 2072: [הרי. . נה\"י]. אבל כן הוא בבוך זה 1089."],["3611","62","<b>כי גם</b>: במאמרי אדה\"ז תקס\"ה כאן: הרי."],["3612","63","<b>בלק\"ת</b>: ר\"פ ראה."],["3613","64","<b>רחצתי את רגלי</b>: שה\"ש ה, ג."],["3614","65","<b>קדשת</b>: בתרגום: קדשית."],["3615","66","<b>פל\"ו</b>: ס\"ג."],["3616","67","<b>בילקוט בתלים</b>: רמז תתעח."],["3617","68","<b>וחג\"ת בחב\"ד</b>: בבוך 1162 ניתוסף בין השיטין (בין התיבות חג\"ת בחב\"ד] בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש: מתעלים לחב\"ד ואזי אין יניקה מנה\"י ע\"י התקשרותן בחג\"ת וחג\"ת בחב\"ד. תיבות אלו אינם מופיעים בבוך זה 1089. אבל נעתקו באוה\"ת כאן, אבל בתור דברי הצמח צדק [ושם נדפס: ואז במקום ואזי]."],["3618","69","<b>שתכלה רגל מן השוק</b>: שבת כא, ב."],["3619","70","<b>טורי דפרודא</b>: זהר בראשית כט, ב. ויצא קנח, א. פקודי רלד, סע\"א."]]],[2000450348,"<b>וזהו</b> ג\"כ שרש ענין וצדקה תרומם גוי, פי' תיבת גוי הן אותיות גימל וא\"ו יו\"ד, הגימל<sup data-n=\"3620\">71</sup> הוא בחי' נה\"י [ע\"ד והנה שלשה עדרי צאן<sup data-n=\"3621\">72</sup> רובצים על הבאר, וגם הגימל משפיע לבחי' ד' ע\"ד גמול דלים<sup data-n=\"3622\">73</sup> כי מבחי' נה\"י נמשך השפע לבחי' דל, וע' זח\"א ד\"ג סע\"א גבי עאלת אות ד' ואות ג' וע' בבה\"ז פ' בלק<sup data-n=\"3623\">74</sup> מענין תמונת אות ג' ע\"פ ומספר את רובע ישראל] והוא\"ו<sup data-n=\"3624\">75</sup> הוא בחי' המדות עצמן [והוא בחי' ת\"ת כולל ו\"ק<sup data-n=\"3625\">76</sup>] והיו\"ד הוא<sup data-n=\"3626\">77</sup> חכמה, וא\"כ פי' תרומם גוי שיהי' הגימל בחי' נה\"י מקושר בהיו\"ד חכמה עילאה ששם מקום הביטול ע\"י הוא\"ו המחברם ואז אין שום יניקה מבחי' נה\"י<sup data-n=\"3627\">78</sup> [וזהו ע\"ד רפאות תהי לשרך<sup data-n=\"3628\">79</sup> דהיינו גם מהטבור ולמטה ששם פרסא מפסקת כמ\"ש יהי רקיע ויהי מבדיל<sup data-n=\"3629\">80</sup> כו' גם משם לא יוכל להיות שום יניקה, וע' מענין וצדקה תרומם גוי בפ\"ק דב\"ב ד\"י ע\"ב, ובילקוט ר\"פ כי תשא דק\"ה ע\"ד<sup data-n=\"3630\">81</sup> ועמ\"ש מזה בתו\"א פ' מקץ<sup data-n=\"3631\">82</sup> בד\"ה המגביהי לשבת], וזהו והארץ הדום רגלי פי' הארץ דמצינו כתוב<sup data-n=\"3632\">83</sup> ג\"פ ארץ ארץ ארץ שמעי דבר ה' בירמי' סי' כ\"ב כ\"ט [ע' מזה בחולין פ' העור והרוטב דקכ\"ז א', ובילקוט בתלים<sup data-n=\"3633\">84</sup> ע\"פ השמים מספרים ובשל\"ה בתשב\"כ פ' ויחי ד' ש\"ד ע\"א ועמ\"ש מזה בלק\"ת פ' שלח<sup data-n=\"3634\">85</sup> סד\"ה טובה הארץ מאד מאד], פי' ג' פעמים ארץ<sup data-n=\"3635\">86</sup> קאי על ג' שרשים של המל'<sup data-n=\"3636\">87</sup> הנק' ארץ כי שרש המל' בג' מקומות בנה\"י ובחג\"ת ובחב\"ד<sup data-n=\"3637\">88</sup> [וע' מזה בהרמ\"ז ר\"פ כי תשא גבי ג' דברים שנתקשה בהן משה מנורה שקלים החדש] כי<sup data-n=\"3638\">89</sup> בכל בחי' ובחי' מג' הללו חב\"ד חג\"ת נה\"י<sup data-n=\"3639\">90</sup> יש בחי' המל' שהוא בחי' אותית וגילוי אותו הבחי' כמו גילוי אותיות השכל וגילוי אותיות הבינה כו', וכן עד\"ז בחי' גילוי אותיות המדות חג\"ת וגילוי אותיות",[["3620","71","<b>הגימל</b>: במאמרי אדה\"ז תקס\"ה כאן: מלמטה למעלה ואותיות יו\"ד וי\"ו גימל מלמעלה למטה כו', וביאור הדברים הנה הגימל.\nלהבא לקמן ראה גם לעיל מאמר ד\"ה ומקנה רב על יד הערה 86 (ובהנסמן בריש המאמר שם). לקמן מאמר ד\"ה מה יפו על יד הערה *77־ ד\"ה בראשית על יד הערה 46 (ובהנסמן בריש המאמר שם). ד\"ה שלש רגלים (בהוספה) על יד הערה 65."],["3621","72","<b>והנה שלשה עדרי צאן</b>: ע\"פ ויצא כט, ב. ראה זהר ס\"ת ויצא קנא, ב. ביאוה\"ז שבהערה 74. מאמרי אדה\"א נ\"ך ע' קיד. וש\"נ."],["3622","73","<b>הגימל. . ד' ע\"ד גמול דלים</b>: שבת קד, א."],["3623","74","<b>בבה\"ז פ' בלק</b>: קז, ד ואילך."],["3624","75","<b>והוי\"ו</b>: במאמרי אדה\"ז תקס\"ה כאן: ולא שהמדות חג\"ת הן בעצמן אלא כמו שהן מתעלמים בבחי' תלת גו תלת כנ\"ל והוי\"ו."],["3625","76","<b>ת\"ת כולל ו\"ק</b>: ראה זהר רע\"מ פינחס רמח, ב."],["3626","77","<b>והיו\"ד הוא</b>: במאמרי אדה\"ז תקס\"ה כאן: כמו שהן (וכידוע בצורת הגימל שהיא וי\"ו ויו\"ד הפוך מלמטה נדבק בו וכו') והיו\"ד הוא בחי'."],["3627","78","<b>וא\"כ פי'. . נה\"י</b>: כ\"ז ליתא במאמרי אדה\"ז תקס\"ה כאן. ושם ישנו חלק נוסף שלא הועתק כאן."],["3628","79","<b>רפאות תהי לשרך</b>: משלי ג, ח."],["3629","80","<b>יהי רקיע ויהי מבדיל</b>: בראשית א, ו [בדילוג]."],["3630","81","<b>ובילקוט ר\"פ כי תשא דק\"ה ע\"ד</b>: רמז שפו."],["3631","82","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370175\" data-slug=\"torah-or\" data-id=\"3901370175\">תו\"א פ' מקץ</b>: לח, ג</a>."],["3632","83","<b>דמצינו כתוב</b>: במאמרי אדה\"ז תקס\"ה ע' תשכד כאן: הנה דכתיב."],["3633","84","<b>ובילקוט בתלים</b>: רמז תרעב."],["3634","85","<b>בלק\"ת פ' שלח</b>: לח, ג."],["3635","86","<b>פי' ג' פעמים ארץ</b>: במאמרי אדה\"ז תקס\"ה כאן: כו' כנ\"ל."],["3636","87","<b>המל'</b>: שם: הנוק'."],["3637","88","<b>בנה\"י ובחג\"ת ובחב\"ד</b>: שם: הוא נגד חב\"ד ונגד חג\"ת ונגד נה\"י."],["3638","89","<b>כי</b>: שם: כי גם."],["3639","90","<b>נה\"י</b>: שם: כו'."]]],[2000450349,"נה\"י כו' [ע' בזח\"ג פ' בלק דקצ\"ג ע\"ב גבי תלת דוכתין דאקרין<sup data-n=\"3640\">91</sup> כל חד אתה וע' מזה בסדור ע\"פ ברוך שאמר והי' העולם, ועד\"ז י\"ל ענין ג' שרשים של המל' כי אתה היינו ג\"כ אותיות מא' עד תי\"ו וה' מוצאות<sup data-n=\"3641\">92</sup> וגם י\"ל ג' בחי' אלו הם בי\"ע שבאצי' ע' בלק\"ת פ' שלח<sup data-n=\"3642\">93</sup> בד\"ה ביאור ע\"פ ועתה יגדל נא, וג' שרשים אלו זהו ג\"כ בשלשה אותיות גוי אשר הג' הוא נה\"י והוא\"ו חג\"ת והיו\"ד היינו או\"א וזהו ענין גוי אחד בארץ<sup data-n=\"3643\">94</sup> כו']. ודרך כלל הוא בחי' חב\"ד חג\"ת נה\"י בלבד שבכל פרצוף לפי ערכו ובכל א' מאלה נמצא בחי' המל' שבו והוא ענין ג' שרשי הנוק' שהיא המל' בדרך כלליות ההשתלשלו', ובדרך פרט הנה מאצי' לבי\"ע מתלבשת בחי' נה\"י דז\"א ובחי' הגילוי שלו הוא בחי' מל' שמחי' יש מאין כידוע, והב' בבחי' האצי' עצמו לנגד חג\"ת דאצי' שם הוא ג\"כ בחי' הגילוי ואמנם שם הוא בבחי' האצי' ממש, משא\"כ בחי' המל' שמסתתרת ומתעלמת בבי\"ע שאינה שם בבחי' האצי' ממש רק בבחי' העלם גדול כידוע, והג' כמו שהמל' היא בשרשה עדיין ולא ירדה למטה באבי\"ע כו', והוא כמו שהיא בשרשה באבא דאבא יסד ברתא<sup data-n=\"3644\">95</sup> וכמ\"ש במ\"א ע\"פ המלאך הגואל<sup data-n=\"3645\">96</sup> כו', וע\"פ ארוממך ה' כי דליתני<sup data-n=\"3646\">97</sup> כנ\"ל [וע' בפרד\"ס<sup data-n=\"3647\">98</sup> שער מיעוט הירח פ\"ג]. והנה כמו שהיא בשורשה עדיין באו\"א<sup data-n=\"3648\">99</sup> בהיותה שם בתכלית הביטול וההתכללו' כמבואר שם לא נק' עדיין בשם<sup data-n=\"3649\">100</sup> במהות דבר בפ\"ע אלא נק' בחי' פסיעה לבר כמו צורת הרגל הקצר שבתוך הה\"א דהיינו כרעי' דה\"א<sup data-n=\"3650\">101</sup> שיש בסופו המשכה קטנה כמו פסיעה לבר [וע' מזה בלק\"ת פ' מסעי בד\"ה לבאר ענין המסעות ושם פ\"ב], ואח\"כ כשיורדת ונמשכת מאו\"א<sup data-n=\"3651\">102</sup> באצי' למטה מתפשטת ביותר וכו'<sup data-n=\"3652\">103</sup>, ואח\"כ מאצי' לבי\"ע נעשית בבחי' דלית<sup data-n=\"3653\">104</sup>, וזהו שרש ענין ג\"פ ארץ שאמר שמעי דבר ה' היינו שיהי' בחי' תיקון הנוק' ולפי שצ\"ל ע\"י בחי' הדיבור כמ\"ש למעלה ויהיו כל אלה נאום ה'<sup data-n=\"3654\">105</sup> לכך אמר שמעי דבר ה' כו'. [והיינו ג' שנקראו ארץ כנס\"י כמ\"ש כי תהיו אתם",[["3640","91","<b>דוכתין דאקרין</b>: בזהר: דוכתי אינון דאקרי. וראה גם אוה\"ת בלק ע' תתקצח. סידור ע' מב. ס\"ע שעט. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 86."],["3641","92","<b>אתה. . מא' עד תי\"ו וה' מוצאות</b>: ראה גם שער היחוד והאמונה פ\"ב."],["3642","93","<b>בלק\"ת פ' שלח</b>: לט, ד."],["3643","94","<b>גוי אחד בארץ</b>: שמו\"ב ז, כג. דהי\"א יז, כא."],["3644","95","<b>דאבא יסד ברתא</b>: ראה זהר רע\"מ פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה מצירופי. קונטרסים ס\"ע תקמז ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540846\" data-slug=\"torat-chaim\" data-id=\"2300540846\">תו\"ח שמות ח\"א יב, א</a>."],["3645","96","<b>המלאך הגואל</b>: ויחי מח, טז. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תרצב ואילך. ביאוה\"ז בלק קמו, ג ואילך."],["3646","97","<b>ארוממך ה' כי דליתני</b>: תהלים ל, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' נז ואילך."],["3647","98","<b>בפרד\"ס</b>: וכ\"ה באוה\"ת כאן. ראה לעיל המשך חייב אדם לברך פ\"ט ובהערה 293."],["3648","99","<b>בשורשה. . באו\"א</b>: במאמרי אדה\"ז תקס\"ה כאן: בשרשה. . באבא."],["3649","100","<b>בשם</b>: שם: בשם ומלכות."],["3650","101","<b>שבתוך הה\"א דהיינו כרעי' דה\"א</b>: שם: שבה\"א."],["3651","102","<b>ונמשכת מאו\"א</b>: שם: ליתא."],["3652","103","<b>מתפשטת ביותר וכו'</b>: שם: אזי מתפשטת יותר ונעשית בצורת וי\"ו קטנה."],["3653","104","<b>בבחי' דלית</b>: שם: בצורת דלי\"ת (והוא היו\"ד הקטן שבראש האלף שנעשה בצורת דלי\"ת קטן למטה והקו האמצעי שבאל\"ף כו' וד\"ל)."],["3654","105","<b>ויהיו כל אלה נאום ה'</b>: ישעי' סו, ב."]]],[2000450350,"ארץ חפץ<sup data-n=\"3655\">106</sup> ותושבע\"פ<sup data-n=\"3656\">107</sup> ומצות וזהו ארץ ארץ ארץ שמעי דבר ה', היינו ארץ שהיא כנס\"י ע\"י קיום המצות וע\"י תושבע\"פ יבואו להיות שמעי דבר ה', וכמ\"ש במד\"ר פ' נשא פי\"ד<sup data-n=\"3657\">108</sup> ע\"פ דברי חכמים כדרבונות שדרים בינה ודיעה בבני אדם כו', ואמרו שם יותר מדברי תורה הזהר בדברי סופרים כו']. והנה לנגד ג' מדרגות הללו דבחי' ארץ אמר כאן והארץ הדום רגלי היינו לנגד ג' מקומות שרשי המל' הנ\"ל, ולהיות כי נעוץ תחב\"ס כנ\"ל ע\"כ בבחי' תיקון הנוק' בג' שרשים שלה הנ\"ל יהי' עילוי לבחי' הראש והמוחין כו' כמבואר למעלה, ובדרך פרט הנה מבואר למעלה<sup data-n=\"3658\">109</sup> שבתורה עצמה יש ב' מדרגות תשב\"כ ותושבע\"פ, והנה תשב\"כ נק' בחי' ראש במה שהיא בבחי' הקריאה וההמשכה מלמעלה למטה כנ\"ל<sup data-n=\"3659\">110</sup> כי ענין קורא הוא מלמעלמ\"ט כמ\"ש קורא הדורות מראש<sup data-n=\"3660\">111</sup> כו', וכמ\"ש במ\"א, ולפי שהיא שמותיו של הקב\"ה<sup data-n=\"3661\">112</sup> עי\"ז<sup data-n=\"3662\">113</sup> יהי' אוא\"ס נמשך מלמעלה למטה, וא\"כ הרי הוא<sup data-n=\"3663\">114</sup> בחי' ראש לגבי תשבע\"פ, אמנם באמת תשבע\"פ היא ג\"כ<sup data-n=\"3664\">115</sup> בחי' הראש כי בדרך העלי' מלמטלמ\"ע למטה הראש כנ\"ל וגם תושבע\"פ הרי הוא<sup data-n=\"3665\">116</sup> בבחי' א\"ח כנ\"ל, ועוד והוא עיקר הטעם שהרי אמיתית רצוה\"ע מתגלה בה והרי גילוי הרצון ותכלית האמיתי בתושבע\"פ הוא [וכמ\"ש במד\"ר נשא שם דרנ\"ז סע\"ד מפני שהם פורשים את התורה ולכך נמשלו דברי חכמים כדרבונות כו' ע\"ש, וזהו ענין ובכל נפשך<sup data-n=\"3666\">117</sup> לפי' הזהר וארא דך\"ז ע\"א דהיינו בבחי' מל' ור\"ל ואהבת בכל כחות הנפש אפי' בבחי' רגל שגם הרגל תרום ותגביה [וע'<sup data-n=\"3667\">118</sup> בת\"ז בתחלתו דף א' סע\"א<sup data-n=\"3668\">119</sup> ע\"פ ועמך כולם צדיקים לעולם ירשו ארץ האי<sup data-n=\"3669\">120</sup> דאתמר בה והארץ הדום רגלי דא שכינתא<sup data-n=\"3670\">121</sup> דאיהי כלילא מעשר ספירן כו', ובכס\"מ שם<sup data-n=\"3671\">122</sup> שזהו ויתן אותם אלקים ברקיע השמים להאיר על הארץ וע' בזהר ויצא דקס\"ב ע\"ב, והנה בזח\"א ר\"פ נח דנ\"ט ע\"ב ע\"פ ועמך כולם צדיקים מ\"ט בגין דנטרין ברית כו', ובזה יש להבין המד\"ר באיכה<sup data-n=\"3672\">123</sup> ע\"פ ולא זכר הדום רגליו דמפרשו על מצות מילה יעו\"ש. והיינו לפי שעי\"ז נמשך האור",[["3655","106","<b>כי תהיו אתם ארץ חפץ</b>: מלאכי ג, יב."],["3656","107","<b>ארץ. . ותושבע\"פ</b>: ראה לעיל המשך חייב אדם לברך פכ\"ד ובהערה 884."],["3657","108","<b>במד\"ר פ' נשא פי\"ד</b>: ס\"ד (בשינויים — ראה אוה\"ת קהלת כרך ב ע' א'קלט)."],["3658","109","<b>מבואר למעלה</b>: ראה מאמר ד\"ה ומקנה רב."],["3659","110","<b>כנ\"ל</b>: ראה מאמר ד\"ה ומקנה רב."],["3660","111","<b>קורא הדורות מראש</b>: ישעי' מא, ד. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' שכה. הנסמן במאמרי אדה\"א דברים ח\"ג ס\"ע תתיא."],["3661","112","<b>שמותיו של הקב\"ה</b>: ראה זהר יתרו פז, א. פתיחת הרמב\"ן עה\"ת. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' נב."],["3662","113","<b>עי\"ז</b>: במאמרי אדה\"ז תקס\"ה ע' תשכה כאן: על ידם."],["3663","114","<b>הוא</b>: שם: היא."],["3664","115","<b>ג\"כ</b>: שם: ליתא."],["3665","116","<b>הוא</b>: במאמרי אדה\"ז תקס\"ה כאן ישנו קטע נוסף."],["3666","117","<b>ובכל נפשך</b>: ואתחנן ו, ה."],["3667","118","<b>[וע'</b>: בבוך 1162: וע'. והחצי ריבוע שקודם תיבת וע' נמחק. וכ\"ה באוה\"ת כאן ע' 2074. אבל כן הוא בבוך זה 1089. וראה גם לעיל הערה 44."],["3668","119","<b>בת\"ז בתחלתו דף א' סע\"א</b>: דפוס אמשטרדם תקכ\"ח. ולפנינו בהקדמה א, ב."],["3669","120","<b>האי</b>: לפנינו: ההיא."],["3670","121","<b>שכינתא</b>: כ\"ה בת\"ז שלפנינו. ובת\"ז הנ\"ל: שכינה — ראה אוה\"ת ישעי' ע' שטו."],["3671","122","<b>ובכס\"מ שם</b>: אות ע (בשינוי לשון — ראה גם אוה\"ת ישעי' שם)."],["3672","123","<b>המד\"ר באיכה</b>: פ\"ב, ג."]]],[2000450351,"בבחי' והארץ הדום רגלי. וע' עוד בת\"ז דף ה' ע\"ג<sup data-n=\"3673\">124</sup> מענין והארץ הדום רגלי ובזח\"ב תרומה דקנ\"ח סע\"א כגון סגול כו' ובפ' פנחס דרמ\"ג סע\"ב ודרמ\"ח ע\"א ובפ' שופטים דף ער\"ה ע\"א ובפרד\"ס ערך הדום<sup data-n=\"3674\">125</sup> ובמאו\"א אות ה' סעי' ג'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו וצדקה תרומם גוי, רפאות תהי לשרך, ארץ ארץ ארץ היינו ג' שרשים של המל', ענין תלת דוכתין דאקרון אתה, בי\"ע שבאצי', והיינו ארץ כנס\"י ע\"י המצות ותושבע\"פ יבואו לבחי' שמעי דבר ה', וזהו ואהבת בכל נפשך ועי\"ז והארץ הדום רגלי, ובבחי' זו נא' ועמך כולם צדיקים לעולם ירשו ארץ המאיר לארץ ולדרים עליה<sup data-n=\"3675\">126</sup> ויתן אותם אלקי' ברקיע השמים להאיר על הארץ].</span>\n<b>וזהו</b> בנים אתם, שברא כרעא, ואם היות שהסוף הוא ראש ג\"כ מ\"מ הנה הרגל נשפל למטה מאד, וצריכים לזהר שלא יטנפו, וזהו האזהרות לא תתגודדו כו' קרחה למת שהוא אבי אבות<sup data-n=\"3676\">127</sup> כו' והיינו שלא יומשך תוס' יניקה ח\"ו, ולכן הגם כי המשכת אורות בכלים זהו ע\"י מ\"ע עכ\"ז הזהיר בכאן על מל\"ת שזהו כמשל דירת המלך שצריכין לנקותה<sup data-n=\"3677\">128</sup> תחילה מכל ליכלוך בכדי שתהי' ראוי' לדירת המלך, וכך בכדי להיות עם קדוש וסגולה כו' צ\"ל הזהירות במל\"ת וזהו לא תתגודדו ולא כו' למת, שעי\"ז<sup data-n=\"3678\">129</sup> זהירות זו נפרד הרע כמו הגו סיגי' מכסף<sup data-n=\"3679\">130</sup> וזהב, שעי\"ז מתברר<sup data-n=\"3680\">131</sup> הכסף והזהב כך עי\"ז ע\"י<sup data-n=\"3681\">132</sup> אשר קדשנו נעשה עם קדוש וסגולה, ולכן אם היות כי בנים אתם כו' מ\"מ מפני שהרגל יורד כו' צ\"ל הזהירה בל\"ת עד שע\"י קיום המ\"ע נעשים עם קדוש וסגולה כו'.",[["3673","124","<b>בת\"ז דף ה' ע\"ג</b>: ראה גם אוה\"ת שם. ולפנינו בהקדמה ז, רע\"א"],["3674","125","<b>ובפרד\"ס ערך הדום</b>: שעה\"כ שכ\"ג, פ\"ה."],["3675","126","<b>המאיר לארץ ולדרים עליה</b>: נוסח ברכת יוצר."],["3676","127","<b>למת שהוא אבי אבות</b>: ראה רש\"י פסחים יד, רע\"ב. יז, א. חוקת יט, כב (ד\"ה תטמא עד הערב). מאמרי אדה\"א דברים ח\"א ע' קסג. וש\"נ."],["3677","128","<b>דירת המלך שצריכין לנקותה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380809\" data-slug=\"likkutei-torah\" data-id=\"4001380809\">לקו\"ת ראה כג, ב</a>."],["3678","129","<b>שעי\"ז</b>: אוצ\"ל: שע\"י."],["3679","130","<b>הגו סיגי' מכסף</b>: ע\"פ משלי כה, ד."],["3680","131","<b>מתברר</b>: תיבה זו איננה ברורה. ואולי כצ\"ל."],["3681","132","<b>עי\"ז ע\"י</b>: תיבת עי\"ז כתובה בסוף השיטה, ובתחילת שיטה הבאה נכתב תיבת ע\"י."]]],[2000450352,"<h3>אני לדודי ודודי לי כו'</h3>\n<b>בס\"ד ש\"פ שופטים ל\"ח</b>\n<b>אני</b> לדודי<sup data-n=\"3682\">1</sup> ודודי לי<sup data-n=\"3683\">2</sup> הרועה בשושנים, והנה אני לדודי ודודי לי ר\"ת אלול<sup data-n=\"3684\">3</sup>, ושושנים הם בחי' יגמה\"ר כמ\"ש בזהר בענין תליסר עלין<sup data-n=\"3685\">4</sup> דסחרין לשושנה, והיינו שבחדש אלול מאירים יגמה\"ר<sup data-n=\"3686\">5</sup>, וזהו הרועה בשושנים שלכנס\"י נעשה מרעה",[["3682","1","<b>אני לדודי</b>: מאמר זה הוא דרוש הרביעי (מההמשך) שמבאר הסיום מביאור הראשון (על מאמר ד\"ה השמים כסאי) ד\"ה להבין שרשי הדברים הנ\"ל שנדפס במאמרי אדה\"ז תקס\"ה ח\"ב הנחת כ\"ק אדמו\"ר האמצעי ע' תשכה — תשכח. והוא דרוש השמיני מההמשך שבו נתבארו הדרושים דהשמים כסאי וביאוריו שנאמרו בשנת תקס\"ה כמצויין לעיל ברד\"ה ואשא אתכם.\nהמאמר (מלבד הפתיחה והסיום, וכן הערות שבתוך ההחצע\"ג שנכתבו בגוכתי\"ק) הוא לשון מאמרי אדה\"ז תקס\"ה הנ\"ל עם הגהות הצ\"צ שבאים בתוך חצאי ריבוע. וההגהות שבהחצע\"ג הם מכ\"ק אדמו\"ר מהר\"ש. והדברים המובאים בתוך חצאי עיגול שהם בתוך חצאי מרובע [( )] הם מכ\"ק אדמו\"ר האמצעי שנכתבו במאמרי אדה\"ז הנ\"ל בין חצאי עיגול. אמנם היוצא מהכלל זה, הוא הבא לקמן בפיסקא ”[(אך\" שעל יד הערה 53 שמאמר אדה\"ז בא בין [( )]. ועל יד הערה 55 החצע\"ג של כ\"ק אדה\"א בא רק בין ( ). וכן החצע\"ג שבפיסקא ”ועם\" שעל יד הערה 102. כאמור לעיל [בריש מאמר ד\"ה ואשא אתכם בהערה] הנה בבוך 1162 בסופו נמצא מאמר אדה\"ז עם הגהות הצ\"צ, אמנם במאמר דידן נמצאים שם 2 דפים* שהונחו שם לאחרי כתיבת המאמר, היינו שבהמאמר המקורי כפי שסדרו הצ\"צ לא הי' הוספה זו. והוא העתק עוד קטע ממאמר אדה\"ז והגהה מכ\"ק אדמו\"ר מהר\"ש.\nהמאמר — מלבד הפתיחה והסיום — נדפס גם בלקו\"ת לג\"פ ט, ג. אוה\"ת בראשית כרך ו ע' 2074 ואילך (פ\"ו).\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות (ומשם נעתקה הכותרת שמופיע בריש המאמר — פרט לתיבת בס\"ד).\nמאמר זה נזכר לקמן במאמר ד\"ה זה עני על יד הערה 48."],["3683","2","<b>אני לדודי ודודי לי</b>: שה\"ש ו, ג."],["3684","3","<b>אני לדודי. . ר\"ת אלול</b>: ראה אבודרהם סדר תפלת ר\"ה ופירושה בשם הדרשנים. מאמרי אדה\"א דברים ח\"א ע' שלב. וש\"נ. שע\"ת מט, א הערה 3."],["3685","4","<b>ושושנים. . תליסר עלין</b>: ראה זהר בהקדמה א, א. ביאורי הזהר שם. ולהצ\"צ כרך ב ע' תקצט ואילך. לעיל המשך חייב אדם לברך פל\"ט ובהערה 1709."],["3686","5","<b>שבחדש אלול מאירים יגמה\"ר</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תכב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540712\" data-slug=\"torat-chaim\" data-id=\"2300540712\">תו\"ח בא ח\"א קכג, סע\"ב</a> ואילך. וש\"נ."]]],[2000450353,"משושנים, ולכן דודי הוא הרועה שרואה<sup data-n=\"3687\">*6</sup> בשושנים את כנס\"י, והנה ביגמה\"ר יש ב' בחי' בכלל והיינו יגמה\"ר שא' משה בתו' ה\"ה<sup data-n=\"3688\">6</sup> אל רחום וחנון<sup data-n=\"3689\">7</sup> כו', ויגמה\"ר שא' מיכה מי אל כמוך<sup data-n=\"3690\">8</sup>, ונודע ממ\"ש בכתהאריז\"ל שיגמה\"ר דמיכה הם גבוהים יותר שהם בא\"א, ודמשה הם בז\"א<sup data-n=\"3691\">9</sup>, והגם שנת' בסידור שבכדי שיהי' ההמשכה מז\"א<sup data-n=\"3692\">10</sup> צ\"ל תחילה המשכה מא\"א בז\"א כו', וגם לפי מ\"ש במ\"א שבכדי שיומשך למטה<sup data-n=\"3693\">11</sup> צ\"ל נמשך מבחי' גבוה יותר, ויגמה\"ר דמשה זהו לחיי הגוף<sup data-n=\"3694\">12</sup> שזהו המשכה למטה כו' עכ\"ז זהו ענין אחר ומ\"מ בענין הפרצופים יגמה\"ר דמיכה ה\"ה גבוהים יותר שהרי הם בא\"א, וא\"כ צ\"ל מדוע ביגמה\"ר דמיכה יש בהם דקדוקים יותר שהרי ארז\"ל נושא עון למי נושא עון למי שעובר על פשע, לשארית נחלתו ולא לכל נחלתו למי שמשים עצמו כשיריים שא' ע\"ז אלי' וקוץ בה<sup data-n=\"3695\">13</sup>, להיות כי א\"ז דבר קל כו', וביגמה\"ר דמשה א' רק תיקון ואמת שזהו דקדוק קצת שהרי אמת א' אל יברא<sup data-n=\"3696\">14</sup>, וגם ונקה לא ינקה ארז\"ל מנקה הוא לשבים<sup data-n=\"3697\">15</sup> לא ינקה לאינם שבים כו', שאינם בבחי' הדקדוק כ\"כ כמו דמיכה כו' שהם לחיי הנשמות כו' אשר לכאו' נהפוך הוא כו'. ויובן בהקדם ענין הנשמה שארז\"ל חמשה שמות נקראו לה, נפש רוח נשמה חיה יחידה (במד\"ר פ' בראשית<sup data-n=\"3698\">16</sup> ) פי' נר\"נ הם פנימים, שיש להם כלים אשר הארתם מתלבשים בהם, וכמ\"ש בזהר שמוחא לבא וכבדא הם כלים לנר\"נ<sup data-n=\"3699\">17</sup>, משא\"כ חי' יחידה אין להם כלים<sup data-n=\"3700\">18</sup> פרטי' בגוף, אבל מ\"מ הם העיקר, וכמ\"ש נשמה שנתת בי<sup data-n=\"3701\">19</sup> שרשה טהורה היא מבחי' טהירא עילאה<sup data-n=\"3702\">20</sup>, ובכדי שתוכל להתלבש בגוף הגשמי ירדה בבחי' בראת כו' נפחתה ויפח באפיו<sup data-n=\"3703\">21</sup> כו' כתי' נשמת חיים דוקא משא\"כ",[["3687","*6","<b>שרואה</b>: ב: שרועה."],["3688","6","<b>יגמה\"ר. . ה\"ה </b>[ב: ה' ה']: ראה לעיל מאמר ד\"ה על חומותיך ובהערה 109. לקמן מאמר ד\"ה זה עני על יד הערה 108."],["3689","7","<b>ה\"ה אל רחום וחנון</b>: תשא לד, ו."],["3690","8","<b>מי אל כמוך</b>: מיכה ז, יח."],["3691","9","<b>שיגמה\"ר דמיכה. . בא\"א ודמשה הם בז\"א</b>: ראה לקמן (בחלק ההנחות) בהנחה כאן. אוה\"ת ראה ע' תתז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380852\" data-slug=\"likkutei-torah\" data-id=\"4001380852\">לקו\"ת ראה לד, ב</a>. סידור שער האלול רכט, ג ואילך. מאמרי אדה\"ז הנחות הר\"פ ע' כט. תקס\"ז ע' שנא. המשך תער\"ב ח\"ג ע' א'תל."],["3692","10","<b>שנת' בסידור. . ההמשכה מז\"א</b>: שחרית נב, א."],["3693","11","<b>שבכדי שיומשך למטה</b>: ראה גם לעיל מאמר ד\"ה על חומותיך ובהערה 19."],["3694","12","<b>ויגמה\"ר דמשה זהו לחיי הגוף. . הנשמות</b>: ראה לקו\"ת סידור וכו' שבהערה 9."],["3695","13","<b>נושא עון. . לשארית נחלתו. . בה</b>: מיכה שם. ראה ר\"ה יז סע\"א ואילך. ראה גם אוה\"ת נצבים ע' א'רפג. מיכה כרך א ס\"ע תצ ואילך. סה\"מ קונטרסים ח\"ב ע' תכז."],["3696","14","<b>אמת א' אל יברא</b>: ב\"ר פ\"ח, ה."],["3697","15","<b>ונקה. . מנקה הוא לשבים</b>: תשא לד, ז. ראה יומא פו, א."],["3698","16","<b>פ' בראשית</b>: פי\"ד, ט. ראה גם הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."],["3699","17","<b>שמוחא לבא וכבדא הם כלים לנר\"נ</b>: ראה אבן עזרא משפטים כג, כה. יסוד מורא — להנ\"ל — ש\"ז. לעיל מאמר ד\"ה על חומותיך ובהערה 49."],["3700","18","<b>חי' יחידה אין להם כלים</b>: ראה שעה\"י קכח, ב ובהערה 51. מאמרי אדה\"א קונטרסים ע' רנג. וש\"נ. לקמן מאמר ד\"ה זה עני על יד הערה 57."],["3701","19","<b>נשמה שנתת בי</b>: ברכת אלקי נשמה (ברכות ס, ב)."],["3702","20","<b>טהורה. . טהירא עילאה</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ס\"ע תנח ואילך. שע\"ת ל, ב ובהערה 17. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 39. ד\"ה ומקנה רב על יד הערה 164. ד\"ה בנים אתם על יד הערה 22."],["3703","21","<b>ויפח באפיו</b>: בראשית ב, ז."]]],[2000450354,"מקיפי'<sup data-n=\"3704\">22</sup> דחי' יחידה הם בחי' ואתה משמרה בקרבי שזהו העיקר, וכמשל שומר הגשמי שהוא עיקר המקיים הדבר לבלי ישלטו בו ידי זרים כו'.\n<b>ויובן</b> זה דהנה כל מה שנת' באורך הנה כ\"ז הוא בבחי' א\"פ<sup data-n=\"3705\">23</sup> דוקא דהיינו בבחי' נר\"נ שיש להם בחי' כלים כנ\"ל, אבל בבחי' חיה יחידה אורות המקיפים שאין להם בחי' כלים אין בהם בחי' ראש וסוף כלל עד שנאמר בהם ההפרש בין מלמטה למעלה שלמטה הראש ובין מלמעלה למטה שלמעלה הראש כנ\"ל מאחר שאין בהם בחי' מעלה ומטה כלל וכלל כו', וזהו שאמר השמים כסאי והארץ הדום רגלי<sup data-n=\"3706\">24</sup> ואת כל אלה ידי עשתה<sup data-n=\"3707\">25</sup> ויהיו כל אלה נאום ה', דהיינו כל הענין המבואר למעלה בתשב\"כ ותושבע\"פ שנק' שמים וארץ<sup data-n=\"3708\">26</sup> והן בחי' עשי' ודבור כנ\"ל<sup data-n=\"3709\">27</sup> שכ\"ז רק בבחי' או\"פ דוקא, אבל בבחי' א\"מ איזה בית אשר תבנו לי כו' ואל זה אביט<sup data-n=\"3710\">28</sup> אל עני ונכה רוח כו' (וכמשנת\"ל<sup data-n=\"3711\">29</sup> פי' עני ונכה רוח ע\"ש, ואמנם גם בזה צ\"ל הלא מצד המקיף אין בו התחלקות, ולמה דקדוק שאל עני ונכה רוח דוקא יביט כו', אלא שזהו כענין יגמה\"ר דמיכה שנא' בהם ג\"כ דקדוקי' וכמשי\"ת), [וזהו השלשה דיעות שבגמ' פ\"ב דחגיגה די\"ב ע\"א ב\"ש אומרים שמים קדמו לארץ ובה\"א ארץ קדמה וחכ\"א זה וזה כאחת נבראו, ובמד\"ר פ' בראשית ספ\"א ובפ' בחוקתי פל\"ו הובא דיעה זו הג' בשם רשב\"י אמר רשב\"י תמיה אני על אבות העולם כו', והיינו כי מצד סדר ההשתל' מלמעלמ\"ט שמים קדמו וכמו הראש לגבי הרגל ובבחי' מלמטה למעלה ע\"ד נעוץ סוב\"ת<sup data-n=\"3712\">30</sup> ארץ קדמה שהמל' היא כתר מלמטה למעלה<sup data-n=\"3713\">31</sup> אך מצד המקיפים דחי' ויחידה שאין שם ראש וסוף כלל קורא אני אליהם<sup data-n=\"3714\">32</sup> יעמדו יחדיו, ועמ\"ש בת\"א פ' בשלח סד\"ה להבין ענין לחם משנה ומ\"ש בענין זכור ושמור בדבור א' נאמרו שם פ' יתרו בד\"ה להבין ענין האבות הן הן המרכבה<sup data-n=\"3715\">33</sup>].\n<b>ולהבין</b> בתוס' ביאור שרש ענין ההבטה שהוא בבחי' אור מקיף דוקא כנ\"ל, יש להקדים ענין א' והוא מה שידוע<sup data-n=\"3716\">34</sup> שאין בהסתכלות והבטה ענין תחלה וסוף<sup data-n=\"3717\">35</sup> כלל כמו בשאר החושים, דהנה בחוש השמיעה א\"א שישמע האזן כל",[["3704","22","<b>מקיפי'</b>: תוקן ע\"פ ב."],["3705","23","<b>כ\"ז הוא בבחי' או\"פ</b>: מכאן הוא לשון מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשכה."],["3706","24","<b>השמים כסאי והארץ הדום רגלי</b>: ישעי סו, א."],["3707","25","<b>ואת כל אלה ידי עשתה</b>: ישעי' שם, ב."],["3708","26","<b>בתשב\"כ ותושבע\"פ שנק' שמים וארץ</b>: ראה לעיל מאמר ד\"ה ומקנה רב ובהערה 107."],["3709","27","<b>עשי' ודיבור כנ\"ל</b>: ראה לעיל מאמר ד\"ה גדול יהי' על יד הערה 46. ד\"ה על חומותיך בתחילתו."],["3710","28","<b>ואל זה אביט</b>: המשך הכתוב ואת כל אלה. במאמרי אדה\"ז תקס\"ה כאן ע' תשכה: אל — ראה גם לעיל מאמר ד\"ה על חומותיך ובהערה 96."],["3711","29","<b>וכמשנת\"ל</b>: במאמר ד\"ה גדול יהי' אחר הערה 48. ד\"ה על חומותיך על יד הערה 96. ובחלק ההנחות שם."],["3712","30","<b>נעוץ סוב\"ת</b>: ראה ס\"י פ\"א, מ\"ז."],["3713","31","<b>שהמל' היא כתר מלמטה למעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381210\" data-slug=\"likkutei-torah\" data-id=\"4001381210\">לקו\"ת שה\"ש כ, ב</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550715\" data-slug=\"torat-chaim\" data-id=\"2300550715\">תו\"ח תצוה ח\"ב שעה, ב</a>. וש\"נ."],["3714","32","<b>קורא אני אליהם</b>: ישעי' מח, יג."],["3715","33","<b>בת\"א. . יתרו בד\"ה. . המרכבה</b>: עג, ב ואילך ד\"ה וזהו."],["3716","34","<b>שידוע</b>: במאמרי אדה\"ז תקס\"ה כאן: שמבואר בספרי הטבע."],["3717","35","<b>שאין בהסתכלות. . תחלה וסוף</b>: ראה גם סה\"מ תרס\"ח ע' ריא שמעתיק מכאן."]]],[2000450355,"הדבורים והקולות בפעם אחת אלא מעט מעט וכל דבור וקול שומע האזן בהבדל מדבור זולתו וא\"א לב' דבורים שישמעו בבת אחת<sup data-n=\"3718\">36</sup> וכמארז\"ל<sup data-n=\"3719\">37</sup> בענין זכור ושמור<sup data-n=\"3720\">38</sup> בדבור א' נאמרו מה שאין הפה יכול לדבר ואין האזן יכולה לשמוע, ונמצא הדבור והשמיעה וכן הריח לא יתפוס הכל בבת אחת אלא חלקים חלקים דוקא, משא\"כ חוש הראי' אינו כן שהרי אנו רואים בכל מי שיביט ויסתכל על איזה דבר שטח מה הנה מיד כרגע יתפוס כח הראות אותו כללות השטח בבת אחת ממש בלתי קדימה לראיית העין על חלק א' ממנו מעל חלק זולתו כלל אלא הכל נסקר בסקירה אחת בעין הראות, מפני שכח חוש הראי' הוא בא ונמשך בבחי' אור מקיף כלומר לפי שהוא תופס בבחי' עגול והיקף לאותו דבר הנתפס בכחו עד שכאלו אותו הדבר שהוא מביט עליו הוא באמצעית וכח ראייתו מקפת אותו ומסבבת מכל צדדיו<sup data-n=\"3721\">39</sup>, וא\"כ מובן שאין בבחי' הראי' חלקים אלא הכל בהשואה אחת ופעם אחת כו', וממילא מובן שאין בה תחלה וסוף ולא מעלה ומטה<sup data-n=\"3722\">40</sup> (ומה שאנו רואים שכאשר יביט הרואה על איזה דבר שיש בה ציורים עד\"מ ציצים ופרחים שאם<sup data-n=\"3723\">41</sup> היות שמביט על כלליות הדבר בסקירה אחת כו' כנ\"ל, עכ\"ז לא ירגיש לראות בדברים הדקים מן הדקים שיש בציור הזה בפרטיות הציצים והפרחים או ברשומות הדקים שבם, כ\"א עד לאחר זמן שיביט בדבר ההוא הרבה אז ימצא כל הפרטי' הדקים וירגיש בהם כו', ולכאו' ה\"ז כמו שארי הכחות שאינם באים בב\"א שהובא לעיל, אמנם באמת אינו כן שזהו רק כמו כלל ופרט, שאין בפרט אלא מה שבכלל<sup data-n=\"3724\">42</sup> שכאשר כלל זה כולל פרטי' אלו בהכרח לאמר שישנם בבחי' הכלל כו' דאל\"כ אינו כלל מכל פרטי' אלו כו', ואינו דומה לכח השמיעה שאזן מילין תבחן<sup data-n=\"3725\">43</sup>, ומעט מעט נרגש דבור המספר עד שיודע הדבר שמספר לו, משא\"כ הרואה הרי רואה בב\"א כנ\"ל אלא שרואה הכלל והפרטי' הנראי' לעין כל, ולא פרטי' הדקי' שזה יכול להיות מב' טעמי' או שמקיף העין אינו מתחלק כ\"כ לפרטי' דקי' עד שיעמיק היטב, או מפני שגם כח הראי' מוגבלת היא שעד פה תבוא<sup data-n=\"3726\">44</sup> כו', אבל עכ\"ז תפיסת כח הראי' ה\"ה בב\"א אלא שבא בבחי' הכלל, והרי מצינו שארז\"ל והלא במאמר אחד יכול להבראות<sup data-n=\"3727\">45</sup>, שנת' פי' שמאמר אחד כולל כלליות ע\"מ והוא מאמר דבראשית<sup data-n=\"3728\">46</sup>, נמצא עכ\"פ הי' יכול להיות ההתהוות כמו שהיא עתה גם ממאמר בראשית שהוא כלל שכולל כל המאמרות כו' (דאם נא' שהי' בלתי פרטי' א\"כ א\"ז נק' יכול להבראות שהרי הי' באו\"א, וגם הלא לא לבד מטעם כדי",[["3718","36","<b>אחת</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תשכו ניתוסף: כמאמר תרי קלי לא משתמעי — רש\"י מגילה כא, ב ד\"ה ובלבד. ר\"ה כז, א."],["3719","37","<b>וכמארז\"ל</b>: שם: וכמפורש ברז\"ל."],["3720","38","<b>בענין זכור ושמור</b>: ראה ר\"ה כז, א. שבועות כ, א (כגי' הע\"י)."],["3721","39","<b>צדדיו</b>: במאמרי אדה\"ז תקס\"ה כאן ישנו קטע נוסף."],["3722","40","<b>ומטה</b>: שם ניתוסף: ולא צדדי וד\"ל."],["3723","41","<b>שאם</b>: כ\"ה בכ\"מ — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["3724","42","<b>שאין בפרט אלא מה שבכלל</b>: ראה גם סהמ\"צ להצ\"צ נח, ב."],["3725","43","<b>שאזן מילין תבחן</b>: איוב יב, יא."],["3726","44","<b>שעד פה תבוא</b>: איוב לח, יא."],["3727","45","<b>והלא במאמר אחד יכול להבראות</b>: אבות רפ\"ה. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200163\" data-slug=\"or-hatorah-hb\" data-id=\"8159200163\">אוה\"ת בהר כרך ג ע' תתעח</a>. סה\"מ תרכ\"ז ס\"ע רפב ואילך. מאמרי אדה\"א דברים ח\"ב ע' תעז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540769\" data-slug=\"torat-chaim\" data-id=\"2300540769\">תו\"ח וארא ח\"א פא, ג</a> והערה 634."],["3728","46","<b>מאמר דבראשית</b>: בראשית א, א. ר\"ה לב, א."]]],[2000450356,"להפרע כו' אלא מפני שרצה שיהי' בפרטיות הדברי' כמו שהן עתה כו'), אלא מפני כדי להפרע כו' ברא בע\"מ וכדפי' במד\"ש<sup data-n=\"3729\">47</sup> שהכלי שעולה לו יו\"ד זהובי' יקר יותר כו', וגם יובן ממה שנודע שהמח' היא כלל ודבור הוא פרט<sup data-n=\"3730\">48</sup> כו' ובתחלה כשעלה במח' להבראות תיכף כשעלה במח' להבראות נבראו כל העולמות אלא שזהו בכלל וברוחניות ודקות, וחזר ופרטן בדבור בכדי שיהיו בגשמיות כמ\"ש עתה, ונמצא כי יש עוד יתרון מעלה לכלל לגבי הפרט כו', ומה שי\"ל שלא הי' רק רוחני' לבד הלא הוא כל יכול וכשהי' רוצה שיהי' ממח' גשמי' הי' מתהוה ג\"כ כו', ועכ\"פ מובן שהכלל כולל כל מה שבא אח\"כ בפרט. ובאמת אין הנדון דומה לראי' כלל שבנ\"ד הרי הפרטי' כבר ישנן, אלא שבסקירתו הנה ע\"י ראייתו ה\"ה רואה וסוקר הכלל מהדבר והפרטי' שבו שנראי' לעין ומ\"מ כבר ישנם בזה גם הפרטי' ג\"כ, והנם פועלים בדבר הנראה גם שאינם מורגשי' שהרי הדבר הנראה מתייפה ע\"י הרשומי' הדקי' שאינם נראי' לעין להדי', ונמצא כי גם מהם יש תועלת בראיית העין בהדבר ההיא כו'. ויובן זה ע\"פ משנ\"ת בכ\"ד שענין ראיית העין הוא ג\"כ ע\"ד כמו מה שרואי' במראה<sup data-n=\"3731\">49</sup> שהוא ע\"י שמחפי' הזכוכי' בחיפוי דק הנה עי\"ז אינו נראה דרך בה כ\"א שהדבר שמחזיקי' או עומדת נגדה מצטיירת בזכוכית החפויה הנ\"ל, ועד\"ז הוא בכלי העין ג\"כ שבעצם נקודת העין מה שבתוך הקרומי' המחפים עליה הנה דופן האחרון שבה היינו מה שלצד הראש הוא חשוך שזהו כמו הסתר הציפוי הנ\"ל וכל דפנותי' בעיגולה הם בהירים (ולרוב בהירותם צריכים כיסוי והיינו הקרומי' שהם כגלדי בצלים זעג\"ז כו', ולכן למי שנחשך כח הראות קורין סגי נהור<sup data-n=\"3732\">50</sup>, לפי שבאמת כן הוא שהקרומי' נעשו דקי' או נעברו לגמרי וע\"י בהירות אור הנקודה שהוא סגי נהור בלתי אפשר לראות שאינו מרגיש הציור כמשי\"ת) מאד, והדבר שרואה אותה מצטיירת בכלי העין<sup data-n=\"3733\">51</sup> וה\"ה מקפת לגמרי הדבר הנראה, ולפ\"ז מובן שגם דברים הדקי' מצטיירים שם כמו שמצטיירים במראה הנק' שפיגל בל\"א, ומה שאינו מרגיש אותם בפרטיות כ\"א רק בכלל והוא מה שמתייפה הדבר ההיא י\"ל שזה אינו שייך לכח הראי' כלל כ\"א להשגת הרואה עצמו, ובאמת בהכרח לומר כן שהרי במראה בודאי נצטייר הכל בב\"א, והיתכן שכלי העין שזהו ג\"כ כענין המראה יוגרע שזהו א\"א כלל כו', אלא שזהו שייך להמשיג כו', וכמו שיש הפרש בין מי שיש חוש<sup data-n=\"3734\">52</sup>",[["3729","47","<b>וכדפי' במד\"ש</b>: ראה אבות שם ד\"ה והחסיד. סה\"מ תרכ\"ז ע' רפב."],["3730","48","<b>שהמח' היא כלל ודבור הוא פרט</b>: ראה סה\"מ תרכ\"ז ע' רפג ובהנסמן בריש המאמר שם."],["3731","49","<b>ראיית העין. . שרואי' במראה</b>: ראה המשך וככה תרל\"ז פנ\"ז (ע' פז). מאמר ד\"ה משה קבל תר\"ם ע' 5."],["3732","50","<b>סגי נהור</b>: ראה המשך וככה שם פע\"ג (ע' קיז). סה\"מ תרס\"ח ע' לב. המשך תער\"ב ח\"א ע' ערה. ח\"ב ע' א'כד ואילך."],["3733","51","<b>והדבר. . מצטיירת בכלי העין</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה גדול יהי' ובהערה 79."],["3734","52","<b>שיש חוש</b>: באוה\"ת כאן ע' 2076: שיש לו חוש."]]],[2000450357,"להבין היטב מה שהוא רואה, למי שאין לו חוש כ\"כ, שמי שיש לו חוש להבין מתפעל באו\"א לגמרי ממי שאין חוש בזה כ\"כ, וקרוב הדבר שמי שיש לו חוש טוב הנה הוא מרגיש יותר במהירות גם בראיית דברי' הקטנים והדקים, ונמצא כי עיקרו בבחי' ההשגה שבא ע\"י הראי', אבל הראי' תופסת ומקפת כל הדברים רק שבכלל מתגלה תיכף גם בהשגה והפרטי' הדקי' מתגלי' לאחר זמן ולפי ערך המשיג כנ\"ל שזה אינו שייך כלל לעצם כח הראי' כו'. וגם אנו רואי' ההבדל בין ראי' לשמיעה שבשמיעה לבד מה שבא לא בפ\"א כ\"א מעט מעט, הנה בשמיעה בא הפרט תחלה ואח\"כ מבין כלליות הענין לאן הדברים מגיעים וכוונתם, ומקור נביעתם, והכרח המדבר המבקשו עד\"מ או כוונת המספר, משא\"כ בראי' בא הכלל תחלה ואח\"כ הפרט, והיינו מפני שהוא חלוק בעצם להיותו בחי' מקיף שהוא כלל כו') [והנמשל מזה יובן למעלה דבחי' הארת המקיף עליון נק' ואל זה אביט כו'].\n<b></b>[(אך<sup data-n=\"3735\">53</sup> הנה לפ\"ז הי' בזה ג\"כ הכרח<sup data-n=\"3736\">54</sup> לומר שלא יהי' לכח הראי' גבול וסוף מאחר שאינה תופסת בגדר חלקי' כלל כנ\"ל, אך הענין הוא דמ\"מ יש לראי' גבול דכל הדברים שלמטה הן תחת בחי' הגבול שהרי אנו רואים שגם לכח השכלי שבמוח יש גבול שההשגה בשכל מוגבלת היא עד כאן יוכל להשיג ויותר לא יוכל להשיג מפני עומק המושג וא\"א כלל שתהי' ההשגה בלי שיעור גם במופלג שבדור בחכמה כי מאחר שנפשו נברא יש מאין הרי היא תחת הגבול (גם<sup data-n=\"3737\">55</sup> בבחי' חי' יחידה שבה, אך מ\"מ הנה יש הפרש בין חי' יחידה לנר\"ן והוא מצד הכלים לפי שהן<sup data-n=\"3738\">56</sup> מגבילי' באמת) להיות ידוע דנר\"ן דאצי' נתלבשו בכלים שנק' מוחא ולבא וכבדא כו', ואותן הכלים מאירים בעולמות הנפרדי' בבי\"ע עד בחי' הכלים דעשי' כידוע, וא\"כ ע\"ד דוגמא מי שנפשו מעולם העשי' הרי יש לה בחי' כלים דעשי', והנה בחי' הכלים הוא עיקר הסיבה שמביאה לידי הגבלה אמיתי' עד\"מ כח השכלי בכלי המוח הנה מה שתקצר כח השגתו להשיג עומק המושג יוכל להיות שאינו מצד עצם כח השכלתו הנפשיות אלא מצד בחי' הכלי של המוח שנתקלקלה או שיש בה חסרון בטבע תולדתה או מפני מיעוט המעלות הצריכות באופן שתהי' כלי מוכן לקבל צורת כח השכל הרוחני וכיוצא, והרי זהו הסיבה שמביאה לידי הגבלה אמיתי' משא\"כ עצם כח השכלתו אינו בהגבלה כזו עדיין אך ורק שאינו מתפשט בלי שיעור כי נברא יש מאין ויש לו גבול בעצם אבל אינו נגבל כ\"כ עד שלא ישיג דבר שכל כמו זה שחסר בכלי השכל שאינו משיג כלום, וכיוצא בזה יובן שגם אם הכלי שלם",[["3735","53","<b>[(אך</b>: לשון מאמרי אדה\"ז תקס\"ה כאן ע' תשכו. וראה הנרשם בריש המאמר כאן אודות פיסקא זו."],["3736","54","<b>בזה ג\"כ הכרח</b>: שם: מהכרח ג\"כ."],["3737","55","<b>(גם</b>: כל הסוגר נמצא במאמרי אדה\"ז תקס\"ה כאן. וראה הנרשם אודות זה בריש המאמר כאן."],["3738","56","<b>שהן</b>: באוה\"ת בראשית כאן ע' תתרלט: שאין."]]],[2000450358,"בתכונתו מ\"מ הוא המגביל כח צורת הנפש להיותה חומריות כו' (ונמצא<sup data-n=\"3739\">57</sup> כי ההפרש בין עצם כח הנפש לכוחות המלובשים בכלי הגוף, הוא כהפרש הגבול לגבי השערה שהיא ג\"כ גבול ע\"ד יכולני לשער כמה טיפים יש בים<sup data-n=\"3740\">58</sup> שאינו מדידה בגבול כו' כ\"א השערה, וע\"ד שיעור עצמו בכח<sup data-n=\"3741\">59</sup> שאינו גבול כ\"א מקור עכ\"פ לגבול ועד\"ז יובן ענין בחי' שיעור שבנפש) ועד\"ז בשאר האברים הם דוקא בחי' כלים מגבילי' לכחות הנפשיות כי כח הנפשיות מצד עצמם אין להם הגבלה כזו, אך מפני סיבת הכלי הוא שנגבלי' כ\"כ וכמו כח הראי' בכלי העין הנה ידוע בספרי הטבע שכלה כח הראי' הבינונית עד ס' מילין<sup data-n=\"3742\">60</sup> בודאי ולא שאין כח הראי' בעצם תוכל לראות יותר מס' מילין בשטח אלא שמחמת שכח הראי' הרוחני' נתלבשה בכלי העין הגשמי ולפי צורת כח הראי' לא היתה ענין הגבלה כזו עדיין אך ע\"י כלי העין החומרי ומכ\"ש אם אין העין שלם בתכונתו הראוי לכך מוגבל שיעור זה דס' מילין דוקא וכיוצא בזה בשאר החושי' כי דוקא האברי' כולן הן עיקר סיבה המביאה לכחות נפשיות שיוגבלו כ\"כ כנ\"ל (והנמשל<sup data-n=\"3743\">61</sup> מכ\"ז יובן למעלה דגם בחי' ההבטה וההסתכלו' למעלה הוא בבחי' אור מקיף עליון ואיננו בגדר חלקי' כלל ולכך אמרו צופה ומביט<sup data-n=\"3744\">62</sup> עד סוף כל הדורות פי' בסקירה א' כו' וכמ\"ש במ\"א, אך ע\"י בחי' כלי ההבטה הוא נגבל בגבולי' והיינו אל זה אביט להיות בחי' אור מקיף כו')].\n<b>ועם</b> ענין הנ\"ל מובן הטעם שכתבו המקובלי' שהלובש ב' מלבושים כא' קשה לשכחה<sup data-n=\"3745\">63</sup> מפני אור המקיף שמסתלק כו', כי הנה מבואר למעלה דההגבלה האמיתי' באה רק מסיבת הכלי אבל לחי' יחידה שהן בחי' מקיפי' ואין להם כלים שיגבילו אותן וזהו ענין כח הזכרון שיש באדם שהוא בא מכח אור מקיף<sup data-n=\"3746\">64</sup> דענין סיבת השכחה היא באה מפני קוצר הגבלת כח הכלי שמגביל את האור השכלי ולכך הולך ומשתכח מעט מעט<sup data-n=\"3747\">65</sup>, אבל מצד בחי' המקיף השורה על כלי השכל אין",[["3739","57","<b>(ונמצא</b>: סוגר זה הוא מכ\"ק אדמו\"ר מהר\"ש. וראה הנרשם בריש המאמר כאן."],["3740","58","<b>יכולני לשער כמה טיפים יש בים</b>: ראה הוריות י, סע\"א. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה פי' פתחה בחכמה על יד הערה 60. סהמ\"צ להצ\"צ ר\"ע 182. המשך מים רבים תרל\"ו פקנ\"ב (ע' קסח). סה\"מ תרכ\"ט ע' צט. וש\"נ. תרל\"ב ח\"ב ע' תקסו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261121\" data-slug=\"likkutei-sichot\" data-id=\"1300261121\">לקו\"ש יתרו כרך כו ע' 121</a>. שיחת ש\"פ קרח תשמ\"א (סמ\"ד)־ סע\"ד ואילך. רשימות חוב' קסו."],["3741","59","<b>שיעור עצמו בכח</b>: ראה מק\"מ לזהר בראשית טו, א. מאמרי אדה\"א קונטרסים ע' רא. וש\"נ."],["3742","60","<b>כח הראי'. . ס' מילין</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' שלו. וש\"נ. סה\"מ תרכ\"ז ע' שעד. וש\"נ. תרל\"ב ח\"א ע' שלב."],["3743","61","<b>(והנמשל</b>: כל הסוגר נמצא במאמרי אדה\"ז תקס\"ה כאן ע' תשכז. וראה הנרשם אודות זה בריש המאמר כאן."],["3744","62","<b>צופה ומביט</b>: ראה ברכת זכרונות. ר\"ה יח, א. סהמ\"צ להצ\"צ ע' פב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540576\" data-slug=\"torat-chaim\" data-id=\"2300540576\">תו\"ח שמות ח\"א מח, ב</a>. וש\"נ."],["3745","63","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540169\" data-slug=\"torat-chaim\" data-id=\"2300540169\">שהלובש ב</a>' מלבושים כא' קשה לשכחה</b>: ראה ספר הכונות (קארץ תקמ\"ד) ה, ב. שו\"ע אדה\"ז חאו\"ח ס\"ב, ס\"ג במהדו\"ק ובמהדו\"ת. מאמרי אדה\"א דברים ח\"א ע' קיד. וש\"נ. תו\"ח וארא ח\"א נח, ד. וש\"נ."],["3746","64","<b>כח הזכרון. . אור מקיף</b>: ראה גם (בנוסף למאמרי אדה\"ז תקס\"ה כאן) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550569\" data-slug=\"torat-chaim\" data-id=\"2300550569\">תו\"ח תרומה ח\"ב שי, סע\"ג</a> ואילך."],["3747","65","<b>מעט</b>: במאמרי אדה\"ז תקס\"ה כאן ניתוסף: כי כלה מעט מעט כח הכלי להכיל השכל מפני שקבלו בתחלה בהגבלה וצמצום גדול וכו'."]]],[2000450359,"אותו השכל בא לידי הגבלה<sup data-n=\"3748\">66</sup> עד שישתכח במשך הזמן ע\"כ יזכור אותו גם כשיומשך הזמן<sup data-n=\"3749\">67</sup> ולא יגרע בו אור השכל מזמן זה לזמן אחר כמאז כן עתה אחר הרבה שנים מאחר שבא מכח שאיננו מוגבל בכלי הגוף כו', וזהו עיקר ענין מוח הזכרון שיש בו מבחי' אור המקיף כו', ולכן בפ' קדש שהוא חכ'<sup data-n=\"3750\">69</sup> נא' ולזכרון בין עיניך<sup data-n=\"3751\">70</sup> כי חכ' היא בחי' חיה<sup data-n=\"3752\">71</sup> כמ\"ש והחכ'<sup data-n=\"3753\">72</sup> תחיה<sup data-n=\"3754\">68</sup>, והנה הלובש לבוש ממשיך עליו אור מקיף כידוע שאורות המקיפים שורים על הלבושים<sup data-n=\"3755\">73</sup> דוקא<sup data-n=\"3756\">74</sup>, אמנם כשלובש ב' מלבושים כא' אין אור המקיף הדוחה הקליפה יכול ליכנס ביניהם ומביאתו לידי<sup data-n=\"3757\">76</sup> שכחה* [ועמ\"ש<sup data-n=\"3758\">75</sup> עוד מענן שכחה בת\"א פ' תצוה סד\"ה זכור את אשר עשה לך עמלק ובלק\"ת<sup data-n=\"3759\">79</sup> בד\"ה ואהי' אצלו אמון פ\"ג, ובאג\"ה בסופו סד\"ה דוד זמירות קרית להו וע' במאו\"א אות שי\"ן סל\"ז ובפרד\"ס<sup data-n=\"3760\">80</sup> ערך שכחה וערך זכירה<sup data-n=\"3761\">81</sup>, ובזח\"א ר\"פ מקץ דקצ\"ג ע\"ב ע\"פ ולא זכר שר המשקים את יוסף וישכחהו וע' בגמ' פ\"ה דברכות דל\"ב ע\"ב ע\"פ ותאמר ציון עזבני ה' ואד' שכחני כו' עד ואנכי לא אשכחך וע' בתוס'<sup data-n=\"3762\">82</sup> פ\"ק דר\"ה די\"ז ע\"ב בשם הפסיקתא. ומכ\"ז יש",[["3748","66","<b>הגבלה</b>: שם ניתוסף: כ\"כ."],["3749","67","<b>הזמן</b>: שם ניתוסף: מאחר שלא הי' דבר מגביל להיות גורם בו הגרעון והוא השכחה כו'."],["3750","69","<b>בפ' קדש שהוא חכ'</b>: בא יג, א ואילך. ראה זהר ואתחנן רסב, א."],["3751","70","<b>ולזכרון בין עיניך</b>: בא יג, ט."],["3752","71","<b>חכ' היא בחי' חיה</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת ראה כה, א</a>. יוה\"כ ע, ג. מאמרי אדה\"א דברים ח\"ב ע' תכח. וש\"נ. שמות ח\"ב ע' תקמח. וש\"נ. מאמרי אדמו\"ר הצ\"צ תרי\"ד ע' ה."],["3753","72","<b>והחכ' תחיה</b>: קהלת ז, יב [ושם: החכמה — ראה לעיל המשך אם כסף תלוה פי\"ד הערה 292]."],["3754","68","<b>ולכך. . והחכ' תחיה</b>: שם: וד\"ל."],["3755","73","<b>שאורות המקיפים שורים על הלבושים</b>: ראה ספר הכונות שם. ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ג. פע\"ח שער התפלה ש\"א, פ\"ב. מאמרי אדה\"א קונטרסים ס\"ע יא ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540997\" data-slug=\"torat-chaim\" data-id=\"2300540997\">תו\"ח בשלח ח\"א קפ, ג</a>. וש\"נ."],["3756","74","<b>דוקא</b>: במאמרי אדה\"ז תקס\"ה כאן ניתוסף: וע\"כ הלובש את מלבושיו דוחה את השכחה מטעם שאין שכחה במקיפים כנ\"ל."],["3757","76","<b>אין אור. . לידי שכחה</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תשכח: דוחה אור המקיף כמבואר בע\"ח וע\"כ קשה לשכחה וד\"ל."],["3758","75","<b>אמנם. . [ועמ\"ש</b>: באוה\"ת כאן ע' 2078: [אמנם. . ועמ\"ש."],["3759","79","<b>ובלק\"ת</b>: פ' במדבר יח, ג."],["3760","80","<b>ובפרד\"ס</b>: כ\"ה בכ\"מ — ראה לעיל המשך חייב אדם לברך פ\"ט ובהערה 293."],["3761","81","<b>ובפרד\"ס ערך שכחה וערך זכירה</b>: שעה\"כ שכ\"ג, פכ\"א ופ\"ז."],["3762","82","<b>בתוס'</b>: ד\"ה שלש עשרה מדות בהגה\"ה."]]],[2000450360,"להבין מ\"ש בזכרי' סי' ט'<sup data-n=\"3763\">83</sup> גילי מאד כו' עני ורוכב על החמור היינו כדי להיות בחי' ואל זה אביט אל עני כו', וענין ורוכב על חמור ועל עיר יובן ממ\"ש ע\"פ אוסרי לגפן עירה<sup data-n=\"3764\">84</sup> כו'. וע' מענין השמים כסאי והארץ הדום רגלי בגמ' פ\"ב דחגיגה די\"ב סע\"א ודי\"ד ודט\"ז ע\"א, פ' בתרא דברכות דנ\"ט ע\"א וברבות פ' בראשית ספ\"א, פ' בחוקתי פל\"ו<sup data-n=\"3765\">85</sup>, ובזח\"ב פקודי דרמ\"א א'<sup data-n=\"3766\">86</sup>, ומענין איזה בית ע' ברבות נשא פי\"ב קרוב לר\"פ, דרמ\"ו ג'<sup data-n=\"3767\">87</sup>, בשעה שאמר הקב\"ה<sup data-n=\"3768\">88</sup> ועשו לי מקדש כו' אמר משה כו' הנה השמים ושמי השמים לא יכלכלוך כו' ואומר השמים כסאי כו' ע\"ש, ובסנהדרין פ\"ק ד\"ז ע\"א, ומענין ואת כל אלה ידי עשתה ברבות בראשית פי\"ב<sup data-n=\"3769\">89</sup> וע' ברבות ויקהל פמ\"ח<sup data-n=\"3770\">90</sup> מענין ג' בחי' אלה יעו\"ש, ומענין ואל זה אביט אל עני ברבות משפטים פל\"א קרוב לס\"פ ע\"פ את העני עמך<sup data-n=\"3771\">91</sup>, וע' עוד מענין השמים כסאי והארץ כו' בזח\"ב פ' יתרו דפ\"ה סע\"ב<sup data-n=\"3772\">92</sup>, תרומה דקנ\"ח סע\"א זח\"ג פנחס דרמ\"ח ע\"א ודרמ\"ג סע\"ב<sup data-n=\"3773\">93</sup>, פ' שופטים דף ער\"ה א', ת\"ז בתחלתו דף א' ע\"א<sup data-n=\"3774\">94</sup> ועיין בשל\"ה ר\"פ תרומה<sup data-n=\"3775\">95</sup>, והנה י\"ל ע\"י חיבור בחי' השמים כסאי והארץ הדום רגלי עי\"ז מאיר ממילא בחי' הגבוה משניהם והוא ענין ואל זה אביט כו', ועמ\"ש מזה בהביאור ע\"פ ועשית בגדי קדש<sup data-n=\"3776\">96</sup>]. ובכל הנ\"ל יובן סוף הפסוק ואל זה אביט כו' ומה שע\"ז אמר לא הביט און ביעקב<sup data-n=\"3777\">97</sup> כו' ה' אלקיו עמו, כי הנה כתי' עיניך יונים<sup data-n=\"3778\">98</sup> כו' וה\"ז כמשל יונה שנזקקה לבן זוגה בהסתכלות<sup data-n=\"3779\">99</sup> בלבד כו', וכמו\"כ כתי' עיניו כיונים<sup data-n=\"3780\">100</sup> כו' ולע\"ל כתי' עין בעין<sup data-n=\"3781\">101</sup> בחי' עין א' כו' כי זהו היחוד בבחי' מקיפי' דחי' יחידה שאין שם כלים (וכמ\"ש<sup data-n=\"3782\">102</sup> במ\"א ע\"פ באתי לגני<sup data-n=\"3783\">103</sup> כו' באתרי'",[["3763","83","<b>בזכרי' סי' ט'</b>: פסוק ט. מכאן ועד הערה 95 הועתק גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560023\" data-slug=\"or-hatorah-hb\" data-id=\"8316560023\">אוה\"ת בראשית כרך ג ע' תעח</a>."],["3764","84","<b>ע\"פ אוסרי לגפן עירה</b>: ראה אוה\"ת ויחי כרך ה תתרח, ב."],["3765","85","<b>פל\"ו</b>: ראה לעיל מאמר ד\"ה ומקנה רב על יד הערה 148 מציין: רפל\"ו."],["3766","86","<b>ובזח\"ב פקודי דרמ\"א א'</b>: ראה לעיל מאמר ד\"ה ומקנה רב על יד הערה 101."],["3767","87","<b>נשא פי\"ב קרוב לר\"פ דרמ\"ו ג'</b>: בדפוס אמשטרדם שנת ת\"א-ב. ולפנינו ס\"ג. ראה גם לעיל שם על יד הערה 148."],["3768","88","<b>שאמר הקב\"ה</b>: וכ\"ה באוה\"ת ישעי' כרך א ע' שיד. ובמדרש שם: שאמר לו הקב\"ה."],["3769","89","<b>ברבות בראשית פי\"ב</b>: ס\"ב. ראה גם לעיל מאמר ד\"ה על חומותיך על יד הערה 37."],["3770","90","<b>ברבות ויקהל פמ\"ח</b>: ס\"ב."],["3771","91","<b>ברבות משפטים פל\"א קרוב לס\"פ ע\"פ את העני עמך</b>: סי\"ג. ראה גם לעיל מאמר ד\"ה ומקנה רב הערה 147."],["3772","92","<b>בזח\"ב פ' יתרו דפ\"ה סע\"ב</b>: ראה גם לעיל מאמר ד\"ה גדול יהי' על יד הערה 71."],["3773","93","<b>פנחס. . ודרמ\"ג סע\"ב</b>: וכ\"ה באוה\"ת ישעי' שם ר\"ע שטו. אבל שם ע' שיב דרמ\"ג ב'."],["3774","94","<b>ת\"ז בתחלתו דף א' ע\"א</b>: דפוס אמשטרדם תקכ\"ח. ולפנינו בהקדמה א, ב. וראה לעיל מאמר ד\"ה בנים אתם על יד הערה 119."],["3775","95","<b>בשל\"ה ר\"פ תרומה</b>: שכד, א. ע\"כ הועתק באוה\"ת — ראה הערה 83."],["3776","96","<b>בהביאור ע\"פ ועשית בגדי קדש</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' שטו ואילך. אוה\"ת תצוה ע' א'תרז ואילך. שם כרך ח ע' ג'עב."],["3777","97","<b>לא הביט און ביעקב</b>: בלק כג, כא."],["3778","98","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["3779","99","<b>כמשל יונה. . בהסתכלות</b>: ראה גם לעיל מאמר ד\"ה על חומותיך הערה 92."],["3780","100","<b>עיניו כיונים</b>: שה\"ש ה, יב."],["3781","101","<b>עין בעין</b>: ישעי' נב, ח."],["3782","102","<b>(וכמ\"ש</b>: באוה\"ת בראשית כאן ע' תתרמ: [(וכמ\"ש. כל הסוגר נמצא במאמרי אדה\"ז תקס\"ה כאן. וראה הנרשם אודות זה בריש המאמר כאן."],["3783","103","<b>ע\"פ באתי לגני</b>: שה\"ש ה, א. ראה זהר פינחס רמא, ב. מאמרי אדה\"ז תקס\"ד ע' קמג."]]],[2000450361,"לאו אורחא למיכל כו' ע\"ש) ושם בא ההארה בבחי' או\"מ בהשואה מכל צד, וזהו הסליחה והמחילה שם הוא דוקא לפי שבבחי' הראי' בעיגול שאינה בגדר חלקי' חלקי'<sup data-n=\"3784\">104</sup> לא יתפס מקום כלל מה שיש עון ופגם באיזה חלק קטן מן השטח הגדול כו' מאחר שהאור בא בבחי' מקיף כו'. ועוד לפי שהראי' וההבטה הזאת הוא בבחי' מקיף העליון האמיתי שאין שם אפי' בחי' מעומ\"ט ובחי' ראש וסוף כלל כנ\"ל, וע\"כ הוא נושא עון ועובר על פשע כו' כי שם אין נוגע כלל וכמ\"ש בביאור ענין י\"ג מדה\"ר<sup data-n=\"3785\">105</sup> למעלה באריכות ע\"ש.\n<b>ואמנם</b> גם בבחי' יגמה\"ר ארז\"ל למי נושא עון למי שעובר ע\"פ, וכן לשארית נחלתו ולא לכל נחלתו, למי שמשים עצמו כשיריים, והענין יובן בהקדם ענין מה שהמן לא ירד בשבת<sup data-n=\"3786\">106</sup>, שהגם שהמן הי' בחי' גבוה מאד, כמ\"ש וברדת הטל<sup data-n=\"3787\">107</sup> ירד המן עליו כמשנ\"ת מזה במ\"א, ובכלל ז\"ע בחי' טל כמו שיורד בהגשמה קצת עד שיהי' בחי' לחם אבירים כו', שנבלע באיברים<sup data-n=\"3788\">108</sup> ועכ\"ז הוא לחם כו' רק שהוא לחם מן השמים<sup data-n=\"3789\">109</sup> כו', ולכן לא ירד בשבת דהנה נת' במ\"א ששרש בחי' המן הוא מבחי' עקודי'<sup data-n=\"3790\">110</sup> שעקוד בכלי אחד<sup data-n=\"3791\">111</sup> שנת' פי' במ\"א שהכלי היא ג\"כ אחד<sup data-n=\"3792\">112</sup>, אך מ\"מ ה\"ה בחי' כלי שהיא בחי' הגבלה קצת כו', וה\"ה מקור למקור דהרי כסדר המדריגות הם עקודי' נקודים וברודים<sup data-n=\"3793\">113</sup> כו', משא\"כ שבת הוא בחי' שביתה מכל אשר עשה היינו דבורו של הקב\"ה שחשיב מעשה<sup data-n=\"3794\">114</sup> כו', וזהו שבתא דמעלי שבתא בחי' שבת תתאה ע'<sup data-n=\"3795\">115</sup> בד\"ה את שבתותי תשמרו בפ' בהר, ושבתא דיומא הוא שבת עילאה, וגם בזה יש ב' בחי' סעודה שלישי' היא רעדכ\"ר<sup data-n=\"3796\">116</sup> ענג העליון, ולכן א\"צ סעודה גמורה<sup data-n=\"3797\">117</sup> ויוצא גם בד\"ת<sup data-n=\"3798\">118</sup>, וע' בהגהות",[["3784","104","<b>חלקי'</b>: באוה\"ת כאן ליתא."],["3785","105","<b>בביאור ענין י\"ג מדה\"ר</b>: לעיל מאמר ד\"ה על חומותיך פיסקא וזהו."],["3786","106","<b>שהמן לא ירד בשבת</b>: בשלח טז, ה. כב ואילך. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370297\" data-slug=\"torah-or\" data-id=\"3901370297\">תו\"א בשלח סו, ד</a>. וראה גם תו\"א שבהערה הבאה."],["3787","107","<b>וברדת הטל</b>: בהעלותך יא, ט [בדילוג]. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370400\" data-slug=\"torah-or\" data-id=\"3901370400\">תו\"א ויקהל פט, א</a> ואילך."],["3788","108","<b>המן. . לחם אבירים כו' שנבלע באיברים</b>: תהלים עח, כה. ראה יומא עה, ב."],["3789","109","<b>לחם מן השמים</b>: בשלח טז, ד. ראה גם שע\"ת ו, א."],["3790","110","<b>ששרש בחי' המן. . עקודי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370295\" data-slug=\"torah-or\" data-id=\"3901370295\">תו\"א בשלח סו, ב</a>. ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380779\" data-slug=\"likkutei-torah\" data-id=\"4001380779\">לקו\"ת עקב טז, ב</a>."],["3791","111","<b>שעקוד בכלי אחד</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370043\" data-slug=\"torah-or\" data-id=\"3901370043\">תו\"א נח י, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540165\" data-slug=\"torat-chaim\" data-id=\"2300540165\">תו\"ח וארא ח\"א נב, ד</a>. וש\"נ. סה\"מ תרנ\"ב ע' ק."],["3792","112","<b>במ\"א. . שהכלי. . אחד</b>: ראה גם לעיל המשך כי תשא קיצור לפ\"י. וש\"נ."],["3793","113","<b>עקודי' נקודים וברודים</b>: ויצא לא, י. יב. ראה ע\"ח ותו\"א שם."],["3794","114","<b>דבורו. . שחשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח."],["3795","115","<b>ע'</b>: בלקו\"ת."],["3796","116","<b>סעודה שלישי' היא רעדכ\"ר</b>: ראה זהר יתרו פח, סע\"ב."],["3797","117","<b>סעודה שלישי'. . א\"צ סעודה גמורה</b>: ראה שו\"ע אדה\"ז הל' שבת סרצ\"א, ס\"ז. פסקי דינים להצ\"צ שנז, ב ואילך. המשך תער\"ב ח\"ב ע' א'קכז ואילך. היום יום כב אד\"ר. לקו\"ש בשלח כרך כא ע' 84 ואילך ובהנסמן שם."],["3798","118","<b>סעודה שלישי'. . ויוצא גם בד\"ת</b>: ראה זהר אמור צה, א ובאוה\"ח שם. מג\"א הל' פסח סתמ\"ד, סק\"ב. ובשו\"ע אדה\"ז שם לא הביאו. סה\"ש תרפ\"ט ע' 30 ואילך ובהנסמן שם. תרצ\"ז ע' 217 ואילך. וראה ג\"כ שו\"ע אדה\"ז הל' שבת סר\"צ, ס\"ד. הל' ת\"ת פ\"ד, ה\"ד."]]],[2000450362,"עד\"ה אכלוהו היום<sup data-n=\"3799\">119</sup> שלכן נק' בקרא היום לא<sup data-n=\"3800\">120</sup> כו' והיינו כי זהו בחי' שבת שע\"ז אמרו רז\"ל מתנה טובה<sup data-n=\"3801\">121</sup> יש לי בבית גנזי ושבת שמה, מתנה זהו בחי' אתעדל\"ע שאין אתעדל\"ת<sup data-n=\"3802\">122</sup> מגעת כו', והוא למעלה גם מעקודי', וע' בפ' בשלח<sup data-n=\"3803\">123</sup> בסד\"ה להבין ענין לחם משנה, שלמעלה גם ממקור העולמות כו', ולכן המן לא ירד בשבת כו', והנה ארז\"ל מי שטרח בע\"ש<sup data-n=\"3804\">124</sup> יאכל בשבת, והיינו שיש בבחי' מה<sup data-n=\"3805\">125</sup> שעושי' את השבת כמ\"ש ושמרו בנ\"י כו' לעשות את השבת<sup data-n=\"3806\">126</sup>, ויש בחי' מתנה כנ\"ל, ועכ\"ז המתנה אינם נותנים אלא למי שראוי<sup data-n=\"3807\">127</sup> כו' דאילו לא הי' ניחא לי' לא הוה נתן לו, נמצא שאם היותו בחי' מתנה עכ\"ז צ\"ל קצת הכנה לזה, ועד\"ז יובן גם ביגמה\"ר שהגם שנושא עון כנ\"ל, עכ\"ז צ\"ל כלי לקבל בחי' זו וזהו מי שמשים עצמו כשיריים שמגיע לבחי' המקיף שזהו פי' שיריים מה שנשאר מבחי' או\"פ המתיישב בכלי כו' ונשאר בבחי' שיריים כו', וכן בג' בחי' אלו דהשמי' כסאי תורה והארץ מהמ\"צ<sup data-n=\"3808\">128</sup> או תושבע\"פ<sup data-n=\"3809\">129</sup> שזהו בחי' או\"פ (כי מקיף דמצות י\"ל שזהו מקיף הקרוב<sup data-n=\"3810\">130</sup> או מקיף פרטי לפ\"ע כאו\"א כמו הלבוש כמ\"ש במ\"א), אבל אי זה בית זהו בחי' השתחואה דתפילה ביטול שהראש שוה לרגל<sup data-n=\"3811\">131</sup>, שאין שם ראש וסוף ה\"ז בחי' או\"מ שיוכל לשרות עליו בחי' מקיף הכללי בחי' הבטה כו' ולכן ואל זה שהגיע לבחי' או\"מ דוקא אביט שישרה עליו בחי' מקיף הכללי, ואפ\"ל שב' בחי' אלו זהו ח\"י מקיף הפרטי ומקיף הכללי<sup data-n=\"3812\">132</sup> שנת' בד\"ה לחם משנה<sup data-n=\"3813\">133</sup>.",[["3799","119","<b>בהגהות עד\"ה אכלוהו היום</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470154\" data-slug=\"or-hatorah-hb\" data-id=\"8316470154\">אוה\"ת בשלח ס\"ע תרכ</a> ואילך (ע' תרג ואילך)."],["3800","120","<b>היום לא</b>: בשלח טז, כה. שבת קיז, סע\"ב. (וראה שו\"ע אדה\"ז ר\"ס עדר). ראה לבוש מלכות סרצ\"א, ס\"ה. פסקי דינים שם. אוה\"ת בשלח ע' תרלא (מאה שערים ע' מד). בהערה שלפ\"ז. סה\"מ תרל\"ב ח\"א ע' רעח. תרס\"ו ע' תקמב. תער\"ב שם. מאמר ד\"ה אתה אחד ט' כסלו תשכ\"ט (קונט' ט'-יו\"ד כסלו תש\"נ — סה\"מ מלוקט ד ע' ע)."],["3801","121","<b>מתנה טובה</b>: שבת י, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381226\" data-slug=\"likkutei-torah\" data-id=\"4001381226\">לקו\"ת שה\"ש כד, ב</a>. סה\"מ תרל\"ו ח\"ב ע' שסד."],["3802","122","<b>אתעדל\"ע. . אתעדל\"ת</b>: ראה זהר לך פח, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a> ובהערה 189."],["3803","123","<b>וע' בפ' בשלח</b>: בתו\"א סו, ד."],["3804","124","<b>מי שטרח בע\"ש</b>: ע\"ז ג, א."],["3805","125","<b>בבחי' מה</b>: כ\"ה בגוכתי\"ק."],["3806","126","<b>ושמרו. . לעשות את השבת</b>: תשא לא, טז. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370312\" data-slug=\"torah-or\" data-id=\"3901370312\">תו\"א יתרו ע, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380266\" data-slug=\"likkutei-torah\" data-id=\"4001380266\">לקו\"ת בהר מד, ג</a>. ש\"ש סח, ב. שה\"ש כד, ב. מאמרי אדה\"ז תקס\"ג ח\"א ע' שיב."],["3807","127","<b>המתנה אינם נותנים אלא למי שראוי</b>: ראה מגילה כו, ב. גיטין נ, ב. ב\"מ טז, א. ב\"ב קנו, א."],["3808","128","<b>דהשמי'. . תורה והארץ מהמ\"צ</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370003\" data-slug=\"torah-or\" data-id=\"3901370003\">תו\"א בראשית א, ב</a>. ג. לעיל מאמר ד\"ה ואשא אתכם־ ד\"ה ומקנה רב־ רד\"ה גדול יהי'. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 27־ ד\"ה ומקנה רב על יד הערה 39."],["3809","129","<b>דהשמי'. . תורה והארץ. . תושבע\"פ</b>: ראה ערה\"כ לבעל סדה\"ד מערכת שמים. לעיל המשך חייב אדם לברך פכ\"ד ובהערה 884."],["3810","130","<b>מקיף דמצות. . מקיף הקרוב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א שמות נה, ב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770185\" data-slug=\"or-hatorah-hb\" data-id=\"8316770185\">אוה\"ת ראה ע' תשפה</a>. שה\"ש ח\"ב ע' תקנג. ע' תקנו. סה\"מ תרכ\"ו ע' רכו. תר\"ל ע' ער."],["3811","131","<b>השתחואה. . שהראש שוה לרגל</b>: ראה גם לעיל מאמר ד\"ה גדול יהי' ובהערה 51."],["3812","132","<b>ח\"י מקיף הפרטי ומקיף הכללי</b>: ראה גם שע\"ת נב, א ובהערה 13."],["3813","133","<b>בד\"ה לחם משנה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370297\" data-slug=\"torah-or\" data-id=\"3901370297\">תו\"א בשלח סו, ד</a>."]]],[2000450363,"<b>וזהו</b> אני לדודי ודודי לי הרועה בשושנים, ופי' שושנים הם יגמה\"ר כנ\"ל שמאירים בחדש אלול<sup data-n=\"3814\">134</sup>, ורז\"ל אמרו א\"ת שושנים אלא ששונים שגם בתו' יש בחי' יגמה\"ר, יג\"מ שהתו' נדרשת בהם, וכ\"מ ממה שארז\"ל ע\"פ ואנכי עמדתי בהר<sup data-n=\"3815\">135</sup> כימים הראשונים מה הראשונים ברצון<sup data-n=\"3816\">136</sup> כו' שנמצא שבחי' רצון זה שביגמה\"ר שהוא נושא עון הי' גם במ\"ת, אשר לכאו' קודם מ\"ת ודאי הי' בלא חטא ועון ומה\"ע בחי' יגמה\"ר, אלא שבמ\"ת הי' גילוי כל מה שיהי' גם אח\"כ, והאיר גם בחי' מקיף הכללי, ולכן על כ\"ד ודבור פרחה נשמתן<sup data-n=\"3817\">137</sup> היינו שיצאו מהגבלת הכלי, לשאר בבחי' המקיף, והחי' אותנו<sup data-n=\"3818\">139</sup> בטל שעתיד להחיות בו את המתים<sup data-n=\"3819\">138</sup> לע\"ל שבחי' טל תחי' זה זהו למעלה משרש המן כו', ובכדי שיוכלו לקבל בחי' זו, הנה ההכנה לזה הי' מ\"ש ויחן ישראל נגד ההר<sup data-n=\"3820\">140</sup> שנעשו כאיש אחד, והאחדות זהו מדריגה גבוה מאד נעלה שזה מורה שהכלי שלו אינו מגבילנו, ולכן הוא כאיש אחד עם זולתו כו', דהנה מי שאינו יכול לסבול זולתו זהו מצד היותו יש ודבר וגבה רוח עד שזולתו אינו תופס מקום נגדו שיהי' עמו קשור ודבוק באהבת ריעים דבוק מאח, וה\"ז הגבלה שאין כמוהו כו', אבל היותו דבוק מאח עם זולתו ה\"ז הוראה שהגיע לבחי' ביטול שלמעלה מהגבלת הכלי ע\"ד בחי' שיריים כו' ולכן היו נכונים שישרה בחי' המקיף שזכור ושמור בד\"א נא' מה שאין הפה כו' ועכדו\"ד פרחה כו' והחזירם בטל תחי', ומה הראשונים הי' ברצון אף אחרונים ברצון שבחדש אלול ועשי\"ת מאירים יגמה\"ר<sup data-n=\"3821\">141</sup> כמו ואל זה אביט, וזהו אני לדודי ועי\"ז ועלי תשוקתו<sup data-n=\"3822\">142</sup> עלי בחי' מקיף, וכמו ביגמה\"ר דמיכה שצ\"ל עובר על פשע ומשים עצמו כשיריי', ומה שביגמה\"ר דמשה לא נא' דקדוקי' כאילו זהו מפני כי הם לחיי הגוף, שע\"פ מדת האמת הנה אמת א' אל יברא, רק שהגביר בחי' ורב חסד להטות כלפי חסד שיומשך למטה מטה בלי דקדוק, ועכ\"ז ונקה הוא לשבים דוקא, משא\"כ אם אינו שב לא ינקה כו', וזהו שצ\"ל אני לדודי ועי\"ז ודודי לי בבחי' מרעה דשושנים יגמה\"ר, וס\"ת אני לדודי ודודי לי הם ד' יודין<sup data-n=\"3823\">143</sup> שרומזי' לארבעי' יום שמר\"ח אלול עד יוהכ\"פ ותחילתן ר\"ח אלול שבהם הוא הזמן שמאירים בחי' יגמה\"ר כנ\"ל.",[["3814","134","<b>אל תקרי שושנים אלא ששונים</b>: ראה זח\"ב תוספות עדר, א. מאמרי אדה\"א דברים ח\"ד ע' א'קפח. וש\"נ. סידור שער האלול רכז, ג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770423\" data-slug=\"or-hatorah-hb\" data-id=\"8316770423\">אוה\"ת ראה ע' תשפה</a>. וע' תשצא. שה\"ש ח\"ב ע' תקנג וע' תקנו. סה\"מ תרכ\"ו ע' רכה. תרכ\"ז ע' חצר. תרכ\"ט ע' רל. תר\"ל ע' רסט. תרל\"ו ח\"ב ע' שנ. המשך יונתי תר\"ם ע' כט. עטר\"ת ע' תסט. מאמר ד\"ה עשרה שיושבין י\"ג תמוז תשמ\"ב (קונט' י\"ב י\"ג תמוז תש\"נ — סה\"מ מלוקט ח\"ד ע' שט. וש\"נ)."],["3815","135","<b>ואנכי עמדתי בהר</b>: עקב י, י."],["3816","136","<b>מה הראשונים ברצון</b>: ראה רש\"י עקב ט, יח. י, י. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131272\" data-slug=\"likkutei-sichot\" data-id=\"1300131272\">לקו\"ש</a> בין המצרים כרך יג ע' 266 בהערה."],["3817","137","<b>על כ\"ד. . פרחה נשמתן</b>: ראה שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג. וש\"נ. נ\"ך ע' שפא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670525\" data-slug=\"torat-chaim\" data-id=\"2300670525\">תו\"ח בראשית יז, ב</a>."],["3818","139","<b>אותנו</b>: כ\"ה בגוכתי\"ק."],["3819","138","<b>והחי'. . להחיות את המתים</b>: שבת שם."],["3820","140","<b>ויחן ישראל נגד ההר</b>: יתרו יט, ב (בדילוג]. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211104\" data-slug=\"likkutei-sichot\" data-id=\"1300211104\">לקו\"ש יתרו כרך כא ע' 104</a>."],["3821","141","<b>ועשי\"ת מאירים יגמה\"ר</b>: ראה הנסמן לעיל בהערה 5."],["3822","142","<b>אני לדודי. . ועלי תשוקתו</b>: שה\"ש ז, יא. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380852\" data-slug=\"likkutei-torah\" data-id=\"4001380852\">לקו\"ת ראה לד, ב</a>."],["3823","143","<b>וס\"ת אני לדודי. . הם ד' יודין</b>: ראה ר\"ח שער התשובה פ\"ד קטו, ב ד\"ה עוד יש. אוה\"ת שה\"ש ח\"ב ע' תקמו."]]],[2000450364,"<h3>פי' פתחה כו' וידבר ה' כו'</h3>\n<b></b><b>ביאור שני לתו' דהשמי' כסאי </b>\n<b></b><b>בס\"ד ש\"פ תבא ל\"ח לפ\"ק</b>\nישיבה כסא\nתבוא\n<b>פיה</b> פתחה בחכ'<sup data-n=\"3824\">1</sup> ותו' חסד על לשונה<sup data-n=\"3825\">2</sup>, וצ\"ל אם התו' היא תורת חסד, ומה שפתחה בחכ'<sup data-n=\"3826\">3</sup>, הלא מוחין ומדות רחוקי' במעלה מאד כו'. ויובן בהקדם מארז\"ל במד\"ר<sup data-n=\"3827\">4</sup> בא ר\"פ י\"ז, כל מה שברא הקב\"ה לא ברא אלא לכבודו ולעשות בהם רצונו שנא' כל פעל ה' למענהו<sup data-n=\"3828\">5</sup>, מה ברא ביום ראשון שמי' וארץ אף הם לא נבראו אלא לכבודו שנא' השמים כסאי<sup data-n=\"3829\">6</sup> כו' ואומר השמים מספרים<sup data-n=\"3830\">7</sup> כו'. נשמע שמה שהשמים כסאו זהו לכבודו כו' ושהוא ענין א' עם השמים מספרים, וצ\"ל שייכותם זל\"ז.\n<b>ויובן</b> בהקדם עוד ענין<sup data-n=\"3831\">8</sup> השמים כסאי שנת\"ל<sup data-n=\"3832\">9</sup> שהוא תשב\"כ [שהיא כסא לאור א\"ס ב\"ה לבחי' רצונו וחכמתו ובינתו כו']. (ולכאורה צ\"ל ענין בחי' התו' ה\"ה",[["3824","1","<b>פיה פתחה בחכ'</b>: מאמר זה הוא דרוש הראשון — מההמשך — שמבאר פיסקא ראשונה שבביאור השני (על מאמר ד\"ה השמים כסאי) ד\"ה להבין שרשי הדברים הנ\"ל שנדפס במאמרי אדה\"ז תקס\"ה ח\"ב הנחת כ\"ק אדמו\"ר האמצעי ע' תשנט — תשס. והוא דרוש התשיעי מההמשך שבו נתבארו הדרושים דהשמים כסאי ושני ביאוריו שנאמרו בשנת תקס\"ה כמצויין לעיל ברד\"ה ואשא אתכם.\nהמאמר (מלבד הפתיחה וכן הערות שבתוך ההחצע\"ג שנכתבו בגוכתי\"ק) הוא לשון מאמרי אדה\"ז תקס\"ה הנ\"ל עם הגהות הצ\"צ שבאים בתוך חצאי ריבוע. וההגהות שבהחצע\"ג הם מכ\"ק אדמו\"ר מהר\"ש. והדברים המובאים בתוך חצאי עיגול שהם בתוך חצאי מרובע [( )] הם מכ\"ק אדמו\"ר האמצעי שנכתבו במאמרי אדה\"ז הנ\"ל בין חצאי עיגול.\nדרוש זה פרט להפתיחה נדפס גם בלקו\"ת לג\"פ בראשית יא, א ואילך. ובאוה\"ת בראשית כרך ג ע' 940 ואילך [ושם א) הגהות הצ\"צ לא ניתנו בין שני חצאי ריבוע. ב) חסירים הגהות כ\"ק אדמו\"ר מהר\"ש].\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות.\nהכותרת שבריש המאמר: ”ביאור שני לתו' דהשמי' כסאי\" נכתבה בגוכתי\"ק בבוך זה 1089. ועד\"ז נכתבה הכותרת במאמר אדה\"ז (עם הגהות הצ\"צ) שנמצא בבוך 1162 ושם: ”ש\"פ עקב ביאור שני לתו' דהשמי' כסאי\". וכן נכתבה כותרת זו בבוך 1162 על ההגהות למאמר זה ושם: ”הגהות על ביאור שני דתו' השמי' כסאי, שבת\"א,\" ובמפתח המאמרים שבריש בוך זה 1089 גוכתי\"ק כ\"ק אדמו\"ר מהר\"ש: ”פי' פתחה בחכמה (והוא שייך לביאור שני דהשמי' כסאי)\". ובמאמרי אדה\"ז תקס\"ה כאן הכותרת היא: בעז\"ה שבת פ' עקב (ביאור שני לתורה דהשמים כסאי כו' דשבת פ' ואתחנן). והכותרת השני' שבריש המאמר כאן: ”בס\"ד ש\"פ תבא ל\"ח לפ\"ק\" נעתקה (פרט לתיבת בס\"ד שנכתבה בגוכתי\"ק) מהנחת כ\"ק אדמו\"ר מהורש\"ב.\nהפתיחה וכן כמה מהגהות נכתבו בבוך זה 1089. וחלק ההגהות נכתבו בבוך 1162. אודות ביכלאך אלו ראה המצויין לעיל בריש מאמר ד\"ה ואשא אתכם. מתחילה כתב כ\"ק אדמו\"ר מהר\"ש פתיחא אחרת למאמר זה: השמי' מספרי' כבוד אל, ופי' בזהר ח\"ב תרומה קלו\"ב, מאן שמי' כו' וע' בסידור שפי' דברי הזהר, והעביר קו ע\"ז."],["3825","2","<b>פיה פתחה בחכ' ותו' חסד על לשונה</b>: משלי לא, כו."],["3826","3","<b>וצ\"ל. . בחכ'</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן."],["3827","4","<b>במד\"ר</b>: בשינוי."],["3828","5","<b>כל פעל ה' למענהו</b>: משלי טז, ד."],["3829","6","<b>השמים כסאי</b>: ישעי' סו, א."],["3830","7","<b>השמים מספרים</b>: תהלים יט, ב."],["3831","8","<b>ענין</b>: מכאן לערך הוא לשון מאמרי אדה\"ז תקס\"ה כאן."],["3832","9","<b>השמים כסאי שנת\"ל</b>: מאמר ד\"ה ואשא אתכם ובהערה 20."]]],[2000450365,"בחי' גילוי אור כמ\"ש ותורה אור<sup data-n=\"3833\">10</sup>, ושם כסא הוא לשון כיסוי כמ\"ש במ\"א בענין כסא כס אלף<sup data-n=\"3834\">11</sup>, אך הענין הוא דהנה התו' נק' משל הקדמוני<sup data-n=\"3835\">12</sup>, שהיא בחי'<sup data-n=\"3836\">*13</sup> משל להבין בה בחי' אוא\"ס קדמונו ש\"ע<sup data-n=\"3837\">13</sup> ). ויובן ע\"פ הקדמה הידוע בכתבי האריז\"ל בספר לק\"ת בפי' כל פ' בהתחלתה וידבר<sup data-n=\"3838\">14</sup> ה' אל משה דבר אל בנ\"י<sup data-n=\"3839\">15</sup> [שמשה הוא יסוד אבא<sup data-n=\"3840\">16</sup>, וענין וידבר הוי' אל משה היינו ההמשכה מאור א\"ס ב\"ה ליסוד אבא, דבר אל בני ישראל הם נצח והוד<sup data-n=\"3841\">17</sup>], דהנה ידוע דאורייתא מחכמה נפקת<sup data-n=\"3842\">18</sup> היינו שיצאת שרשה מחכמה (ולכאו' צ\"ל הלא נת' בכ\"ד פי' אורייתא מחכ' נפקת, נפקת דוקא אבל שרשה בבחי' הכתר<sup data-n=\"3843\">19</sup>, ואיך אמר<sup data-n=\"3844\">20</sup> כאן שרשה מחכ', אמנם באמת דקדק לומר שיצאת שרשה מחכ', פי' הדברים ששרש יציאתה היינו תחילת גילויה לנו היא יצאת מחכ', אבל שרשה העצמי ע\"ז נא' לא ידע אנוש ערכה<sup data-n=\"3845\">21</sup> רק אלקי' הבין דרכה<sup data-n=\"3846\">22</sup> ובידיעת עצמותו יודע את התורה כו', וא\"כ פי' שיצאת שרשה, ה\"ה כמו מחכ' נפקת שא' שם כו') ונתפשטה ונתלבשה למטה. והענין הוא דשרשה בבחי' אור אבא ומשם יציאתה למטה ונתלבשה בז\"א.\n<b>וביאור</b> הדברים, הנה ידוע דשרש רמ\"ח מ\"ע הן ה\"ח דז\"א<sup data-n=\"3847\">24</sup> ושרש השס\"ה ל\"ת<sup data-n=\"3848\">23</sup> הן בחי' ה\"ג<sup data-n=\"3849\">25</sup> ועד\"מ באדם במדות<sup data-n=\"3850\">26</sup> שבלב הן שולטין במעשיהו",[["3833","10","<b>ותורה אור</b>: משלי ו, כג."],["3834","11","<b>כסא. . כיסוי. . כסא כס אלף</b>: ראה מאמרי אדה\"ז תקס\"ד ע' קמו. סה\"מ תרכ\"ז ע' קנז וע' קפג. המשך מים רבים תרל\"ו פקט\"ז ע' קכא. תו\"ח ח\"ש קל, ב ובהערה 28. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 9."],["3835","12","<b>התו' נק' משל הקדמוני</b>: שמו\"א כד, כג וברש\"י שם. ראה גם הנסמן במאמרי אדה\"א דברים ח\"ב ע' תב. שמות ח\"ב ע' שפג. סה\"מ תרכ\"ז ע' פז. לעיל המשך וידבר וגו' ויצוום פ\"ט ובהערה *176."],["3836","*13","<b>בחי'</b>: בלקו\"ת לג\"פ כאן יא, ב ליתא. אבל כ\"ה בגוכתי\"ק."],["3837","13","<b>קדמונו ש\"ע</b>: ב\"ר פל\"ח, ז. זהר לך פד, א."],["3838","14","<b>כל פ' בהתחלתה וידבר</b>: השווה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 14."],["3839","15","<b>וידבר ה' אל משה דבר אל בנ\"י. . לאמר</b>: ראה המשך תער\"ב ח\"א ע' שדמ שברוב הפרשיות נא' — צו ז, כב. כג. כח. כט. תזריע יב, ב. אמור כג, כג. כד. לג. לד. ועוד (בהוספת תיבת לאמר אחרי תיבת משה). ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381194\" data-slug=\"likkutei-torah\" data-id=\"4001381194\">לקו\"ת שה\"ש טז, ב</a>. המשך תער\"ב שם. ח\"ב ע' א'פד."],["3840","16","<b>שמשה הוא יסוד אבא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."],["3841","17","<b>בני ישראל הם נצח והוד</b>: ראה ת\"ז רתמ\"ח. טעמי המצות וספר הליקוטים להאריז\"ל ר\"פ תשא. מאו\"א מערכת בנ\"י אות נב [וכן צ\"ל באוה\"ת שמות ע' לו] וביאיר נתיב שם. לקמן מאמר ד\"ה וידבר אלה הם מועדי על יד הערה 81 ואילך (ובהנסמן בהערה 1 שם). ו(בחלק ההנחות) בהנחה שם על יד הערה 21. וראה מאמרי אדה\"ז תקס\"ה כאן (הובא בסמוך בפנים) על יד הערה 47: נה\"י דז\"א."],["3842","18","<b>דאורייתא מחכמה נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["3843","19","<b>נפקת. . שרשה בבחי' הכתר</b>: ראה גם לעיל המשך כי תשא פ\"ז הערה 171."],["3844","20","<b>אמר</b>: בלקו\"ת לג\"פ כאן: אומר. אבל כ\"ה בגוכתי\"ק."],["3845","21","<b>לא ידע אנוש ערכה</b>: איוב כח, יג."],["3846","22","<b>אלקי' הבין דרכה</b>: איוב שם, כג."],["3847","24","<b>רמ\"ח מ\"ע הן ה\"ח דז\"א</b>: ראה קו\"א לתניא (ד\"ה להבין מ\"ש בפע\"ח) קנח, ב. הנסמן במאמרי אדה\"א נ\"ך ע' רלה."],["3848","23","<b>רמ\"ח מ\"ע. . השס\"ה ל\"ת</b>: מכות כג, סע\"ב."],["3849","25","<b>השס\"ה ל\"ת הן בחי' ה\"ג</b>: ראה קו\"א לתניא שם."],["3850","26","<b>במדות</b>: וכ\"ה באוה\"ת כאן ע' תעא. במאמרי אדה\"ז תקס\"ה כאן: המדות. בלקו\"ת לג\"פ כאן: בעדות!"]]],[2000450366,"אם לעשות כך ולא לעשות כך כו', כמ\"כ למעלה שרשי המ\"ע ול\"ת נמשכים מבחי' המדות דאצי' מחו\"ג, מבחי' החסדים נמשך שרש מעשה המ\"ע<sup data-n=\"3851\">27</sup> דהיינו שכך וכך יוכשר לעשות ויהי' בו גילוי אלקות (וה\"ז תכלית הטוב והחסד כו') ולא באופן אחר (ומה שלכאורה ע\"פ החסד לא הי' צריך להיות בו דקדוקי' שכך דוקא ולא כך, כמו שהמוותר אינו מדקדק כלל ליתן למי שראוי דוקא, וכמו אברהם שא' לו ישמעאל יחי' לפניך<sup data-n=\"3852\">28</sup>. אך הענין הוא דהנה בתיקון הוא בחי' התכללות, וא\"כ גם החסד כלול מגבורה, וע' בפ' שלח<sup data-n=\"3853\">29</sup> בביאור ועתה יגדל נא בענין המדידה שבכל מצוה כמו סוכה ז\"ט ומשהו<sup data-n=\"3854\">30</sup> שרשו מבחי' גבו' דע\"י שמלובש במו\"ס<sup data-n=\"3855\">31</sup> כו' ששם<sup data-n=\"3856\">32</sup> לית שמאלא<sup data-n=\"3857\">33</sup> כו' (ועמ\"ש במ\"א בענין גבורות גשמים<sup data-n=\"3858\">34</sup>, שהם חיים לעולם, ומענין כי הדם הוא הנפש<sup data-n=\"3859\">35</sup> כו', ומענין איזהו גבור<sup data-n=\"3860\">36</sup> כו' שנא' טוב א\"א מגבור<sup data-n=\"3861\">37</sup> כו'). ונמצא מובן ענין הדקדוק שכזה דוקא יוכשר ולא בא\"א, ומה שאברהם אם<sup data-n=\"3862\">38</sup> היותו מרכבה לחסד דאצי'<sup data-n=\"3863\">39</sup> ועכ\"ז א' לו ישמעאל כו' אפ\"ל שדקדק לומר לפניך<sup data-n=\"3864\">40</sup> שלכאו' ה\"ז מיותר, אלא שהכוונה שיחי' בחיים האמיתי' להיות דבוק בחיי החיים כמ\"ש בנש\"י ואתם הדבקים<sup data-n=\"3865\">41</sup> כו' חיים שנת' במ\"א פי' פסוק זה להיות דבוק",[["3851","27","<b>החסדים. . המ\"ע</b>: ראה זח\"ב תוספות רעו, א. ת\"ז בהקדמה ה, א. ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ד."],["3852","28","<b>לו ישמעאל יחי' לפניך</b>: לך יז, יח. ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 29 ואילך."],["3853","29","<b>וע' בפ' שלח</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381287\" data-slug=\"likkutei-torah\" data-id=\"4001381287\">לקו\"ת שם לט, ד</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380366\" data-slug=\"likkutei-torah\" data-id=\"4001380366\">לקו\"ת במדבר יד, ג</a>."],["3854","30","<b>סוכה ז\"ט ומשהו</b>: ראה גם סה\"מ תרל\"ב ח\"א ע' פד ובהערה שם."],["3855","31","<b>גבו' דע\"י שמלובש במו\"ס</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ו-ז."],["3856","32","<b>ששם. . כו')</b>: כ\"ז נכתב בגוכתי\"ק בעט אחר בבוך 1162 בצד ימיני של הגליון מלמעלמ\"ט. וכן ניתוספה הגה\"ה זו בגוכתי\"ק בבוך זה 1089 בצד הימיני של העמוד. ומזה משמע שהגה\"ה זו ניתוספה לאחר זמן."],["3857","33","<b>לית שמאלא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["3858","34","<b>גבורות גשמים</b>: תענית ב, א. ראה סידור שחרית סא, ד. שער הסוכות רנז, ד. שער הלולב רסד, ב. מאמרי אדה\"ז הנחות הר\"פ ע' נו. תקס\"ב ח\"א ע' לב. ענינים ע' שפ. אמרי בינה שער הק\"ש נא, א ואילך. מאמרי אדה\"א דברים ח\"ד ע' א' תכח ואילך. סה\"מ תרכ\"ז ס\"ע רמט ואילך. וש\"נ."],["3859","35","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a>. מאמרי אדה\"ז הנחות הר\"פ שם. מאמרי אדה\"א ויקרא ח\"ב ע' תצט. סה\"מ תרכ\"ז ר\"ע רנ. ע' רסג."],["3860","36","<b>איזהו גבור</b>: אבות רפ\"ד. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380365\" data-slug=\"likkutei-torah\" data-id=\"4001380365\">לקו\"ת במדבר יד, ב</a>. אוה\"ת משלי כרך א ר\"ע תריד. סה\"מ תרכ\"ט ע' קיז. תרל\"ב ח\"א ע' קסד. ע' שח. ע' שיז."],["3861","37","<b>טוב א\"א מגבור</b>: משלי טז, לב. ראה גם שע\"ת יא, ג. שערי אורה ע' מט. מאמרי אדה\"א הנחות תקע\"ז ע' ריט. אוה\"ת שבועות ע' קצא בשולי היריעה [ובמהדורת תשנ\"ה ע' קצ בפנים]."],["3862","38","<b>אם</b>: כ\"ה בכ\"מ — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["3863","39","<b>מרכבה לחסד דאצי'</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["3864","40","<b>לומר לפניך</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 38. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680196\" data-slug=\"torat-chaim\" data-id=\"2300680196\">תו\"ח תולדות קמד, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540469\" data-slug=\"torat-chaim\" data-id=\"2300540469\">שמות ח\"א לא, סע\"א</a>. מאמרי אדה\"א קונטרסים ע' ריז. לקו\"ש ח\"ש כרך ה ע' 340 ובהנסמן שם."],["3865","41","<b>ואתם הדבקים</b>: ואתחנן ד, ד. ראה גם מאמרי אדה\"א קונטרסים ע' נג ואילך. ר\"ע קלח. ע' קסא. שע\"ת ב. א (בהקדמה). ג, ג. מז, ב. פ, ד. סה\"מ תרל\"ו ח\"ב ע' שלט ואילך. לעיל המשך חייב אדם לברך ספכ\"ה. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 40. ד\"ה גדול יהי' על יד הערה 63."]]],[2000450367,"באוא\"ס חיי החיים<sup data-n=\"3866\">42</sup> האמיתי' כו'. וזהו שא' לו ישמעאל יחי' בבחי' לפניך כו'. ונמצא כי מזה יובן עוד יותר בחי' ריבוי חסד דאברהם שאם היותו יודע טיב מהות ישמעאל, עכ\"ז מצד ריבוי חסדו ביקש וא' לו פי' לואי שיחי' ישמעאל בבחי' לפניך כנ\"ל), ובהיפך בל\"ת שע\"י מעשה זרה לא יהי' בו גילוי אלקות אדרבה יצמצם האור ויסתיר על אור האלקי ויפגום בנפש ובשרשה שבע\"ס<sup data-n=\"3867\">43</sup> (ובבחי' גבורה זו ג\"כ מלובש חסד, שה\"ז הוא תכלית הטוב והחסד שלא יאיר אור האלקי בבחי' זו, בכדי שלא יומשך תוס' יניקה לסט\"א כו') ולכן אסור<sup data-n=\"3868\">44</sup> לעשותו כמו לא תלבש שעטנז<sup data-n=\"3869\">45</sup> וכיוצא כ\"ז נמשכו מבחי' המדות ושרשם למעלה בבחי' נה\"י דאבא שמהם נעשו בחי' מוחין למדות<sup data-n=\"3870\">46</sup> כידוע.\n<b>וזהו</b> וידבר ה' אל משה שהוא בחי' יסוד אבא, דבר אל בנ\"י פי' שתתפשט מבחי' החכמה שבתורה להיות מסתעפים מזה המוחין למדות להיות התחלקות מ\"ע ול\"ת ולבא לבחי' המעשה ממש תפילין גשמיי' וכו', וזהו לבנ\"י שהן בחי' נה\"י דז\"א כי ז\"א נק' ישראל<sup data-n=\"3871\">48</sup> ונו\"ה דז\"א נק' בני<sup data-n=\"3872\">47</sup> ישראל [ועמ\"ש בד\"ה ואלה שמות בנ\"י<sup data-n=\"3873\">49</sup> הבאים מצרימה כו'] לאמר פי' משם יתפשט עוד בכנ\"י הנק' נוק' דז\"א<sup data-n=\"3874\">50</sup> כידוע [וזהו שרש ענין ועשיתם אותם אתם כתיב<sup data-n=\"3875\">51</sup> שהאדם הוא העושה את התורה דהיינו שהוא הגורם המשכה זו שיומשך אור א\"ס בחכמה דהיינו וידבר ה' אל משה כו' ושיומשך מהחכמה אל בנ\"י נו\"ה כו' אשר כל זה הוא ע\"י ואהבת בכל לבבך<sup data-n=\"3876\">52</sup> כו' אם ישים אליו לבו<sup data-n=\"3877\">53</sup>, רוח אמשיך רוח<sup data-n=\"3878\">54</sup> ואייתי רוח וכמ\"ש מזה בד\"ה בכ\"ה בכסלו<sup data-n=\"3879\">55</sup> גבי דם התמיד קודם להטבת שתי נרות וסד\"ה מזוזה מימין<sup data-n=\"3880\">56</sup> כו'].",[["3866","42","<b>חיי החיים</b>: יומא עא, א."],["3867","43","<b>ויסתיר על. . שבע\"ס</b>: במאמרי אדה\"ז תקס\"ה כאן ליתא."],["3868","44","<b>ולכן אסור</b>: במאמרי אדה\"ז תקס\"ה כאן: ואסור."],["3869","45","<b>לא תלבש שעטנז</b>: תצא כב, יא."],["3870","46","<b>נה\"י דאבא. . מוחין למדות</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"ב. מבוא שערים ש\"ב ח\"א ספ\"ג. המשך תער\"ב ח\"א ע' רסז. ח\"ב ע' תתקעט. ח\"ג ע' א'רנא (ושם: נו\"ה דאבא). תו\"א שבהערה 49."],["3871","48","<b>ז\"א נק' ישראל</b>: ראה ע\"ח שער פרטי עי\"מ שכ\"ז, ספ\"ד. שער הקליפות שמ\"ח, פ\"ג. מאמרי אדה\"א דברים ח\"ב ע' שצב. וש\"נ. לקמן מאמר ד\"ה וידבר כו' אלה הם מועדי על יד הערה 81. ו(בחלק ההנחות) בהנחה שם על יד הערה 57."],["3872","47","<b>כי ז\"א. . בני</b>: במאמרי אדה\"ז תקס\"ה כאן: שנק'."],["3873","49","<b>בד\"ה ואלה שמות בנ\"י</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370228\" data-slug=\"torah-or\" data-id=\"3901370228\">תו\"א שמות נ, ד</a>."],["3874","50","<b>בכנ\"י הנק' נוק' דז\"א</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ב כלל יט."],["3875","51","<b>ועשיתם אותם אתם כתיב</b>: בחוקותי כו, ג. ראה זהר בחוקותי קיג, סע\"א. ויק\"ר פל\"ה, ז. ראה גם לעיל מאמר ד\"ה ואשא אתכם ובהערות 55-6."],["3876","52","<b>ואהבת בכל לבבך</b>: ואתחנן ו, ה [בדילוג]."],["3877","53","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["3878","54","<b>רוח אמשיך רוח</b>: ראה זהר תרומה קסב, רע\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדה\"א בראשית ע' רל. וש\"נ."],["3879","55","<b>בד\"ה בכ\"ה בכסלו</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370137\" data-slug=\"torah-or\" data-id=\"3901370137\">תו\"א וישב כט, ג</a>."],["3880","56","<b>וסד\"ה מזוזה מימין</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a>."]]],[2000450368,"<b>ועד\"ז</b> יובן ג\"כ פי' ענין השמים כסאי פי' שמים היינו מאש ומים<sup data-n=\"3881\">57</sup> (והיינו כמארז\"ל נטל אש ומים<sup data-n=\"3882\">58</sup> ופתכן<sup data-n=\"3883\">59</sup> זב\"ז ומהם נעשו שמים) ועיקרו תיבת מים והשין מתיבת אש הוא טפל<sup data-n=\"3884\">60</sup> להיות כי עיקר התורה שנלבשה<sup data-n=\"3885\">62</sup> בז\"א<sup data-n=\"3886\">61</sup> הוא<sup data-n=\"3887\">63</sup> מבחי' החסדים והן המ\"ע והגבורות דל\"ת מעורבים בחסדים הללו [(כי גם הן אינן אלא לתועלת גילוי אור החסדים<sup data-n=\"3888\">64</sup> שע\"י מ\"ע ולא שהן בבחי' גבורות ממש כו' וכמ\"ש במ\"א)], ופי' השמים כסאי היינו שתשב\"כ דנקראת שמים מאש ומים היא נק' כסאי, והטעם לזה יובן תחלה עד\"מ בישיבה של אדם התחתון על הכסא דאנו רואים בזה כמה מדרגות ירידה הא' מה שנכפף קומתו לישב על הכסא שהושפל בזה חב\"ד שבראשו למטה כו', והב' גם כאשר כבר ישב הנה איננו יושב עליה ממש רק בבחי' נה\"י שבו שהן תרין שוקין וכו' ולא בחג\"ת שבו שהרי תרין דרועין ולבו מוגבהים ממעל לכסא [ועמ\"ש מזה בד\"ה ותחת רגליו<sup data-n=\"3889\">65</sup> כמעשה לבנת הספיר], וכמו\"כ<sup data-n=\"3890\">66</sup> יובן הנמשל<sup data-n=\"3891\">67</sup> למעלה הנה אור אבא כלול מי\"ס כידוע ובחי' נה\"י שבו ירדו להתלבש בז\"א כנ\"ל, והרי בחי' ז\"א [שהוא בחי' תורה כי רמ\"ח מ\"ע הם רמ\"ח אברים דמלכא<sup data-n=\"3892\">68</sup> שהוא ז\"א כמ\"ש בד\"ה משה ידבר<sup data-n=\"3893\">69</sup> ושאר דוכתי] הוא בחי'<sup data-n=\"3894\">70</sup> כסא [לבחי' חכמה עילאה] בהיות שמלובש בו בחי' נה\"י דאבא כנ\"ל, וזהו השמים כסאי כו', וגם שלא נתלבש בנה\"י דאבא<sup data-n=\"3895\">71</sup> רק בחי' האחוריים דח\"ע<sup data-n=\"3896\">72</sup> ולא בחי' פנימית [חכמה עילאה וכמ\"ש באגה\"ק ד\"ה עוטה אור כשלמה<sup data-n=\"3897\">73</sup> בענין וראית את אחורי ופני לא יראו], דהנה<sup data-n=\"3898\">74</sup> באמת על<sup data-n=\"3899\">75</sup> כ\"ד ספרים דאורייתא עליהם נא' ותמלא כדה ותעל<sup data-n=\"3900\">76</sup> דהיינו עד\"מ הכד",[["3881","57","<b>שמים היינו מאש ומים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח. לעיל מאמר ד\"ה ואשא אתכם הערה 19."],["3882","58","<b>נטל אש ומים</b>: ראה ב\"ר פ\"ד, ז. לעיל מאמר ד\"ה ואשא אתכם הערה 39."],["3883","59","<b>ופתכן</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה ב\"ה אלקי ישראל על יד הערה 41. וש\"נ."],["3884","60","<b>ועיקרו תיבת מים והשין. . טפל</b>: ראה גם לעיל מאמר ד\"ה ישמח משה ובהערה 60."],["3885","62","<b>שנלבשה</b>: במאמרי אדה\"ז תקס\"ה כאן ובאוה\"ת בראשית כאן שנתלבשה."],["3886","61","<b>התורה שנלבשה בז\"א</b>: ראה ע\"ח שער דרושי הצלם שכ\"ה, דרוש ח. לעיל מאמר ד\"ה על חומותיך ובהערה 47. לקמן על יד הערה 68."],["3887","63","<b>הוא</b>: במאמרי אדה\"ז תקס\"ה כאן: שנק' אורייתא הוא. וכן העתיק הר\"ש סופר כאן. ומחקו כ\"ק אדמו\"ר מהר\"ש."],["3888","64","<b>והגבורות דל\"ת. . לתועלת גילוי אור החסדים</b>: ראה גם סידור שער התפילין טז, ב. יז, סע\"א ואילך. ד\"ח עא, א ואילך. שה\"א ד, ב ואילך. מאמרי אדה\"א נ\"ך ס\"ע צג ואילך."],["3889","65","<b>בד\"ה ותחת רגליו</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370347\" data-slug=\"torah-or\" data-id=\"3901370347\">תו\"א משפטים עח, ב</a>. ג."],["3890","66","<b>וכמו\"כ</b>: במאמרי אדה\"ז תקס\"ה ח\"ב ע' תשס כאן ישנו קטע נוסף שלא הועתק כאן."],["3891","67","<b>יובן הנמשל</b>: במאמרי אדה\"ז תקס\"ה כאן ליתא."],["3892","68","<b>רמ\"ח מ\"ע. . דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["3893","69","<b>בד\"ה משה ידבר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370303\" data-slug=\"torah-or\" data-id=\"3901370303\">תו\"א יתרו סז, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370306\" data-slug=\"torah-or\" data-id=\"3901370306\">סח, ג</a> ואילך."],["3894","70","<b>הוא בחי'</b>: במאמרי אדה\"ז תקס\"ה כאן: נק'."],["3895","71","<b>שלא נתלבש בנה\"י דאבא</b>: שם: מבחי' נה\"י דאור אבא לא נתלבש בז\"א."],["3896","72","<b>דח\"ע</b>: שם: ליתא."],["3897","73","<b>באגה\"ק ד\"ה עוטה אור כשלמה</b>: סי\"ט."],["3898","74","<b>דהנה</b>: במאמרי אדה\"ז תקס\"ה כאן ישנו קטע נוסף שלא הועתק כאן."],["3899","75","<b>על</b>: במאמרי אדה\"ז תקס\"ה כאן וכן העתיק הר\"ש סופר כאן: הנה. ותוקן בגוכתי\"ק על."],["3900","76","<b>ותמלא כדה ותעל</b>: ח\"ש כד, טז. ראה ת\"ז תכ\"א (מו, ב). ביאוה\"ז וישב כה, א. לעיל המשך חייב אדם לברך פכ\"ד ובהערה 879."]]],[2000450369,"הקטן ששואבין בו מים הגדול וידוע דים הגדול הוא בחי' אור אבא<sup data-n=\"3901\">77</sup> והכד שנשאב ממנו הוא בחי' נה\"י<sup data-n=\"3902\">78</sup> שבו שיוצאים ומתלבשים בז\"א וזהו אורייתא מחכ' נפקת כו', ומה שהתורה נק' שמים כסאי הוא למטה מבחי' הכד הזה כי המשכת המצות (היינו גשם דבר הציווים דכתי' בכל התורה כו'<sup data-n=\"3903\">79</sup> ) ממש הוא ע\"י המדות דז\"א כנ\"ל והוא שנק' כסא לגבי כ\"ד ספרים דאורייתא כו' שהן בחי' מוחין לז\"א כו', ועל בחי' הכד הזה נאמר למשה וראית את אחורי<sup data-n=\"3904\">80</sup> כו' והפנימית לא השיג משה וכנראה בתוך כתבי האריז\"ל בסיפור מעשה שהאריז\"ל ראה והשיג רזין דאורייתא בפ' בלק ובלעם שלא הי' יכול לגלותם בס' שנים<sup data-n=\"3905\">81</sup> כו' כי אין ערך מה שלמעלה מן ההשגה למה שבא ונמשך לבחי' השגה ממש, ולפי ערך זה יובן גם אפילו במשה, ומשארז\"ל נובלות חש\"מ תורה<sup data-n=\"3906\">82</sup> יש לפרשו בב' אופנים א' כנ\"ל דבחי' כ\"ד ספרים דאורייתא הוא בחי' אחוריי' דנה\"י דאבא והן מלובשי' במדות כו', והב' עוד למעלה גם מאור אבא כי חכ' שלמעלה הוא בחי' ח\"ס דא\"א כידוע ובחי' הנובלות והאחוריי' משם הוא בחי' הים הגדול דאור אבא הנ\"ל וכמאמר אנת חכים ולא בחכ' ידיעא<sup data-n=\"3907\">83</sup> דהים הרי נק' חכמה כידוע<sup data-n=\"3908\">84</sup> ונמשכת בבחי' נובלות מלמעלה מן החכמה והוא מבחי' חכ' דלא ידיעא כו' [(וע\"ד<sup data-n=\"3909\">85</sup> ב' האופנים הללו ג\"כ יובן במשל ענין כפיפת הקומה לישב שבחי' חב\"ד יורדי' למטה, הא' מבחי' ח\"ע באבא והב' מאבא לז\"א כו')].\n<b>(וע\"פ</b><sup data-n=\"3910\">86</sup> כ\"ז יובן ג\"כ מה שנק' התורה בשם כסא כס לשון כיסוי, דהנה נת\"ל שהתו' נק' משל הקדמוני שהיא בחי' משל להבין בחי' אוא\"ס קדמונו של עולם, ונודע כי המשל תחלה ה\"ה מכסה על הנמשל, שהרי המשל הוא מדבר זר, וכמו משלי שלמה שהמשיל ד\"ת באמרו ראה חיים עם אשה<sup data-n=\"3911\">87</sup> אשר אהבת וכדומה, ועכ\"ז אחרי שיבין כל דברי המשל היטב יובן הנמשל בטוב טעם ודעת מה שא\"א להבין בלתי המשל, שהרי כל ענין המשל הוא בכדי שיובן גם שכל העמוק עמוק מאד",[["3901","77","<b>דים הגדול. . אור אבא</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ר\"ע שח. ח\"ב כאן ע' תשס. תקס\"ו ר\"ע קיג. תקס\"ט ע' ב וע' ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381103\" data-slug=\"likkutei-torah\" data-id=\"4001381103\">לקו\"ת ברכה צד, סע\"א</a> ואילך. וראה גם לקמן (בחלק ההנחות) בהנחה כאן הערה 58."],["3902","78","<b>והכד. . נה\"י</b>: ראה גם מאמרי אדה\"ז תקס\"ה כאן."],["3903","79","<b>(היינו. . כו')</b>: כ\"ז נכתב בגוכתי\"ק בעט אחר בבוך 1162 בצד ימיני של הגליון מלמעלמ\"ט. וכן ניתוספה הגה\"ה זו בגוכתי\"ק בבוך זה 1089 בצד השמאלי של העמוד מלמטלמ\"ע. ומזה משמע שהגה\"ה זו ניתוספה לאחר זמן."],["3904","80","<b>וראית את אחורי</b>: תשא לג, כג."],["3905","81","<b>בתוך כתבי האריז\"ל. . בס' שנים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380244\" data-slug=\"likkutei-torah\" data-id=\"4001380244\">לקו\"ת אמור לט, סע\"ג</a> מובא לעיל בהמשך וידבר וגו' ויצוום פ\"ה ובהערה 104 [ושם: בשמונים שנה. ע' שנה]."],["3906","82","<b>נובלות חש\"מ תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["3907","83","<b>אנת חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה יז, ב."],["3908","84","<b>כידוע</b>: במאמרי אדה\"ז תקס\"ה כאן: ידיעא."],["3909","85","<b>וע\"ד</b>: שם: ועד\"ז. במאמר אדה\"ז עם הגהות הצ\"צ שבבוך 1162 לא הועתק החצע\"ג הזה. והוסיפו כ\"ק אדמו\"ר מהר\"ש בגוכתי\"ק."],["3910","86","<b>(וע\"פ</b>: הוספת החצע\"ג הוא ע\"פ בוך 1162. וכ\"ה בלקו\"ת לג\"פ כאן. ובבוך 1089 כאן: וע\"פ."],["3911","87","<b>ראה חיים עם אשה</b>: קהלת ט, ט."]]],[2000450370,"ג\"כ כמו שכל הגלוי כו'. ועד\"ז יובן בבחי' התו' שאם היותה בחי' אור כמ\"ש ותורה אור, עכ\"ז הנה גשם דבר ההלכות וכל הדברים אשר נצטוינו בתו' נתלבשו בדברים גשמיי' וה\"ז כמו המשל שהוא מדבר זר ובו מלובש שכל עמוק, רק שגשם דבר ההלכה שבתו' ה\"ז עצמו ג\"כ מכוון עמוק שהוא בירור דברים שבנוגה, או הפרדת הסכסוכי' והפירודי' שבין אדם לחבירו כו', משא\"כ משלי' סתם ה\"ה דברים פשוטי' לגמרי כו', ואמנם גם דברי' הגשמי' שבתו' ה\"ה רק כמו המשל בדבר זה<sup data-n=\"3912\">88</sup> שהמשל מכסה על הנמשל עד שיבוא על אמתתן ואז יהי' מובנים הנמשל כו' ומה גם כי לא כל אדם זוכה לזה שיש כו\"כ שלומדי' דברי תו' ואינם מביני' כ\"א פשט דבר ההלכה ולא הנמשל הגנוז בה, וכ\"ש בחי' אור הגנוז שבה שהוא בחי' אור תורה ויש בחי' טל תורה כמ\"ש מזה במ\"א בענין מארז\"ל כל המשתמש באור תו'<sup data-n=\"3913\">89</sup>, ובילקוט טל<sup data-n=\"3914\">91</sup> תורה<sup data-n=\"3915\">90</sup>, וע' בסש\"ב פל\"ז<sup data-n=\"3916\">92</sup>, ונמצא מובן מה שהתו' נק' כסא לשון מכסה כי פשט הדברים מכסים על הגנוז בה, ועוי\"ל שנק' משל הקדמוני לפי שגם התו' כמו שהיא ברוחניות עד\"מ כמו מה שלומדי' בג\"ע<sup data-n=\"3917\">93</sup> כו' ה\"ה רק בחי' משל להבין בחי' אור א\"ס קדמונו של עולם כו', כמ\"ש מזה במ\"א ע' בד\"ה אם כסף תלוה<sup data-n=\"3918\">94</sup>, ונמצא שגם מזה יובן מה שנק' כסא שמכסה כו' עד שנק' רק בשם משל כו') [ועמ\"ש מזה בביאור ע\"פ תורה<sup data-n=\"3919\">95</sup> צוה<sup data-n=\"3920\">96</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> ענין וידבר ה' עצמות אור א\"ס אל משה יסוד אבא דבר אל בנ\"י נו\"ה לאמר מ', וזהו השמים ז\"א תורה כי מ\"ע ה\"ח ול\"ת ה\"ג הן כסא לחכמה שנה\"י דאבא מתלבשים בז\"א, וזהו כד ספרי דאורייתא כד מים החכמה.</span>\n<b>ועפ\"ז</b> יובן מ\"ש<sup data-n=\"3921\">97</sup> ברבות בא ר\"פ י\"ז הה\"ד כל פעל ה' למענהו כו' לכבודו ולעשות בהם רצונו כו' שנא' כה אמר ה' השמים כסאי ואומר השמים",[["3912","88","<b>זה</b>: בלקו\"ת לג\"פ: זר."],["3913","89","<b>כל המשתמש באור תו'</b>: כתובות קיא, ב. ראה סה\"מ תרכ\"ז ע' תסד. תרכ\"ח ע' קפו. תרכ\"ט ע' כו. ע' רצ. ע' תז ואילך. תר\"ל ס\"ע פח ואילך. המשך וככה תרל\"ז פס\"ח ע' קז."],["3914","91","<b>טל</b>: בלקו\"ת לג\"פ נדפס: של. ותיקן הר\"ש סופר עה\"ג: טל."],["3915","90","<b>ובילקוט טל תורה</b>: בסה\"מ תרכ\"ז ע' רצו־ תרל\"ב ח\"א ע' קעא־ ע' שכג־ המשך מים רבים תרל\"ו פקע\"ה (ס\"ע קצג ואילך) מציין: ובילקוט ישעי' ברמז רצ\"ח [והוא ע\"פ דפוס וויניציאה שכ\"ו וההולכים בעקבותיו]. ראה יל\"ש ישעי' כו, יט (רמז תלא)."],["3916","92","<b>בסש\"ב פל\"ז</b>: בהמשך מים רבים תרל\"ו פקע\"ד (ופקע\"ה)־ וככה שבהערה 89: ספל\"ו."],["3917","93","<b>התו'. . ברוחניות. . בג\"ע</b>: ראה גם לעיל המשך חייב אדם לברך פכ\"ח. וש\"נ."],["3918","94","<b>בד\"ה אם כסף תלוה</b>: לע\"ע לא נתברר לאיזה דרוש מתכוין. ראה גם לעיל המשך וידבר וגו' ויצוום פ\"ט ובהערה *176."],["3919","95","<b>ע\"פ תורה צוה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381107\" data-slug=\"likkutei-torah\" data-id=\"4001381107\">לקו\"ת ברכה צה, סע\"א</a> ואילך."],["3920","96","<b>צוה</b>: בלקו\"ת לג\"פ כאן: צוה]."],["3921","97","<b>ועפ\"ז יובן מ\"ש</b>: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480221\" data-slug=\"or-hatorah-hb\" data-id=\"8316480221\">אוה\"ת בראשית כאן ע' 942</a> ובלקו\"ת לג\"פ: הג\"ה. והנה ברבות [וסיום ההג\"ה הוא לקמן בסיום הקיצור]. וכן העתיק הר\"ש סופר בבוך 1089 כאן. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."]]],[2000450371,"מספרים כבוד אל, ובזח\"ב תרומה קלו\"ב מאן שמים כו' ובמק\"מ<sup data-n=\"3922\">98</sup> היינו ז\"א שביום השבת מאירים בו מוחין דגדלות מאו\"א משא\"כ בחול מאיר רק מוחין דיניקה<sup data-n=\"3923\">99</sup>, וזהו מספרים לשון בהירות<sup data-n=\"3924\">100</sup> כמראה אבן ספיר<sup data-n=\"3925\">101</sup>, וגם מספרים שמאיר בו מבחי' סופר וספר וסיפור שהם חב\"ד<sup data-n=\"3926\">102</sup> וכמשנ\"ת בסדור ע\"פ השמים מספרים<sup data-n=\"3927\">103</sup> כו', ועיין מענין מוחין דיניקה ומוחין דגדלות בד\"ה ביאור ע\"פ משה ידבר<sup data-n=\"3928\">104</sup> כו' יעו\"ש ובסדור ע\"פ השמים מספרים<sup data-n=\"3929\">105</sup>, ועפ\"ז יובן שע\"י עסק התורה הנק' ספר וע\"י תשבע\"פ שהיא נק' דברי סופרים בחי' סופר שלמעלה מבחי' ספר כמ\"ש בד\"ה ולא אבה<sup data-n=\"3930\">106</sup> בפ' תצא ובד\"ה שחורה אני ונאוה<sup data-n=\"3931\">107</sup> עי\"ז ממשיכים מוחין דגדלות לז\"א מלמעלה מבחי' נה\"י דאבא רק שעוברים דרך נה\"י וזהו ג\"כ ענין השמים כסאי כו' שנמשך על זה מבחי' ועתיק יומין יתיב<sup data-n=\"3932\">108</sup> כמ\"ש בגמרא פ\"ב דחגיגה דף י\"ד ע\"א, וזהו מספרים כבוד אל כבוד הוא ל\"ב נתיבות החכמה<sup data-n=\"3933\">109</sup> כו', וזהו לכבודו ולעשות בהם רצונו כו', ועמ\"ש בלק\"ת בד\"ה האזינו השמים דרוש השני<sup data-n=\"3934\">110</sup> בפירוש העידותי בכם היום את השמים ואת הארץ (וזהו<sup data-n=\"3935\">111</sup> פי' פתחה בחכ' ותורת חסד על לשונה, פי' שאם היות שעיקר בבחי' החסד, שנק' שמים בחי' אש ומים כו' עכ\"ז פי' פתחה בחכמה, פי' פיה היינו גילויה כי פה המדבר הוא המגלה העלם שבו לבוא לידי גילוי זולתו כו', ופיה היינו גילוי' פתיחתה היינו ראשיתה היא בחכ' כנ\"ל שתחילת גילוי' הי' מחכ', או י\"ל פי' המדבר ולומד ד\"ת פתחה בחכ' עושה פתח ומבוא גילוי בחי' חכים ולא בחכ' ידיעה בחכ' ידיעה שהוא בחי' אבא דאצי' כו'<sup data-n=\"3936\">112</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> וברבות דהשמים כסאי והשמים מספרים ענין א' והיינו שמאירים מבחי' סופר ספר וסיפור ע\"י עסק התורה שנק' ספר וערבים עלי דברי סופרים<sup data-n=\"3937\">113</sup>, והיינו המשכת מוחין דגדלות לז\"א, וזהו וע\"י יתיב, עכ\"ה<sup data-n=\"3938\">114</sup>. </span>",[["3922","98","<b>ובזח\"ב תרומה. . ובמק\"מ</b>: ראה אוה\"ת תהלים כרך ב ע' תתקכז."],["3923","99","<b>מוחין דגדלות. . דיניקה</b>: נסמן בסמוך בפנים."],["3924","100","<b>מספרים לשון בהירות</b>: ראה גם סידור שחרית לשבת קעח, סע\"ד. פיה\"מ פ\"י ו, ב."],["3925","101","<b>כמראה אבן ספיר</b>: יחזקאל א, כו."],["3926","102","<b>סופר וספר וסיפור שהם חב\"ד</b>: ראה גם לעיל המשך כי תשא פ\"ו על יד הערה *123 בשם הפרדס."],["3927","103","<b>בסדור ע\"פ השמים מספרים</b>: שחרית לשבת קעט, א."],["3928","104","<b>בד\"ה ביאור ע\"פ משה ידבר</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370306\" data-slug=\"torah-or\" data-id=\"3901370306\">תו\"א יתרו סח, ג</a>."],["3929","105","<b>ובסדור ע\"פ השמים מספרים</b>: שחרית לשבת קעח, ג."],["3930","106","<b>בד\"ה ולא אבה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380871\" data-slug=\"likkutei-torah\" data-id=\"4001380871\">לקו\"ת תצא לח, ג</a>."],["3931","107","<b>ובד\"ה שחורה אני ונאוה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381157\" data-slug=\"likkutei-torah\" data-id=\"4001381157\">לקו\"ת שה\"ש ז, א</a>."],["3932","108","<b>ועתיק יומין יתיב</b>: דניאל ז, ט."],["3933","109","<b>כבוד הוא ל\"ב נתיבות החכמה</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"א מערכת כבוד. מאמרי אדה\"א בראשית ע' ג ואילך. דברים ח\"ב ע' שפ. וש\"נ."],["3934","110","<b>בלק\"ת בד\"ה האזינו. . השני</b>: עג, ד."],["3935","111","<b>(וזהו</b>: הגה\"ה זו בגוכתי\"ק ניתוספה בבוך זה 1089 בשולי היריעה."],["3936","112","<b>כו'</b>: כנצ\"ל: כו')."],["3937","113","<b>וערבים עלי דברי סופרים</b>: ראה ע\"ז לה, א וברש\"י שם."],["3938","114","<b>עכ\"ה</b>: כ\"ה גם באוה\"ת בראשית ובלקו\"ת לג\"פ כאן. אבל לכאורה היא מיותרת ראה לעיל הערה 97."]]],[2000450372,"<h3>להבין ענין הנוסח כו' באש הצתה כו'</h3>\n<b>בס\"ד</b>\n<b>להבין</b> ענין הנוסח<sup data-n=\"3939\">1</sup> שתיקנו אנשי כנה\"ג<sup data-n=\"3940\">2</sup> כי אתה ה' באש הצתה ובאש אתה עתיד לבנותה כאמור ואני אהי' לה<sup data-n=\"3941\">3</sup> חומת אש סביב, ולכבוד כו'. וגם צ\"ל הלא בקרא נא' רק שיהי' חומת אש סביב ולא שהבנין יהי' מאש, או שיבנה באש כו'. דלכאו' נא' כאן רק שסביב יהי' אש, וכבוד יהי' בתוכה, אבל מה תהי' העיר ובמה תבנה לא נא' כלל, וא\"כ מאין לקחו אכה\"ג לתקן נוסח הנ\"ל ואיזהו פי' פירשו בפסוק זה כו'. אך הענין הוא דהנה עיקר הבנין הוא המקיים את הדבר ומחזקו ומשמרו כי בלתי זה איננו שוה כלום כו', וכמו ואתה משמרה בקרבי<sup data-n=\"3942\">4</sup> שזהו עיקר יסוד קיום",[["3939","1","<b>להבין ענין הנוסח כו' באש הצתה</b>: בבוך 1089 בא מאמר זה לבסוף הספר היינו אחרי מאמר ד\"ה מה יפו הנדפס לקמן. וסודר כאן ע\"פ רשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש שנדפס בס' התולדות שלו.\nברשימת המאמרים שבריש הספר גוכתי\"ק נרשם: להבין ענין הנוסח כו' באש הצתה ובאש אתה עתיד לבנותה, מיוסד על הש' רי\"ל (השריפה רחמנא יצילנו — רשימת מאמרי דא\"ח כאן) שהי' בסוף קיץ תרל\"ח ה\"י, ולא' נא' כלל, וסיום הדרוש צריכי' להעתיק מן ביאור צדקת פרזונו בס' תקס\"ה.\nברשימת המעתיק מהמאמרים שבריש הספר העתיק את הנ\"ל. וכנראה שלאחר זמן הוסיף בצד ימין של העמוד: אח\"כ נא' במוש\"ק, אחר ההצלה מהלאמפ' שנפל, ואיזה ש\"ק נצרך לשאול מרממ\"זא או רד\"ץב שהי' ש\"ק הנ\"ל.\nברשימות חוב' קפד ע' 5: בוך תרל\"ח מאמר ד\"ה להבין ענין הנוסח כי באש הצתה וגו'.\nבמפתחות ששיך [ששייך] לנפילת הל מ‘: בחדר מהרשנ\"ע היו תלוי ל מ‘ זכוכית וע נעצי„ני עם קנים וכו' גדול ויפה. פעם נפל מן התקרה. נשבר מקצתו ונשפך הקער סיְן שבו ונדלקה אש. אדנ\"ע הי' מכין אז א\"ע להכנס ליחידות. רץ אל החדר אר געח„‘ט בגד שעליו און ארום גע-וְוקעלט על מהרשנ\"ע וכבתה האש. חלק מהרצפה בער ג\"כ.\nראה לקמן בחלק ההנחות הנחה מכ\"ק אדמו\"ר מהורש\"ב נ\"ע, ושם הפתיחה היא: לה\"ע השריפה ובכותרת: ש\"פ תבא ביחי' ל\"ח לפ\"ק ומה שנרשם בהערה 1 שם. וכן לקמן הנחה ד\"ה ענין הפחד ובכותרת: א' דיו\"ט בסעודת צהרים.\nנדפס בקונט' בפ\"ע — מאמר ד\"ה להבין כו' באש תרל\"ח בראשו היכל מנחם וכן החותמת היכל מנחם, עש\"ק פ' שמיני פרשת החודש, שמבה\"ח ניסן ה'תשנ\"ז חמ\"ד (עם מ\"מ, פיענוח ר\"ת, צילום ע' ראשון מגוכתי\"ק). הדפסה שני' (עם תיקונים וכו') החותמת קה\"ת."],["3940","2","<b>הנוסח שתיקנו אנשי כנה\"ג</b>: בשמו\"ע — תפלת נחם — לט\"ב. ראה ירושלמי ברכות פ\"ד, ה\"ג. תענית פ\"ב, ה\"ב. רי\"ף ספ\"ד דתענית סתת\"מ. רמב\"ם הל' תפלה פ\"ב, הי\"ד ובסדר תפלות שבסו\"ס אהבה (בנוסח ברכות התפלה וסידורן לאחרי ברכת שים שלום). רא\"ש פ\"ד דתענית סל\"ד."],["3941","3","<b>ואני אהי' לה</b>: זכרי' ב, ט [בדילוג]."],["3942","4","<b>ואתה משמרה בקרבי</b>: ברכת אלקי נשמה מברכות ס, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380714\" data-slug=\"likkutei-torah\" data-id=\"4001380714\">לקו\"ת דברים א, א</a>. מאמרי אדה\"ז תקס\"ג ח\"א ע' קד ואילך. מאמרי אדה\"א נ\"ך ע' תסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540646\" data-slug=\"torat-chaim\" data-id=\"2300540646\">תו\"ח שמות ח\"א ז, ג</a>. וש\"נ. אוה\"ת שמות כרך ז ע' ב'תקיח. סה\"מ תרס\"ב ע' קסב ואילך. תרצ\"ט ע' 227 ואילך. תניא עם ליקוט פירושים פ\"ב סי\"ט ע' ע."]]],[2000450373,"הנפש כנודע ממ\"ש במ\"א באריכות וכן יובן בבנין בית ועיר אלקינו, הנה כתי' אם ה' לא יבנה בית<sup data-n=\"3943\">5</sup> שוא עמלו כו' להיות כי עיקר קיום הדבר הוא ע\"י מה שה' בונה, והיינו ע\"י שמקיימו ומשמרו שזהו עיקר דבר הבנין ומאחר שאמר אהי' לה חומת אש, המובן מזה שמלבד מה שישמור בנינה הנה השמירה תהי' בחומת אש כו', ולכן למדו אכנסה\"ג ואמרו ובאש אתה עתיד לבנותה כלומר לשמור ולחזק בנינה כו'.\n<b>אך</b> עדיין צ\"ל מהו מעלתה שיהי' לה חומת אש, ולכאו' ע\"ד הפשוט י\"ל שכאשר יהי' לה חומת אש הגם כי לא נא' ממה תהי' עצם העיר, אמנם מובן שאיננה יריאה מן האש עכ\"פ א\"כ לא תהרוס ע\"י האש כמו בחורבן בהמק\"ד, אך הנה באמת יש מעלה יתירה בזה שתהי' בנינה ע\"י האש דוקא, דהנה ארז\"ל בספ\"ק דיומא דך\"א ע\"ב ששה אישות הן כו' אש אוכלה אש דשכינה, וא\"כ כשאומר באש אתה עתיד כו' היינו באש שלו שאש אוכלה אש כו'. ויובן זה מענין אשא תכלה<sup data-n=\"3944\">6</sup> דתכלת דאכיל ושצי, והיינו בחי' בירור הבירורי' שע\"י אכילת אש זה אוכל ושורף את בחי' האש זרה כו', ועד\"ז יובן בדקות יותר ענין בחי' אש אוכלה אש דשכינה כו'. אך עדיין צ\"ל הלא לע\"ל הכוונה היא לכאו' בגמר שלימות הבירורים, והגם שבימוהמ\"ש תהי' עיקר עשיית המצות כמ\"ש ושם נעשה לפניך כמצות רצונך<sup data-n=\"3945\">7</sup> עכ\"ז לא תהי' ע\"ד בירור דעכשיו כמ\"ש בלק\"ת<sup data-n=\"3946\">8</sup> בביאור דכי ע\"כ כבוד חופה בסופו, וא\"כ אינו שייך לומר על בחי' האש ע\"ד דאכיל ושצי דתכלת. אך הענין הוא דהנה אנו רואים שטבע האש חלוק מכל הג' יסודות דעמ\"ר שג\"י עמ\"ר הנה ע\"מ הם כל השפעתם בדרך ירידה מלמעלמ\"ט כי מים יורדים מגבוה לנמוך<sup data-n=\"3947\">9</sup>, וכ\"ש עפר כו', וגם רוח ישנן<sup data-n=\"3948\">10</sup> בדרך עלי' ובדרך ירידה כטבע הרוח להעלות ולהוריד<sup data-n=\"3949\">11</sup> וכמ\"ש ורוח ה' ישאך<sup data-n=\"3950\">12</sup>, וכתי' ויעל אלי' בסערה<sup data-n=\"3951\">13</sup> כו', וכן הנה ירידת גשמי' הוא ע\"י הרוח<sup data-n=\"3952\">14</sup> כו', וכמאמר רז\"ל זיקא דמקמי מיטרא ובתר מיטרא<sup data-n=\"3953\">15</sup>, אבל יסוד האש הנה הוא רק עולה<sup data-n=\"3954\">16</sup> לבד ואינו יורד כלל, וגם הוא הדק יותר מכל היסודות כו', ולכן פי' רבינו ז\"ל במ\"א",[["3943","5","<b>אם ה' לא יבנה בית</b>: תהלים קכז, א."],["3944","6","<b>אשא תכלה</b>: ראה זהר בראשית נא, א. ב."],["3945","7","<b>ושם נעשה לפניך כמצות רצונך</b>: מוסף ליו\"ט [בדילוג]. ראה ד\"ה אוסרי לגפן תקס\"ד נדפס ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680037\" data-slug=\"torat-chaim\" data-id=\"2300680037\">תו\"ח ויחי רלו, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680164\" data-slug=\"torat-chaim\" data-id=\"2300680164\">רלח, א</a>. מאמרי אדה\"א שמות ח\"א ע' רכו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541070\" data-slug=\"torat-chaim\" data-id=\"2300541070\">תו\"ח שמות ח\"א כב, ג</a>. וש\"נ."],["3946","8","<b>כמ\"ש בלק\"ת</b>: שה\"ש מח, א-ב."],["3947","9","<b>מים יורדים מגבוה לנמוך</b>: ראה תענית ז, א."],["3948","10","<b>ישנן</b>: אוצ\"ל ישנו."],["3949","11","<b>כטבע הרוח להעלות ולהוריד</b>: ראה מאמרי אדה\"ז תקס\"ט ע' רכו ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670473\" data-slug=\"torat-chaim\" data-id=\"2300670473\">תו\"ח בראשית מב, סע\"ג</a>. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 13. המשך מים רבים תרל\"ו פק\"ה ואילך. סה\"מ תרפ\"ט ע' 134. וראה גם מאמרי אדה\"א הנחות תקע\"ז ע' נ. וש\"נ. סה\"מ תרס\"א ע' קעו."],["3950","12","<b>ורוח ה' ישאך</b>: מל\"א יח, יב."],["3951","13","<b>ויעל אלי' בסערה</b>: מל\"ב ב, יא."],["3952","14","<b>ירידת גשמי' הוא ע\"י הרוח</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 14."],["3953","15","<b>זיקא דמקמי מיטרא ובתר מיטרא</b>: ראה תענית ג, ב. מאמרי אדה\"ז־ תו\"ח־ המשך מים רבים שבהערה 36. מאמרי אדה\"א במדבר ח\"ב ע' תרמג."],["3954","16","<b>יסוד האש. . רק עולה</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 15."]]],[2000450374,"שיסוד האש הוא נגד בחי' מדבר<sup data-n=\"3955\">17</sup> כו', וכנודע שיסוד האש הוא תחת גלגל הירח<sup data-n=\"3956\">18</sup>, ויובן ביאור הענין דהנה ארז\"ל בסנהדרין דל\"ח ע\"א<sup data-n=\"3957\">19</sup> אלקיכם כהן הוא, כד<sup data-n=\"3958\">20</sup> קברי<sup data-n=\"3959\">21</sup> למשה במאי טביל כו' אלא בנורא, כי עיקר הטבילה היא בנורא כמ\"ש וכל דבר אשר לא יבא באש<sup data-n=\"3960\">22</sup> תעבירו במים, הרי עיקר הטבילה הוא בנורא, וכן זיכוך הנשמות הוא טבילה בנהר דינור<sup data-n=\"3961\">23</sup> לשכוח על השגתה הראשונה בכדי שתוכל להנות מנופת צוף טעם בחי' הגבוה יותר כו', ולכן בין כל עלי' צ\"ל טבילה בנהר דינור. והענין הוא דהנה אנו רואי' פעולת האש הוא לכלות כל דבר אשר תאחז בה, להיות כי כ\"ד מורכב הוא מד\"י<sup data-n=\"3962\">24</sup>, וע\"י האש יוצאים ג' יסודות דאמ\"ר בעשן זולת יסוד העפר<sup data-n=\"3963\">25</sup> שנשאר ממנו אפר שהוא כמו העפר<sup data-n=\"3964\">26</sup>, ועכ\"ז ה\"ה משתנה ממהות למהות ג\"כ שלכן צ\"ל שאפר כשר לכיסוי הדם<sup data-n=\"3965\">27</sup> נשמע שהי' באפשר לומר שאינו כשר, ונמצא מובן שחילוק יסודות המורכבים הוא ע\"י יסוד האש דוקא. וכתי' גם את העולם נתן בלבם<sup data-n=\"3966\">28</sup> שבירר<sup data-n=\"3967\">*29</sup> כל ד\"י שבעולם תלוי באדם דוקא והיינו ע\"י בחי' בירור ד\"י שבאדם עצמו<sup data-n=\"3968\">29</sup> כו', והוא כי עיקר סיבת נפילת האדם בעברו על אחת ממצות ה' אשר לא תעשינה ואשם<sup data-n=\"3969\">30</sup>, או העדר עשיית מ\"ע זהו מצד חומר גופו הגס והגשמי הניזון מדברים הגשמיי' הגסים, אשר עי\"ז שולט בו יותר תאוות ומזימת לב יצרו הרע המסיתו ומדיחו מדרך הטוב והישר דרכי הוי' לילך דרך עקלתון שבור כרה לו ויחפרהו<sup data-n=\"3970\">31</sup> בו, ואם<sup data-n=\"3971\">32</sup> כי באמת עיקר מכון<sup data-n=\"3972\">33</sup> יצרו הרע הוא שלא יאבה ולא יומשך",[["3955","17","<b>שיסוד האש. . מדבר</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"י. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קנא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670073\" data-slug=\"torat-chaim\" data-id=\"2300670073\">תו\"ח בראשית יט, ג</a>. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 12. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061123\" data-slug=\"likkutei-sichot\" data-id=\"1300061123\">לקו\"ש יתרו כרך ו ע' 112</a> הערה 42."],["3956","18","<b>שיסוד האש הוא תחת גלגל הירח</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא פי\"ט</a> בשם הע\"ח. מהדו\"ק שם ע' קלב הערה 5. המשך תער\"ב ח\"ג ע' א'שכט מספורנו בראשית א, ב. לקו\"ב לשער היחוד קסט, ד בשם פלוסופים הראשונים. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370432\" data-slug=\"torah-or\" data-id=\"3901370432\">תו\"א מג\"א צו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">צז, א</a>."],["3957","19","<b>בסנהדרין דל\"ח ע\"א</b>: בסה\"מ תרכ\"ז ע' רעג־ תרכ\"ח ע' פז־ תרכ\"ט ע' קפו: דל\"ט. — ראה שם בשינוי לשון."],["3958","20","<b>כד</b>: כ\"ה בר\"ח שם."],["3959","21","<b>קברי</b>: כנצ\"ל: קברי'."],["3960","22","<b>וכל דבר אשר לא יבא באש</b>: מטות לא, כג [בהוספת תיבת: דבר — המובא בריש הכתוב. חלקו הראשן של הכתוב הובא גם בר\"ח ובע\"י כאן]."],["3961","23","<b>טבילה בנהר דינור</b>: ראה זהר מקץ רא, א. ויקהל ריא, ב. סה\"מ תרכ\"ט ע' צח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540540\" data-slug=\"torat-chaim\" data-id=\"2300540540\">תו\"ח שמות ח\"א ה, ד</a>. וש\"נ."],["3962","24","<b>כ\"ד מורכב הוא מד\"י</b>: ראה רמב\"ם רפ\"ד מהל' יסוה\"ת."],["3963","25","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">וע\"י האש יוצאים ג</a>' יסודות. . העפר</b>: ראה גם אגה\"ק סט\"ו. תו\"א וישלח כו, רע\"ד. ביאוה\"ז נח ז, ג. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שז. ח\"ב ע' תרסז. כתובים ח\"א ע' מו. תקס\"ה ח\"ב ע' עדרת. לקו\"ת חוקת נו, ג. מאמרי אדה\"א במדבר ח\"ד ע' א' שצ ואילך (ובשולי היריעה שם). ש\"א מז, א."],["3964","26","<b>אפר שהוא כמו העפר</b>: ראה גם ש\"א שם מז, ב."],["3965","27","<b>שאפר כשר לכיסוי הדם</b>: ראה חולין פח, ב. תוד\"ה מצינו שם. שו\"ע יו\"ד הל' שחיטה סכ\"ח, סכ\"ג. תו\"א וישלח שם."],["3966","28","<b>גם את העולם נתן בלבם</b>: קהלת ג, יא. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380329\" data-slug=\"likkutei-torah\" data-id=\"4001380329\">לקו\"ת במדבר ה, ב</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקעט. ע' תרמ. אוה\"ת בלק ע' תתקמ."],["3967","*29","<b>שבירר</b>: אוצ\"ל: שבירור."],["3968","29","<b>ד\"י שבאדם עצמו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a>."],["3969","30","<b>ממצות ה' אשר לא תעשינה ואשם</b>: ויקרא ד, כז."],["3970","31","<b>שבור כרה. . ויחפרהו</b>: ע\"פ תהלים ז, טז."],["3971","32","<b>ואם</b>: כ\"ה בכ\"מ — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["3972","33","<b>מכון</b>: ב: מכוון."]]],[2000450375,"אחר מזימותיו וכמ\"ש בזהר ממשל הזונה עם בן המלך<sup data-n=\"3973\">34</sup>, עכ\"ז זהו כמו שהוא בשרשה ששט\"ן ופנינה לש\"ש נתכוונו<sup data-n=\"3974\">35</sup>, וגם למטה עיקר פנימיותו היינו הטוב שמחי' אותו הוא ג\"כ בחי' טוב והיינו שלא יציית אותו, אך בחי' חיצונותו הנראה ונגלה לעין כל הנה הוא מסית ומדיח בכל מיני הסתות להראות לו איך שטוב לו מאד כן, וכן איך שפלוני עושה כל זה וה' מצליח לו, ואינו מראה לו שיבין שמשלם לו הטוב בעוה\"ז כמ\"ש ומשלם לשונאיו<sup data-n=\"3975\">36</sup> כו', עד שע\"י הססותיו הרבים הנה מי שגופו גס יותר, במהרה יותר ילכד במצודתו הפרושה על דרכי חיי בני האדם הרוחני' והגשמיי', כי יורד ומסטין ועולה ומקטרג<sup data-n=\"3976\">37</sup>, וכמ\"ש תיסרך רעתך<sup data-n=\"3977\">38</sup> שהרע בעצמו הוא המייסר את האדם ונוקם נקמתו בו ר\"ל על אשר הטה מעומק פנימיות כוונתו לאחוז בחיצוניותו ולצייר ציור רע בכח המתאווה שבו שהוא בעצם רק כח המתאוה לבד כמ\"ש מזה במ\"א ע' בדרושי פרה אדומה<sup data-n=\"3978\">39</sup>, ולכן ציור הרע שצייר בכח המתאוה שבו הנה גם הוא נוסף על שונאו הוא יצרו הרע, וזהו שאמר רעתך היינו רע שלך שאתה עשיתו רע, הן ביצה\"ר והן בכח המתאוה כו', ולכן הם הם המה המיסרים אותו ונוקמי' נקמתו בו כו'. ולכן עיקר הטהרה הוא באש דוקא, להיות כי הוא עיקר המצרף ומלבן, כי זהו מדה במדה כו', כי הרי עיקר החטא הוא בבחי' האש זרה שבו שבוער בקרבו להבת שלהבת עד שגומר מעשה הרע, ולכן בצדיקים וחסידים שבעולם מצינו שצווח נורא בי' עמרם<sup data-n=\"3979\">40</sup> בכדי להציל א\"ע מזה כו', הרי שכינה את הרע בשם אש שהוא הוא הבוער בקרבו לכלותו ולהאבידו מדרך הטוב כו'. ולאו דוקא בכגון דא במעשה שהי' שם כ\"א בכל עניני ציור הרע המקור הוא יסוד האש שבו שהרי גם בפגמי המוח כמו הגסות שהוא רמות רוחא שעיקר הוא מטמא המוח ורוח החיים שבו, שלכן נק' בשם רמות רוחא, גבה עינים ורחב לבב<sup data-n=\"3980\">41</sup> שזהו חב\"ד בכלל, ולכן נק' אבי אבות הטומאה<sup data-n=\"3981\">42</sup> כו' כמ\"ש מזה במ\"א באריכות, הנה גם בזה המביאו לידי זה הוא בחי' האש בו שמצייר בו ציור רע, והיינו בקנאו את קנאתו<sup data-n=\"3982\">43</sup> מדוע גם לו לא ינהגו כבוד כמו לאיש החכם והמצוין במעשיו, הלא גם הוא ביכולתו כמו הנ\"ל וכאשר תבעור בו אש הקנאה ורמות רוחו נקט לו הנה יצא גם לפועל שיכעס ויריב אם זולתו שמלבד האש הבוער בקרבו הנה תצא ממנו אש זרה זו לאכול מכעיסיו, מפני אשר לפי היקוד אש שבקרבו גוזל זולתו אותו במה שניתן הכבוד או שא\"ד לזולתו אשר לפ\"ד שלו הוא כו'.",[["3973","34","<b>בזהר ממשל הזונה עם בן המלך</b>: תרומה קסג, א. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא פ\"ט</a> ופכ\"ט ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680131\" data-slug=\"torat-chaim\" data-id=\"2300680131\">תו\"ח מקץ רטז, ד</a> הערה 67."],["3974","35","<b>ששט\"ן ופנינה לש\"ש נתכוונו</b>: ב\"ב טז, א. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תעו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670327\" data-slug=\"torat-chaim\" data-id=\"2300670327\">תו\"ח נח נא, א</a>."],["3975","36","<b>ומשלם לשונאיו</b>: ואתחנן ז, י."],["3976","37","<b>יורד ומסטין ועולה ומקטרג</b>: כ\"ה גם בסה\"מ תרל\"ב ח\"א ע' לז. מאמרי אדה\"א קונטרסים ע' רה. וש\"נ. וראה ב\"ב טז, א."],["3977","38","<b>תיסרך רעתך</b>: ירמי' ב, יט. ראה גם שע\"ת ו, ג ובהנסמן במ\"מ לשם."],["3978","39","<b>בכח המתאווה. . בדרושי פרה אדומה</b>: ראה לקו\"ת חוקת נו, סע\"ג ואילך. לעיל המשך חייב אדם לברך פכ\"ח ובהערה 1103."],["3979","40","<b>נורא בי' עמרם</b>: קדושין פא, א."],["3980","41","<b>גבה עינים ורחב לבב</b>: תהלים קא, ה."],["3981","42","<b>אבי אבות הטומאה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381188\" data-slug=\"likkutei-torah\" data-id=\"4001381188\">לקו\"ת שה\"ש יד, ד</a>. המשך תער\"ב ח\"ב ע' א'מז. הלשון — ראה לעיל מאמר ד\"ה בנים אתם הערה 127."],["3982","43","<b>בקנאו את קנאתו</b>: ע\"פ פינחס כה, יא."]]],[2000450376,"<b>והנה</b> כ\"ז הוא עבודת האדם לגרש הרע שבו ולבררו, וצא יאמר לו והוא ע\"י שמעורר בקרבו אהבה ברשפי אש השלהבת לאלקות כמ\"ש רשפיה רשפי אש<sup data-n=\"3983\">44</sup> שלהבת יה, ולהיות קשור ודבוק לאלקות כשלהבת הקשורה בגחלת<sup data-n=\"3984\">45</sup> שבעבודה היא בחי' רשפי אש התשוקה מקרב ולב עמוק בבחי' פנימיות נקודת נפשו בבחי' רעו\"ד<sup data-n=\"3985\">46</sup> מעומק נקודת הלב ועי\"ז אש אוכלה אש<sup data-n=\"3986\">47</sup> היינו בחי' האש זרה הנ\"ל שהיא היא בחי' מקור משחת לכל הבחי' עד שמעיינו נרפש ר\"ל, ולכן בהסיר הגורם הציור הנ\"ל ממילא נהרס הרע עד היסוד שבו הוא<sup data-n=\"3987\">48</sup> שתכליתו שטוב הוא כנ\"ל והוא ע\"י התבוננות שיתבונן בעצמו בענין תאותו שנצטייר בה ציור רע ע\"י חמימות האש שבו, הנה הוא צריך לכבוש את יצרו רע<sup data-n=\"3988\">49</sup> ברגע ההוה לבד, שהרי מה שעבר אין ועל להבא עדיין אינו ידוע לו מה יהי' עמו וז\"ע יזכיר לו יום המיתה<sup data-n=\"3989\">50</sup> שאבדו כל עשתונותיו<sup data-n=\"3990\">51</sup> ונפסק חום הטבעי שבדם שגם הוא מיסוד האש כו', וא\"כ כל יגיעותיו צ\"ל רק ברגע זו דהוה לבד, וגם איך יהי' כפוי טובה כ\"כ הלא גם בעת שפועל פעולת הרע הנה הוא ית' המחי' אותו ונותן לו כח כמ\"ש ואתה מחי' את כולם<sup data-n=\"3991\">52</sup> אפי' רע גמור ג\"כ בכלל הוא, ורק הוא ית' היותו כל יכול, יכול הוא לסבול מעשה כזה להחיות שונאו העובר רצונו, אמנם יהי'<sup data-n=\"3992\">53</sup> כפוי טובה כ\"כ, ומה גם כשיתבונן שאם מעשה הרע שהיא בדבר גשמי יש בה ענג כ\"כ, שכל הענג שבעוה\"ז הוא מהתענוג שנפל<sup data-n=\"3993\">54</sup> כו' כמ\"ש במ\"א, וכ\"ש ענג הרוחני שבתורה וקיום המצות ואהבת הקב\"ה ודבקותו בו שאין ערוך לו כלל, וע' באה\"ח ע\"פ ואהבת<sup data-n=\"3994\">55</sup> את הוי' אלקי', הובא בד\"ה וספרתם לכם מאה\"ז דספירת ז\"נ וטבילה דחה\"ש (ט\"ז<sup data-n=\"3995\">56</sup> ), אשר ע\"י כ\"ז יתעורר ברשפי אש התשוקה לאלקות עד שאש אוכלה אש התאוה וציור הרע להיות נהפך לקדושה להיות בבחי' ואהבת בכל לבבך בשני יצריך<sup data-n=\"3996\">57</sup> שגם היצה\"ר ישוב לאהבת ה', והיינו כנ\"ל שבעצם הוא טוב, וגם כח המתאוה שבו הוא רק כח לתאות תאוה, אבל יכול להיות בבחי' תאוה לאלקות כו' כנ\"ל וכמ\"ש במ\"א באריכות<sup data-n=\"3997\">59</sup>, ובחי' זו מתהפך ע\"י בחי' האש דקדושה שאש אוכלה אש כו'.",[["3983","44","<b>רשפי' רשפי אש</b>: שה\"ש ח, ו."],["3984","45","<b>כשלהבת הקשורה בגחלת</b>: ס\"י פ\"א, מ\"ז."],["3985","46","<b>רעו\"ד</b>: זהר וירא קד, א."],["3986","47","<b>אש אוכלה אש</b>: יומא כא, ב."],["3987","48","<b>הוא</b>: תיבה זו ניתוספה בין השיטין."],["3988","49","<b>רע</b>: אוצ\"ל: רק."],["3989","50","<b>יזכיר לו יום המיתה</b>: ברכות ה, א."],["3990","51","<b>שאבדו כל עשתונותיו</b>: ע\"פ תהלים קמו, ד."],["3991","52","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו. ראה גם לקמן מאמר ד\"ה בראשית על יד הערה 24. ו(בחלק ההנחות) הנחה ד\"ה כי המצוה על יד הערה 60. ד\"ה אנכי אנכי על יד הערה 18. ובההוספה ד\"ה שלש רגלים על יד הערה 62."],["3992","53","<b>אמנם יהי'</b>: אוצ\"ל: אמנם איך יהי'. או אוצ\"ל: האמנם יהי'."],["3993","54","<b>שכל הענג שבעוה\"ז. . שנפל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380444\" data-slug=\"likkutei-torah\" data-id=\"4001380444\">לקו\"ת בהעלותך לג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380499\" data-slug=\"likkutei-torah\" data-id=\"4001380499\">שלח מו, ד</a>. מאמרי אדה\"א דברים ח\"א ע' נח. וש\"נ. ח\"ג ע' תתמח. וש\"נ."],["3994","55","<b>באה\"ח ע\"פ ואהבת</b>: בסה\"מ שבהערה הבאה: ”ע\"פ ואהבת. . והיו הדברים האלה\" ראה אור החיים ואתחנן ו, ו ד\"ה עוד נתכוון. מובא גם בסה\"מ תר\"ל מהדורת תשמ\"ג ע' שנד."],["3995","56","<b>וספרתם לכם. . דחה\"ש (ט\"ז)</b>: הנחת כ\"ק אדמו\"ר מהר\"ש נמצא בבוך 1029 ע' צא בכותרת: ”בס\"ד ל\"ג בעומר רחוב\"ת\". ונאמר עוה\"פ בחה\"ש בשינוי ההתחלה עה\"פ ”ועשית חג שבועות\". ונדפס בשינויים בסה\"מ תרל\"ג ח\"א ע' רעו ואילך."],["3996","57","<b>ואהבת. . בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, ב במשנה. שערי אורה ו, א הערה 9.\n58)לתאות: ב: להתאוות."],["3997","59","<b>וכמ\"ש במ\"א באריכות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380966\" data-slug=\"likkutei-torah\" data-id=\"4001380966\">לקו\"ת ר\"ה סא, ד</a>. סה\"מ תרכ\"ט ע' קא וע' רסג. לעיל הערה 39."]]],[2000450377,"<b>ואמנם</b> הנה כ\"ז הוא כשמהפך האש זרה להיות בבחי' רשפי אש התשוקה לאלקות כו', אבל אם עדיין עומד במרדו לילך אחר מזימות יצרו הרע המסיתו ומדיחו כנ\"ל, הנה הקב\"ה ממתין לו אולי ישוב מדרכו, ובא\"ל חכ'<sup data-n=\"3998\">*60</sup> כאשר מתמלא סאתו, או קודם מעט שמתמלא כל סאתו (ע\"ד חורבן בהמק\"ד ב' שני' קודם<sup data-n=\"3999\">60</sup> כמ\"ש במ\"א) שולח הקב\"ה אש לטהרו ולזככו כו', כי עיקר הטהרה הוא באש כנ\"ל, והיינו יסוד הדק יותר מכל היסודות, ולכן כשפגם ע\"י עובי וגסות יסודותיו דרמ\"ע, והעיקר מיסוד העפר שהוא היותר גס שבהם, הנה טהרתו וזיכוכו הוא באש, אלא שמחסד ה' עלינו שולח חמתו על העצים והאבנים<sup data-n=\"4000\">61</sup> ומכלה חמתו בהם ר\"י<sup data-n=\"4001\">62</sup>, תמורת אש נוקמת שג\"כ אוכלה אש דחום הטבעי ויצה\"ר כמ\"ש ותבער בם אש ה' ותאכל<sup data-n=\"4002\">63</sup>, וכתי' כי בערה בם אש ה'<sup data-n=\"4003\">64</sup>, אלא להיותו טוב וישר ה'<sup data-n=\"4004\">65</sup> ומרבה להיטיב שופך חמתו על העצים כו', אשר עי\"ז כאשר מכלה ר\"ל ביתו ובניניו, נוטל ממנו כל בחי' מקיפי' שלו, והעיקר הוא המקיף שבירור זו הוא עוד חזק וגרוע מכור עוני, שהפנימי' ומקיפי' שלו הם אינם טובים, ומ\"מ ישנם כפי ההכרח כו' משא\"כ שריפה ר\"י אוכלת הכל, ולא עוד שגורם פחד הלב שמתפחד עד שמתלבן דאזיל סומקי<sup data-n=\"4005\">66</sup> כו', והוא ע\"י חלישות העורקי' שנחלשי' מהפחד, וממילא מתעורר התפעלות החום שבו לגרש את רוח החיוני שבו עד שיכול לבוא לידי התעלפות גמורה, והיא מדה כנגד מדה<sup data-n=\"4006\">67</sup>, וכמארז\"ל שמדה במדה לא בטלה<sup data-n=\"4007\">68</sup> ובמדה שאדם מודד<sup data-n=\"4008\">69</sup> מודדין לו, הוא הסית בנפשו חום הטבעי ולא גדר בעדו להסתפק במה שהותר לנו כל הדברים שאסר לנו כמארז\"ל אסר לנו בשר בחלב והיתיר לנו<sup data-n=\"4009\">70</sup> כחל, ועד\"ז רבות שם, כ\"א נמשך אחר דברים האסורים כו', וגם אינו פועל בנפשו לעורר את האהבה לאלקות עד שאש אוכלה אש כו', לכן מדה במדה תייסריך רעתך ושולט האש הגשמי המכלה כו' שהוא מד' אבות נזיקין<sup data-n=\"4010\">71</sup> כו', עד שפועל כנ\"ל כו', וג\"ז הוא תכלית הטוב בשביל לנקותו להצטרף ולהתלבן כו', ויובן גודל עונש הפחדי' ממארז\"ל שהמלבין פני חבירו ברבים<sup data-n=\"4011\">72</sup> אין לו חלק לעוה\"ב, והיינו דאזיל סומקא ואתי חיורא<sup data-n=\"4012\">73</sup> וא\"כ מובן גודל עונש הפחדי' ואיך שמזדכך עי\"ז, ונודע כי הילוך השמש בארץ טפח הנה ברקיע היא מהלכת אלפי' מילין כמ\"ש",[["3998","*60","<b>חכ'</b>: כ\"ה גם בב."],["3999","60","<b>חורבן בהמק\"ד ב' שנים קודם</b>: ראה גיטין פח, א. סנהדרין לח, א."],["4000","61","<b>שולח חמתו על העצים והאבנים</b>: ע\"ד איכ\"ר פ\"ד, יד. מדרש תהלים פע\"ט, ג. רש\"י תהלים עט, א. רש\"י קדושין לא, ב ד\"ה איסתייעא."],["4001","62","<b>ר\"י</b>: רחמנא יצילנו."],["4002","63","<b>ותבער בם אש ה' ותאכל</b>: בהעלותך יא, א."],["4003","64","<b>כי בערה בם אש ה'</b>: בהעלותך שם, ג."],["4004","65","<b>טוב וישר ה'</b>: תהלים כה, ח."],["4005","66","<b>דאזיל סומקי</b>: נסמן בסמוך הערה 73."],["4006","67","<b>מדה כנגד מדה</b>: ראה שבת קה, ב."],["4007","68","<b>שמדה במדה לא בטלה</b>: ראה הערה שלפנ\"ז."],["4008","69","<b>ובמדה שאדם מודד</b>: ראה סוטה ח, ב במשנה."],["4009","70","<b>אסר לנו. . והיתיר לנו</b>: ראה חולין קט, ב."],["4010","71","<b>האש. . מד' אבות נזיקין</b>: משנה ריש בב\"ק."],["4011","72","<b>שהמלבין פני חבירו</b>: אבות פ\"ג, מי\"א. ב\"מ נט, א."],["4012","73","<b>דאזיל סומקא ואתי חיורא</b>: ב\"מ נח, ב."]]],[2000450378,"באגה\"ת בסופו<sup data-n=\"4013\">74</sup> בש' הרמב\"ן ז\"ל<sup data-n=\"4014\">75</sup> מובן שזיכוך זה הוא זיכוך גדול מאד עד שעי\"ז נעשה כלי לקבל הגילוי דלע\"ל מה שאני אהי' לה חומת אש סביב, והענין הוא דהנה נת' לעיל שטבע יסוד האש הוא לעלות למעלה ובזה הוא חלוק מכל היסודות, ולע\"ל תהי' התחדשות שהאש יהי' בדרך ירידה כו', דהנה במ\"ת כתי' ודבריו שמענו מתוך האש<sup data-n=\"4015\">76</sup>, וכן והר סיני כו' ירד עליו ה' באש<sup data-n=\"4016\">77</sup>, ונמצא אם היות שמצינו שירד האש מלמעלמ\"ט, מ\"מ לא הי' הגילוי מבחי' אש כ\"א קול דברים אתם שומעים<sup data-n=\"4017\">78</sup> שהקול מורכב מג' יסודות אמ\"ר<sup data-n=\"4018\">79</sup> כידוע כו', וכן מה שמצינו שאש ירדה מלמעלה ותאכל העולה<sup data-n=\"4019\">80</sup>, ואש שלמעלה הי' יורד בבהמק\"ד<sup data-n=\"4020\">81</sup> וכן באלי' ותרד אש<sup data-n=\"4021\">82</sup>, עכ\"ז הי' פעולתו להעלות וגם הוא הי' עולה, ועמוד האש שהי' הולך לפניהם לילה<sup data-n=\"4022\">83</sup> י\"ל ג\"כ שהי' דרך עלי' מלמטלמ\"ע רק שהי' נאחז למטה ע\"ד כמו האש שנאחז בעצים ובפתילה כו', וכן עמוד הענן<sup data-n=\"4023\">84</sup> הי' נאחז בדבורו של הקב\"ה, אבל שיהי' חומת אש סביב תמיד זהו ע\"ד או\"מ דעכשיו זהו דבר שיהי' לע\"ל כו'. ואפ\"ל מפני כי לע\"ל תהי' אחע\"ב<sup data-n=\"4024\">85</sup>, ובחי' מ\"ח יצאו מירושלים<sup data-n=\"4025\">86</sup> אל הים הקדמוני כו', לכן גם האש ישונה תנועתו כו' ובכדי שיוכלו לקבל גילוי אור גדול כזה, זהו ע\"י זיכוך דאש כו', ואמנם העצה להנצל מעונש המר הלזה הוא כנ\"ל לעורר את רשפי אש האהבה עד שתחפץ לדבקה בו א\"ס חיי החיים<sup data-n=\"4026\">87</sup>, וזהו בכל השנה ובאלול ור\"ה ויוהכ\"פ שהוא זמן התשובה הרי עוד בנקל יותר לבוא לבחי' זו ע\"י התשובה מעומקא דליבא בבחי' צעקה בקול פשוט בלתי<sup data-n=\"4027\">88</sup>",[["4013","74","<b>הילוך השמש. . באגה\"ת בסופו</b>: פי\"ב. מובא גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650218\" data-slug=\"or-hatorah-hb\" data-id=\"8316650218\">אוה\"ת ש\"ש ע' א'תקכז</a>. נ\"ך כרך ב ע' תתקמז. סה\"מ תרס\"א ע' רכב. תרפ\"ה ס\"ע של. בהערה הבאה."],["4014","75","<b>הילוך השמש. . באגה\"ת בסופו בש' הרמב\"ן ז\"ל</b>: ראה גם בסה\"מ תר\"ל ע' קכד־ תרל\"ב ח\"א ע' קמב־ תרנ\"ג ס\"ע קצז־ תרנ\"ז ע' קד [ושם: וכמשל המבואר בהרמב\"ן בהקדמת איוב מהעתקת הצל למטה טפח, הובא בסש\"ב]. סה\"מ תרל\"ב ח\"א ס\"ע שב ואילך [ושם: וכמ\"ש הרמב\"ן ממשל העתקת הצל טפח על הארץ למעלה הוא הילוך אלפיים מיל]. ולפנינו ברמב\"ן ליתא."],["4015","76","<b>ודבריו שמענו מתוך האש</b>: כ\"ה גם לקמן (בחלק ההנחות) בהנחה כאן ד\"ה לה\"ע השריפה על יד הערה 18. ראה ואתחנן ד, לו [ושם: שמעת]. ה, כא [ושם: ואת קולו]."],["4016","77","<b>והר סיני. . באש</b>: יתרו יט, יח."],["4017","78","<b>קול דברים אתם שומעים</b>: ואתחנן ד, יב."],["4018","79","<b>שהקול. . אמ\"ר</b>: ראה זהר תצוה קפד, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תרנא. וש\"נ. דברים ח\"ג ע' תתק. וש\"נ. קונטרסים ע' תקמט. וש\"נ."],["4019","80","<b>שהאש ירד מלמעלה ותאכל העולה</b>: שמיני ט, כד."],["4020","81","<b>ואש שלמעלה. . בבהמק\"ד</b>: ראה תו\"כ ויקרא א, ז. ערובין סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["4021","82","<b>ותרד אש</b>: מל\"ב א, י. י\"ב."],["4022","83","<b>ועמוד האש שהי' הולך לפניהם לילה</b>: ראה בשלח יג, כא. כב. שלח יד, יד. נחמי' ט, יב. יט."],["4023","84","<b>עמוד הענן</b>: בשלח־ שלח ונחמי' שם."],["4024","85","<b>אחע\"ב</b>: משלי יב, ד."],["4025","86","<b>מ\"ח יצאו מירושלים</b>: ראה זכרי' יד, ח."],["4026","87","<b>חיי החיים</b>: יומא עא, א."],["4027","88","<b>בלתי</b>: ע\"כ נמצא בגוכתי\"ק. וראה לעיל בהערה 1: וסיום הדרוש צריכי' להעתיק מן ביאור צדקת פרזונו בס' תקס\"ה. הביאור דצדקת פרזונו — נדפס במאמרי אדה\"ז תקס\"ה ח\"ב ע' א'ד ואילך."]]],[2000450379,"<h3>כי המצוה הזאת כו'</h3>\n<b>ש\"פ נצו\"י ל\"ח לפ\"ק</b>\n<b></b>האדם בחי' כללית כו' האדם והמצות כו' פגם העבירות - ב\"פ\n[נצו\"י]\n<b>להבין</b> שרשי הדברים הנ\"ל הנאמרים ע\"פ כי המצוה<sup data-n=\"4028\">1</sup> הזאת אשר אנכי מצוך היום לא נפלאת<sup data-n=\"4029\">2</sup> היא ממך כו', וצ\"ל על איזה מצוה קאי, נא'<sup data-n=\"4030\">4</sup> שקאי על כל המצות למה אמר המצוה ל' יחיד<sup data-n=\"4031\">3</sup>, ותחלה יש להקדים ב' עניני'<sup data-n=\"4032\">5</sup>, דהנה כתיב נעשה אדם בצלמנו<sup data-n=\"4033\">6</sup> כו', וידוע הקושיא למה נאמר בו לשון רבים נעשה כו' ולא נאמר בו יהי אדם כמ\"ש יהי אור<sup data-n=\"4034\">8</sup> יהי רקיע<sup data-n=\"4035\">9</sup> כו'. אך הענין הוא דהאדם אינו כשאר כל הנבראים",[["4028","1","<b>להבין. . כי המצוה הזאת</b>: מכאן מתחיל סדרה של ד' מאמרים שהראשון שבהם נאמר בש. ז. (תרל\"ח), וג' מהם נאמרו בשנה שלאח\"ז (שנת תרל\"ט), בהמשך זה נתבאר מאמר ד\"ה זה שנאמר ע\"י כ\"ק אדה\"ז בשנת תקס\"ו, ונדפס במאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקלה ואילך (ושם לחלקו הראשון של המאמר נדפסו ב' נוסחאות, וקיצור מכ\"ק אדמו\"ר הצ\"צ נמצא שם ע' תתקנ). ובשינויים באוה\"ת נצבים ע' א'רכט ואילך. ונאמר גם בראשית שנת תרכ\"ז ע\"י כ\"ק אדמו\"ר מהר\"ש ונדפס בסה\"מ תרכ\"ו ע' רמב, ואילך (עם הוספה, וקיצור נדפס שם ע' רנד ואילך).\nבמאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו נדפס גוף המאמר שפתיחתו הוא כי המצוה הזאת והוא משבת פ' נצבים תקס\"ה (ומקבילו נדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380900\" data-slug=\"likkutei-torah\" data-id=\"4001380900\">לקו\"ת נצבים מה, ב</a>). וביאור ראשון (שפתיחתו היא להבין שרשי הדברים) נדפס שם בע' תתפג. וביאור שני (שפתיחתו היא להבין וכו' ע\"פ כי המצוה) נדפס שם ע' תתקלה. ומאמר דידן מיוסד על ביאור שני כנ\"ל.\nמאמר דידן מבאר שני פרקים הראשונים ממאמר דתקס\"ו (ע' תתקלה — תתקלט שבמאמרי אדה\"ז תקס\"ה הנ\"ל).\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה להלן בחלק ההנחות (ומשם נעתקה הכותרת שבריש המאמר) ושם הפתיחה: כי המצוה הזאת, וראה גם הנרשם בסמוך.\nמאמר זה נזכר בסה\"מ תרנ\"ח ע' כה ושם: ”כמ\"ש מזה בהביאור דכי המצוה הזאת ובהגהות לשם בס' רל\"ח\". תרס\"ט ע' קנ ושם: ”ועמ\"ש בהגהות לביאור כי המצוה הזאת בס' תרל\"ח\". סה\"מ תרע\"ח ע' שעא. לקמן במאמר ד\"ה אנכי אנכי על יד הערה 10. ד\"ה וכל מאמינים על יד הערות 49. 56. ד\"ה שהמ\"מ על יד הערה 26. בבוך זה 1089 מתחלה נכתבו ההגהות בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש למאמר זה ובכותרת ”הג\"ה לד\"ה כי המצוה דתקס\"ה\", ואח\"כ בא המאמר בהעתקת הר\"ש סופר כשולב בתוכו ההגהות הנ\"ל וכן ניתוספו עוד הגהות בגוכתי\"ק.\nהמאמר נמצא גם בכת\"י מעתיקים דלהלן ובכולם הפתיחה היא ”כי המצוה הזאת\" וכ\"ה גם בסה\"מ תרכ\"ו ע' רמב בהערה. וברשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש. ואפשר כשניתן המאמר להעתיק ציוה כ\"ק אדמו\"ר מהר\"ש להשמיט ההתחלה: ”להבין שרשי הדברים הנ\"ל הנאמרים ע\"פ\". וראה לקמן במאמר ד\"ה אנכי על יד הערה 10: ”נת' בד\"ה כי המצוה\".\nהכת\"י המעתיקים הם:\nא 363 ע' עבר בכותרת: בס\"ד פ' נצו\"י תרל\"ט(!).\nב 545 ע' קלד בכותרת: בס\"ד פ' נצו\"י.\nג 2083 ע' צה כותרת: בס\"ד פ' נצו\"י (כת\"י הר\"ש סופר).\nד מאסקבא 127 בתחלתו בכותרת: בס\"ד פ' נצו\"י ל\"ח."],["4029","2","<b>כי המצוה הזאת. . לא נפלאת</b>: נצבים ל, יא."],["4030","4","<b>נא'</b>: אוצ\"ל: ואם נא'."],["4031","3","<b>וצ\"ל. . יחיד</b>: ניתוסף בגוכתי\"ק בריש צד השמאלי של העמוד."],["4032","5","<b>ב' עניני'</b>: במאמרי אדה\"ז תקס\"ה כאן: ענין א' וכן העתיק הר\"ש סופר. ותיקנו בגוכתי\"ק. ענין הב' הובא לקמן על יד הערה 60."],["4033","6","<b>נעשה אדם בצלמנו</b>: ראה גם (ולהבא לקמן) לקו\"ת להאריז\"ל תשא לג, ה. האזינו (עה\"פ נעשה אדם).\n7)הקושיא. . לשון רבים: ב\"ר פ\"ח, ח. ראה גם סה\"מ תרל\"ו ח\"ב ע' שטז."],["4034","8","<b>יהי אור</b>: נסמן לקמן בהערה 18."],["4035","9","<b>יהי רקיע</b>: בראשית א, ו."]]],[2000450380,"ונאצלים בהשתל' שהם כל או\"א<sup data-n=\"4036\">10</sup> מדרגה ובחי' א' פרטיות בלבד אבל האדם הוא בחי' כוללת שכלול מכל ההשתל' ויש בו מכל הפרצופי' יחד וכולהו איתנהו בי' כו' ואינו מע\"ס בבחי' פרטיות בלבד<sup data-n=\"4037\">11</sup> וע\"כ כל העולמות כלולים בו וכמבואר בזהר<sup data-n=\"4038\">12</sup> (ונק' עולם קטן<sup data-n=\"4039\">13</sup> כו'), (וכ\"ה<sup data-n=\"4040\">14</sup> במד\"ר בראשית פי\"ב<sup data-n=\"4041\">15</sup> אם אני בורא אותו מן העליוני' או מן התחתוני' הרי יש קנאה במע\"ב, אלא אני בורא מן העליונים ומן התחתוני', שנמצא כולל עליוני' ותחתוני') וזהו שנא' בו נעשה לשון רבים לפי שמכולם נעשה דהיינו מכל הי\"ס בכלל ולכך כלול הוא מכל המדרגות, משא\"כ בשאר נברא זולתו שאין התהוותן אלא מבחי' ומדרגה פרטי' כמו האור מן החסד<sup data-n=\"4042\">16</sup> והרקיע מן הת\"ת<sup data-n=\"4043\">17</sup> וכיוצא ולכך נאמר בהן לשון יחיד ויאמר אלקי' יהי אור<sup data-n=\"4044\">18</sup> יהי רקיע כו'. והמופת לזה שהאדם כלול מכולן כנ\"ל הנה אנו רואים זה ממעשה המצות שנצטוה האדם, דידוע שכל עיקר המצות הן רק להמשיך אורות עליונים בכלים כו' וכמו ע\"י הטלית נמשך אור מקיף לנוק'<sup data-n=\"4045\">19</sup> וציצית הטלית הן בשביל<sup data-n=\"4046\">21</sup> מוחין דנוק'<sup data-n=\"4047\">20</sup> כו' ואכילת מצה מוחי' דקטנות דנוק' כו'<sup data-n=\"4048\">22</sup>, ובג' סעודות השבת אנו רואים דסעודה הראשונה בשביל חקל תפוחין שהוא בבחי' מל' והשלישית בבחי' עתיק<sup data-n=\"4049\">23</sup> כו', ויש מצות שהן בבחי'<sup data-n=\"4050\">24</sup> ז\"א כמו הלולב (ומיניו שהם המשכת הדעת לנוק' דז\"א העומדת בחזה<sup data-n=\"4051\">25</sup> ) דז\"א ומצות ת\"ת",[["4036","10","<b>שהם כל או\"א</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. במאמרי אדה\"ז תקס\"ה כאן: שהוא."],["4037","11","<b>בלבד</b>: במאמרי אדה\"ז תקס\"ה כאן בנוסחא שני' מציין הצ\"צ: כמו מז\"א לבד או מאו\"א לבד."],["4038","12","<b>וכמבואר בזהר</b>: במאמרי אדה\"ז תקס\"ה כאן בנוסחא שני' מציין הצ\"צ: וע' בזהר בשלח דנ\"ה ע\"א ובמק\"מ שם וע' בזהר פ' אמור דף ק\"ד א' ע\"פ כל הנקרא בשמי ובפי' הרמ\"ז שם ור\"פ במדבר דקי\"ז א' ובמק\"מ ובהרמ\"ז שם ובפ' פנחס דרי\"ט ע\"ב ור\"פ תולדות קל\"ד ב' ובפ' ויחי דרמ\"ה ובשע\"ק להרח\"ו ח\"ג שער ב'."],["4039","13","<b>ונק' עולם קטן</b>: ראה תנחומא פקודי ג. מאמרי אדה\"א הנחות תקע\"ז ע' צח. וש\"נ."],["4040","14","<b>(וכ\"ה</b>: הגהת כ\"ק אדמו\"ר מהר\"ש."],["4041","15","<b>במד\"ר בראשית פי\"ב</b>: ס\"ח (בשינוי לשון). ראה גם המשך וככה תרל\"ז פע\"ה."],["4042","16","<b>האור מן החסד</b>: ראה גם אוה\"ח לזהר בראשית מו, א. מאמרי אדה\"א דברים ח\"ד ע' א'תמו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550120\" data-slug=\"torat-chaim\" data-id=\"2300550120\">תו\"ח תצוה ח\"ב שיט, א</a>. וש\"נ."],["4043","17","<b>והרקיע מן הת\"ת</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"כ מערכת רקיע. מאו\"א מערכת רקיע אות מו."],["4044","18","<b>ויאמר אלקי' יהי אור</b>: בראשית א, ג."],["4045","19","<b>הטלית נמשך אור מקיף לנוק'</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 32. במאמרי אדה\"ז תקס\"ה כאן ע' תתקלו בנוסחא שני' תיבת: לנוק', ליתא."],["4046","21","<b>בשביל</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תתקלו ניתוסף: בחי'."],["4047","20","<b>וציצית. . מוחין דנוק'</b>: וכ\"ה במאמרי אדה\"ז כאן. ועד\"ז הוא לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 33. בנוסחא שני' שם: הם בחי' שערות וא\"פ. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380526\" data-slug=\"likkutei-torah\" data-id=\"4001380526\">לקו\"ת קרח נג, א</a>. המשך תער\"ב ח\"ב ע' א'קפו."],["4048","22","<b>דקטנו' דנוק'</b>: בנוסחא שני' שם: דאבא."],["4049","23","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450627\" data-slug=\"or-hatorah-hb\" data-id=\"8316450627\">סעודה</a> הראשונה. . חקל תפוחין. . והשלישית בבחי' עתיק</b>: וכ\"ה במאמרי אדה\"ז תקס\"ה כאן. ראה אוה\"ת בהר כרך ד ע' א'קנב. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 35. המשך תער\"ב ח\"ב ע' א'צז ואילך. לקו\"ש בשלח כרך לא ע' 247."],["4050","24","<b>בבחי'</b>: במאמרי אדה\"ז תקס\"ה כאן: לבחי'."],["4051","25","<b>(ומיניו. . בחזה)</b>: שם: בדעת. ראה פע\"ח שער הלולב שכ\"ט, פ\"א ואילך. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 37. המשך וככה תרל\"ז פפ\"ד ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'שט. וש\"נ."]]],[2000450381,"במוחי' דז\"א<sup data-n=\"4052\">26</sup> וכן תפילין של ראש<sup data-n=\"4053\">27</sup> כו' ויש מצות שהם בבחי'<sup data-n=\"4054\">28</sup> אימא בא\"פ וא\"מ כמו הסכך דסוכה בבחי' מקיפים דאימא<sup data-n=\"4055\">29</sup> כידוע ויש מצות שהן בבחי' אור אבא<sup data-n=\"4056\">30</sup> ובחי' עתיק וא\"ק<sup data-n=\"4057\">31</sup> כו' כמבואר בפרע\"ח, והנה לכאורה יפלא מהיכן יהי' כח באדם להמשיך אור ע\"י המצות בכל המדריגות בעתיק וא\"א ואו\"א וזו\"נ ע\"י הטלית בנוק' וע\"י הלולב (בנוק' דז\"א העומדת בחזה דז\"א<sup data-n=\"4058\">32</sup> ) כו' וכיוצא אם לא שמוכרח לומר כנ\"ל שהאדם הוא בחי' כוללת מכל ההשתל' בכלל ולא מע\"ס פרטיות בלבד וא\"כ יש בו גם מבחי' ע\"י וא\"א וגם מאו\"א וזו\"נ כו' ולכך ע\"י המצות כולן שיקיים ימשיך מכולן לפעמים מזה ולפעמים מזה לפי אופן מעשה המצות להיכן שהן רמוזים ועל ידו יתקיימו כולן למעלה כמ\"ש אשר יעשה אותם האדם<sup data-n=\"4059\">33</sup> כו' והוא מאחר שכוללם יחד א\"כ בהכרח שהוא למעלה מכולן כו', וזהו פי' אדם אדמה לעליון<sup data-n=\"4060\">34</sup> ממש שלפני כל ההשתלשלו' וכמ\"ש במ\"א (ולכאו'<sup data-n=\"4061\">35</sup> צ\"ל למה הרכיב כאן ב' ענינים שהם ג' ביחד ענין המצות שפועלים בכל ע\"ס, ב' האדם המקיים אותם גבוה מהם שהוא ג' שהאדם עושה המצות כמ\"ש אשר יעשה אותם האדם כו', אך הענין הוא דאם<sup data-n=\"4062\">36</sup> היות שע\"י מעהמ\"צ ממשיכי' מכל הע\"ס הרי אין מזה שום ראי' שהאדם כלול מכולן כי י\"ל שזהו מחמת המצוה לעשות אשר באמת למי שהי' מצוה לעשות הי' פועל כן, ולכן הוצרך לטעם שהאדם עושה המצוה והיינו כמארז\"ל מעלה אני עליכם כאלו עשאוני<sup data-n=\"4063\">37</sup>, כמ\"ש מזה בשה\"ש בד\"ה צאינה וראינה<sup data-n=\"4064\">38</sup> באריכות ובכ\"ד, וממילא האדם גדול מהם, והגם כי באמת זהו מכח המצוה לעשותן שזהו ההפרש בין מ\"ת<sup data-n=\"4065\">39</sup> למה שקיים אברהם כל התורה כולה<sup data-n=\"4066\">40</sup> עכ\"ז לפום גמלא שיחנא<sup data-n=\"4067\">41</sup> שלפ\"ע מעלת כח פועל העבודה טוענים כובד המשא",[["4052","26","<b>ת\"ת במוחי' דז\"א</b>: ראה גם מאמרי אדה\"ז תקס\"ה כאן. אוה\"ת נצבים כאן. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380673\" data-slug=\"likkutei-torah\" data-id=\"4001380673\">לקו\"ת מטות פז, ד</a>."],["4053","27","<b>וכן תפילין של ראש</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370163\" data-slug=\"torah-or\" data-id=\"3901370163\">תו\"א מקץ לה, ג</a>. מאמר ד\"ה את ה' האמרת ח\"י אלול תש\"ל פ\"ד [קונט' ח\"י אלול תשמ\"ז — סה\"מ מלוקט ב ע' צ]."],["4054","28","<b>שהם בבחי'</b>: במאמרי אדה\"ז תקס\"ה כאן: לבחי'."],["4055","29","<b>הסכך. . מקיפים דאימא</b>: ראה ביאוה\"ז אמור פ, ב. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540329\" data-slug=\"torat-chaim\" data-id=\"2300540329\">תו\"ח בא ח\"א קיד, א</a>. מאמרי אדה\"א דברים ח\"ד ע' א'שנו ובהנסמן שם. סה\"מ תרכ\"ז ע' תכא. וש\"נ."],["4056","30","<b>מצות. . אור אבא</b>: ראה מאמרי אדה\"ז תקס\"ה כאן נוסחא שני' הובא לעיל הערה 22."],["4057","31","<b>מצות. . עתיק וא\"ק</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 42."],["4058","32","<b>(בנוק'. . דז\"א)</b>: במאמרי אדה\"ז תקס\"ה כאן: בז\"א."],["4059","33","<b>אשר יעשה אותם האדם</b>: אחרי יח, ה."],["4060","34","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבוה\"ק ח\"א חלק היחוד פי\"ז. מאמרי אדה\"א דברים ח\"א ע' קכב. וש\"נ. בראשית ע' קסב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a>. סה\"מ תרל\"ו ח\"ב ע' שטז. לקמן (בחלק ההנחות) הנחה ד\"ה וכל מאמינים על יד הערה 81. ד\"ה שיר המעלות ממעמקים על יד הערה 31 ואילך."],["4061","35","<b>(ולכאו'. . הע\"ס כו'</b>: הגהת כ\"ק אדמו\"ר מהר\"ש נמצא גם בסה\"מ תרכ\"ו כאן ע' רמג."],["4062","36","<b>דאם</b>: כ\"ה בכ\"מ — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["4063","37","<b>מעלה אני עליכם כאלו עשאוני</b>: ראה זהר שם קיג, סע\"א. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' רלה."],["4064","38","<b>בשה\"ש בד\"ה צאינה וראינה</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381215\" data-slug=\"likkutei-torah\" data-id=\"4001381215\">לקו\"ת שה\"ש כא, סע\"ג</a> ואילך."],["4065","39","<b>ההפרש בין מ\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370304\" data-slug=\"torah-or\" data-id=\"3901370304\">תו\"א יתרו סח, א</a> ואילך."],["4066","40","<b>שקיים אברהם כל התורה כולה</b>: ראה יומא כח, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301670169\" data-slug=\"likkutei-sichot\" data-id=\"1301670169\">לקו\"ש תולדות כרך לה ע' 107</a> ואילך."],["4067","41","<b>לפום גמלא שיחנא</b>: כתובות סז, א. ראה גם ס' המצות להצ\"צ קס, סע\"ב."]]],[2000450382,"עליו כ\"כ, ומאחר שציוה אותנו לעשות את כל המצוה הזאת הרי בהכרח לומר שיש בכח האדם לעשותם כולם, והיינו כי ברא אותו מן העליוני' והתחתוני' ויצר וברא בו מכל הע\"ס כו'.\n<b>ועוי\"ל</b><sup data-n=\"4068\">42</sup> שהמכוון ממ\"ש נעשה לשון רבים בכדי שיוכלל בו גם כח המלאכים<sup data-n=\"4069\">*43</sup>, בהיות ידוע שהמלאכי' שאמרו מה אנוש<sup data-n=\"4070\">43</sup> נענשו ע\"ז כמארז\"ל בזה בגמ' ומדרשי', וע' בלק\"ת<sup data-n=\"4071\">44</sup> בד\"ה מזמור שיר חנוכת הבית, והמלאכי' שהסכימו הנה עי\"ז ניתוסף באדם כח המלאכי' ג\"כ שהרי הסכם רצונם הי' ע\"ז, רק שלפי מארז\"ל במד\"ר פ\"ח<sup data-n=\"4072\">45</sup> עד שהיו מאה\"ש<sup data-n=\"4073\">46</sup> מדיינים אלו עם אלו ומתעסקי' כו' בראו הקב\"ה, א\"ל מה אתם מדיינים כבר נעשה אדם, א\"כ אין בו מכח המלאכי', אלא שי\"ל שמה שנשא ונתן עמהם זהו בשביל שלא יקטרגו ושיטרדו בדיינם אע\"א כו', וא\"כ ה\"ז עצמו קצת סיוע, היינו מה שהיו מדיינים אע\"א כו', ויובן זה ע\"פ משנ\"ת בכ\"ד בענין שרפים ואופנים<sup data-n=\"4074\">47</sup>, שביאר רבינו אדמ\"ו ז\"ל שהנה\"ב הוא משמרי האופנים<sup data-n=\"4075\">48</sup>, והנה\"א הוא כדוגמת השרפי'<sup data-n=\"4076\">49</sup>, אלא שהוא חלק ה' ממש<sup data-n=\"4077\">50</sup> כו', ולכן אם לא הי' משתעי עם המלאכים בדבר יצירת האדם לא הי' האדם שליט ברוחו לכלוא את הרוח דנה\"ב שיבוא לאהבת בכל לבבך בשני יצריך<sup data-n=\"4078\">51</sup> היינו שגם היצה\"ר יבוא לבחי' ואהבת כו', ובאמת זהו תכלית ירידת הנשמה בגוף<sup data-n=\"4079\">52</sup> וגם ענין קיום המצות הוא בשביל זה כמארז\"ל ע\"פ אמרות ה' צרופה<sup data-n=\"4080\">53</sup> לא ניתנו המצות<sup data-n=\"4081\">54</sup> אלא לצרף בהם את הבריות כו', שנת' בד\"ה מים רבים ובד\"ה וככה<sup data-n=\"4082\">56</sup> תאכלו אותו באורך<sup data-n=\"4083\">55</sup> ע\"ש, ועפ\"ז יתיישב היטב דברי המד\"ר אני בורא אותו מן העליוני' ומן כו' שנתן בו כח מן העליוני', והיינו ע\"י שא'",[["4068","42","<b>ועוי\"ל</b>: מכאן עד סיום הסוגר נכתב בגוכתי\"ק."],["4069","*43","<b>כח המלאכים</b>: ראה גם לקו\"ת שבהערה 6."],["4070","43","<b>שהמלאכי' שאמרו מה אנוש</b>: תהלים ח, ה. סנהדרין לח, ב. יל\"ש בראשית א, כו (רמז יג)."],["4071","44","<b>בלק\"ת</b>: ברכה צז, סע\"ד ואילך."],["4072","45","<b>במד\"ר פ\"ח</b>: ב\"ר פ\"ח, ה."],["4073","46","<b>עד שהיו מאה\"ש</b>: שם: עד שמלאכי השרת."],["4074","47","<b>בענין שרפים ואופנים</b>: ראה גם לעיל המשך וידבר וגו' ויצוום פ\"ח. וש\"נ."],["4075","48","<b>שהנה\"ב הוא משמרי האופנים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380083\" data-slug=\"likkutei-torah\" data-id=\"4001380083\">לקו\"ת ויקרא ב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381021\" data-slug=\"likkutei-torah\" data-id=\"4001381021\">האזינו עד, ג</a>."],["4076","49","<b>והנה\"א הוא כדוגמת השרפי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381024\" data-slug=\"likkutei-torah\" data-id=\"4001381024\">לקו\"ת האזינו עה, ב</a>."],["4077","50","<b>והנה\"א. . חלק ה' ממש</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. לקמן (בחלק ההנחות) ד\"ה ושמרתם ובהערה 19."],["4078","51","<b>לאהבת. . בשני יצריך</b>: ראה ואתחנן ו, ה ובספרי שם. ברכות נד, ב במשנה. שערי אורה ו, א הערה 9."],["4079","52","<b>תכלית ירידת הנשמה בגוף</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381021\" data-slug=\"likkutei-torah\" data-id=\"4001381021\">לקו\"ת האזינו עד, ג</a>."],["4080","53","<b>אמרות ה' צרופה</b>: שמו\"ב כב, לב. תהלים יח, לא [ושם: אמרת]. משלי ל, ה [ושם: אמרת אלקה — ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670453\" data-slug=\"torat-chaim\" data-id=\"2300670453\">תו\"ח בראשית טו, ב</a>. מאמרי אדה\"א במדבר ח\"ג ע' א'קיז]."],["4081","54","<b>לא ניתנו המצות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. ויק\"ר פי\"ג, ג. אוה\"ת שמיני ע' נב ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171426\" data-slug=\"likkutei-sichot\" data-id=\"1300171426\">לקו\"ש אבות כרך יז ע' 415</a> הערה 53. שופטים כרך יט ע' 182 הערה 42."],["4082","56","<b>ובד\"ה וככה</b>: תרל\"ז ע' יז [ושם: וכמ\"ש ענין צירוף זה באורך בד\"ה מים רבים]. ע' קלח [ושם: ע\"פ מה שנת\"ל דעיקר ענין המצות לא ניתנו אלא לצרף בהם את הבריות שנת' לעיל ובד\"ה מים רבים שקאי על נה\"ב שנק' בריות]."],["4083","55","<b>בד\"ה מים רבים. . באורך</b>: תרל\"ו ע' קטו."]]],[2000450383,"נעשה לשון רבים, ויצירתו הי' מהקב\"ה עצמו כמ\"ש ויברא וייצר, ויפח<sup data-n=\"4084\">57</sup>, וכמ\"ש מי אתי<sup data-n=\"4085\">58</sup> וארז\"ל מי הי' שותף אתי במע\"ב<sup data-n=\"4086\">59</sup> כו').\n(ב) <b>והנה</b> עוד ענין<sup data-n=\"4087\">60</sup> אחר<sup data-n=\"4088\">61</sup> יש להקדים והוא בפגם העבירות מה הן פוגמי' דהנה מבואר למעלה דעיקר המצות הן בחי' המשכות האורות בכלים כו', והנה ידוע דמחיצוניות ואחוריים של הכלים יש יניקה לחיצוני' ג\"כ (וכמ\"ש<sup data-n=\"4089\">62</sup> בפ' וישלח<sup data-n=\"4090\">63</sup> בד\"ה ויאבק איש עמו שמאחורי העור בין נקב לנקב היינו בין צירוף לצירוף נמשך יניקה לסט\"א כו' ע\"ש). אך גם זאת הוא בא להם במדה וקצבה ושיעור מוגבל כפי המדה הקצובה מהמאציל העליון מבחי' קו המדה הנק' בוצינא דקרדוניתא<sup data-n=\"4091\">64</sup> כו' שמודד גם כמה יהי' יניקת החיצוני' מבחי' אחוריי' כו'. והנה במעשה העבירות שתים רעות יש, הא' והוא דבר קטן דהיינו מה שעי\"ז ניתוסף להם שפע אלקי' יותר מכפי הצמצום המדה שלהם ושיעורם המוגבל מקו המדה כו' וזהו דבר קטן וכלא חשיב ממש, שהרי מבחי' קו המדה שבמאציל נמדד מדה לכל פרטי ההשתל' דאבי\"ע דהיינו עד כמה יומשך אור האצי' ויהי' בחי' הגבול דאצי' ולהיות משם ואילך בחי' נפרד מאלקות וכמ\"ש ומשם יפרד<sup data-n=\"4092\">65</sup> כו', והוא עולמות הנפרדים בי\"ע כידוע וגם כמה יהי' העולמות הללו בבחי' א\"פ ומקיפי' וכמה יהי' מהם גם בבחי' חיצוני' ואחוריי' כו' ולפ\"ז שיעור זה שניתן ליניקת החיצוני' מבחי' אחוריי' וחיצוניות ובפרט כמו דרך צפרנים ושערות שהן רק בחי' אחוריי' דאחוריי'<sup data-n=\"4093\">66</sup> ה\"ז דבר קטן ומועט בערך מאד לגבי עיקר הפנימי' שבבריאה ומכ\"ש לגבי האצי' כו', וא\"כ גם שניתוסף לחיצוני' קצת יניקה יותר מכפי המדה המצומצמת להם אינו תופס מקום כלל וכלל וכלא ממש חשיב כו' ע\"כ נק' פגם זה פגם קטן. אבל פגם הגדול שע\"י העבירות הוא ענין אחר, והוא מה<sup data-n=\"4094\">67</sup> שהאורות עליונים דאבי\"ע מסתלקים מן הכלי בסיבת רבוי יניקת החיצוני' כי לא יגורך רע<sup data-n=\"4095\">68</sup> כתי' וטהור עינים מראות ברע<sup data-n=\"4096\">69</sup> כו', ובחי' הסתלקות האורות זהו גרעון גדול מאד לגבי המקבלים שהן העולמות וההיכלות עליונים כו' שהרי האורות הן בחי' אלקות ממש וע\"י הסתלקות האור למעלה ממילא נפגם העולם מצד העדר האור, זאת הרעה הרבה יותר מרעה הראשונה בתוס' היניקה לחיצונים בכפלי כפלים כו'",[["4084","57","<b>ויברא וייצר ויפח</b>: בראשית א, כז. ב, ז."],["4085","58","<b>מי אתי</b>: ישעי' מד, כד."],["4086","59","<b>מי הי' שותף אתי במע\"ב</b>: ראה ב\"ר פ\"א, ג. לעיל המשך וידבר וגו' ויצוום ספ\"ו הערה 123."],["4087","60","<b>עוד ענין אחר</b>: ענין הא' ראה לעיל על יד הערה 5."],["4088","61","<b>אחר</b>: וכ\"ה בסה\"מ תרכ\"ו כאן ובמאמרי אדה\"ז תקס\"ה כאן: אחד."],["4089","62","<b>(וכמ\"ש</b>: הגהת כ\"ק אדמו\"ר מהר\"ש."],["4090","63","<b>בפ' וישלח</b>: ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א כו, ב</a>."],["4091","64","<b>קו המדה הנק' בוצינא דקרדוניתא</b>: ראה זהר בראשית טו, א [ובמפרשים שם]. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370177\" data-slug=\"torah-or\" data-id=\"3901370177\">תו\"א מקץ לט, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370476\" data-slug=\"torah-or\" data-id=\"3901370476\">שמות קז, ד</a>. מאמרי אדה\"א נ\"ך ע' עא. וש\"נ. אוה\"ת שלח ע' תצג ואילך."],["4092","65","<b>ומשם יפרד</b>: בראשית ב, י."],["4093","66","<b>דאחוריי'</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן ע' רמד. ובמאמרי אדה\"ז תקס\"ה כאן ע' תתקלז ליתא."],["4094","67","<b>והוא מה</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תתקלח: והוא ענין מה. בסה\"מ תרכ\"ו כאן כבפנים."],["4095","68","<b>לא יגורך רע</b>: תהלים ה, ה."],["4096","69","<b>וטהור עינים מראות ברע</b>: חבקוק א, יג [ושם: רע — ראה מנחת שי שם. מאמרי אדה\"א בראשית ע' צו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540736\" data-slug=\"torat-chaim\" data-id=\"2300540736\">תו\"ח בא ח\"א קכג, ד</a>. וש\"נ]."]]],[2000450384,"(ולכאו'<sup data-n=\"4097\">70</sup> צ\"ל למה יחשב ענין המשכת תוס' יניקה לסט\"א לפגם קטן יותר מן מה שמסתלק האורות מהכלים דבי\"ע הלא לכאו' כל ענין סילוק האורות הוא מפני שלא יגורך רע כו', וא\"כ תוס' היניקה הוא לכאו' עוד יותר גרוע שה\"ז המשכת קיום ברע כו'. אך הענין הוא דכתי' כי לא ידח<sup data-n=\"4098\">71</sup> ממנו נדח, וא\"כ כל מה שניתוסף חיות יתר מכפי חוק הקצוב יתברר, כי גם מה שבחוק הקצוב יתברר ויוטל ג\"כ וכ\"ש מה שניתוסף כו', ומה גם כי התוס' אינו נחשב לדבר גדול להיותו ג\"כ מן מה שמצומצם ע\"פ קו המדה כנ\"ל. אבל מה שנסתלקו האורות מחמת זה ה\"ז גרם היזק שאין כמוהו, וזהו דכתי' כי שתים רעות עשה עמי אותי עזבו מקור כו' לחצוב להם בורות<sup data-n=\"4099\">72</sup> כו' לא יכילו המים, פי' ע\"י שפגמו המשיכו תוס' יניקה בבחי' בורות נשברי' הוא הסט\"א אשר לא יכילו המים שאינם ע\"ד כמו שבקדושה הוא אורות בכלים כ\"א בהם הוא שנבלע השפע כמ\"ש מזה בפ' תולדות<sup data-n=\"4100\">73</sup> בד\"ה ראה ריח בני ע\"ש, וזהו לא יכילו שאינם נעשי' כלי לבחי' המים הוא שפע הקדושה כ\"א שנבלע בהם, אמנם מפני כי לא ידח ממנו נדח כנ\"ל לכן חטא זה הוא דבר קטן כו', אבל מה שאותי עזבו שהקדושה מסתלק כמאמר קוב\"ה בג' סליק לעילא ולעילא<sup data-n=\"4101\">74</sup> ה\"ז גדול עוונו מאד שלא בערך נגד בחי' ההמשכה שהמשיכו בהפגם בסט\"א כו', ועכ\"ז מועיל תשו' ע\"ז כמשי\"ת).\n<b>ואחר</b> הקדמה הנ\"ל יובן שלצורך התיקון לפגם העבירות צריך ב' דברים לתקן, הא' להעביר תוס' היניקה של החיצוני' מאחוריי' של הכלים די\"ס דאבי\"ע כו' בכדי שיוכל אור העליון לשכון בה ואחר שהעבירו יניקת החיצוני' מכל וכל ולא נשאר להם רק כפי המדה בלבד מראשית ההשתל' הנה עוד עדיין חסר העיקר והוא להמשיך האורות בכלים וישכון<sup data-n=\"4102\">75</sup> בהם ולא יסתלקו עוד כמבראשונה והוא ענין החזרת האורות שנסתלקו וכו', וכ\"ז ע\"י המצות בכלל ע\"י רמ\"ח מ\"ע ושס\"ה ל\"ת<sup data-n=\"4103\">76</sup> הל\"ת הן להעביר התוס' יניקה שלא יומשך לחיצונים כמו לא תאכל חלב ודם<sup data-n=\"4104\">77</sup> כו' והמ\"ע הן להמשיך האור כו' וכידוע (אך<sup data-n=\"4105\">78</sup> עדיין צ\"ל מה מועיל עשיית המצות להמשיך האור החסר מהפגם הקדום, הן אמת שע\"י עשיית המצות נמשך אורות בכלים אבל זהו האורות שנמשכי' ע\"י המצות שעושה עכשיו, אבל ע\"י מה ממשיכי' האורות שנסתלקו מקודם. אך הענין דכתי' סור מרע ועשה טוב<sup data-n=\"4106\">79</sup>, פי' הפשוט סור מרע הוא הזהירות בשס\"ה ל\"ת ועשה טוב הם קיום רמ\"ח מ\"ע,",[["4097","70","<b>(ולכאו'</b>: הגהת כ\"ק אדמו\"ר מהר\"ש."],["4098","71","<b>כי לא ידח</b>: שמו\"ב יד, יד [ושם: לבלתי ידח — ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה ביום ההוא יהי' ובהערה 24]."],["4099","72","<b>כי שתים רעות. . בורות</b>: ירמי' ב, יג [ושם: בארות]."],["4100","73","<b>בפ' תולדות</b>: ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370094\" data-slug=\"torah-or\" data-id=\"3901370094\">תו\"א כ, סע\"ב</a> ואילך."],["4101","74","<b>קוב\"ה בג' סליק לעילא ולעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540232\" data-slug=\"torat-chaim\" data-id=\"2300540232\">תו\"ח שמות ח\"א לט, סע\"א</a> ואילך ובהערה 72."],["4102","75","<b>וישכון</b>: במאמרי אדה\"ז תקס\"ה כאן ובסה\"מ תרכ\"ו כאן: וישכנו."],["4103","76","<b>רמ\"ח מ\"ע ושס\"ה ל\"ת</b>: מכות כג, סע\"ב."],["4104","77","<b>לא תאכל חלב ודם</b>: ראה ויקרא ג, יז."],["4105","78","<b>(אך</b>: הגהת כ\"ק אדמו\"ר מהר\"ש."],["4106","79","<b>סור מרע ועשה טוב</b>: תהלים לד, טו. ראה גם לקמן (בחלק ההנחות) מאמר ד\"ה אנכי אנכי על יד הערה 20."]]],[2000450385,"וגם י\"ל סור מרע שעברת קודם והיינו ע\"י התשובה מעומקא דלבא שע\"י החרטה ועקירת הרצון והצמצום שעושה בעצמו הן בתשובת המדה<sup data-n=\"4107\">80</sup> והמשקל<sup data-n=\"4108\">81</sup> והן בתשו' הגדר<sup data-n=\"4109\">82</sup>, וע\"י הסיגופי' שעושה עי\"ז מצמצם לבלי יומשך שפע הקדושה מאחורי הכלים, וע\"י בחי' חילא יתיר שיש בבע\"ת כמ\"ש בזהר זכאין אינון מארי דתיובתא<sup data-n=\"4110\">83</sup> דמשכין לי' לקוב\"ה בחילא יתיר<sup data-n=\"4111\">84</sup>, הנה ע\"י בחי' חילא יתיר זו עי\"ז ממשיך האורות שנסתלקו מקודם שיבואו לשכון בכלים מכלים שונים, ומ\"ש כאן שזהו ע\"י המצות כוונתו גם ע\"י התשובה שקדם שזהו ג\"כ בכלל מצות כו' שהתשובה היא ג\"כ מצוה<sup data-n=\"4112\">85</sup> אלא שהיא מצוה רמה ונשאה שמעוררת בחי' בעל הרצון<sup data-n=\"4113\">86</sup> שיומשכו הצנורות הם בחי' פרטי הרצון דרה\"ע שבמעשה המצות, כמ\"ש מזה בד\"ה והתהלכתי בתוככם דתרך\"ב<sup data-n=\"4114\">87</sup>, ע\"ש). וזהו בדרך כלל בכללות המצות ובדרך פרט יש ב' תיקונים הללו בכל מצוה וכמו במצות מילה שהיא הראשונה<sup data-n=\"4115\">88</sup> שעיקר ענינה הוא לב' דברים הנ\"ל, הא' להסיר תחלה בחי' הערלה החופפת על ברית הקדש כו' והוא להסיר התוס' מן החיצוני' להיות לכך נק' ערלים כו' וכמ\"ש ומלתם ערלת לבבכם<sup data-n=\"4116\">89</sup> כו', וגם במילה עיקר הכוונה במצות המילה הוא כדי שיהי' התגלות י\"ה כו' צריך שימול הערלה החופפת בבחי' תוס' לחיצוני' כו', וזהו אותיות מילה מל י\"ה וכמ\"ש בכוונת המילה בפע\"ח באריכות<sup data-n=\"4117\">90</sup>, לפי שבלתי הסרת הערלה לא יוכל",[["4107","80","<b>בתשובת המדה</b>: ראה רקח הל' תשובה סוף ס\"א (ע' כה) ואילך ושם: וד' עניני תשובה הם תשובת הבאה תשובת הגדר תשובת המשקל תשובת הכתוב."],["4108","81","<b>והמשקל</b>: ראה לקו\"ת ואתחנן ט, ד. לקמן (בחלק הההנחות) בהנחה כאן על יד הערה 76. סה\"מ שבהערה הבאה."],["4109","82","<b>בתשו' הגדר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380751\" data-slug=\"likkutei-torah\" data-id=\"4001380751\">לקו\"ת ואתחנן ט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380866\" data-slug=\"likkutei-torah\" data-id=\"4001380866\">תצא לז, ב</a>. נצבים נב, א. המשך מים רבים תרל\"ו פר\"א ע' רלד. סה\"מ עת\"ר ר\"ע סא. קונטרסים ח\"ב ע' 674. תש\"ט ע' 224. לקמן (בחלק הההנחות) בהנחה כאן על יד הערה 76."],["4110","83","<b>זכאה אינון מארי דתיובתא</b>: ראה זהר ח\"ש קכט, סע\"א."],["4111","84","<b>בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540123\" data-slug=\"torat-chaim\" data-id=\"2300540123\">תו\"ח שמות ח\"א לז, א</a>. וש\"נ."],["4112","85","<b>שהתשובה היא ג\"כ מצוה</b>: ראה לקו\"ש ר\"ה כרך ד ע' 1144 ובהערה 5. משפטים כרך ו ע' 329. קדושים כרך יז ע' 210 ואילך ובהערה 40. נשא כרך לח ע' 18 ואילך. וראה גם לקמן (בחלק ההנחות) הנחה ד\"ה וכל מאמינים על יד הערה 8."],["4113","86","<b>בעל הרצון</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה ביום ההוא יהי' ובהערה 20."],["4114","87","<b>והתהלכתי בתוככם דתרך\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940272\" data-slug=\"or-hatorah-hb\" data-id=\"8159940272\">אוה\"ת בחוקותי כרך ב ע' תרעח</a> ואילך. ע' תרמג. סה\"מ תרכ\"ט ע' רנד. הנחת כ\"ק אדמו\"ר מהר\"ש מדרוש זה נמצא בבוך 2111 ע' עא בכותרת: בס\"ד ש\"פ בחוקתי ך\"ב. הנחת ר\"ה יודפס בעז\"ה בספרו פלח הרמון פ' בחוקותי."],["4115","88","<b>במצות מילה שהיא הראשונה</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ה (בנוסחא א — אבל בנוסחא שני' שם: ליתא)־ אוה\"ת־ סה\"מ תרכ\"ו כאן. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670033\" data-slug=\"torat-chaim\" data-id=\"2300670033\">תו\"ח לך צג, ב</a>. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381276\" data-slug=\"likkutei-torah\" data-id=\"4001381276\">לקו\"ת שה\"ש לז, א</a>: שתיכף כשנולד מקיים מצוה ראשונה. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 80: מצות מילה מצוה ראשונה שנצטווה אברהם."],["4116","89","<b>ומלתם ערלת לבבכם</b>: עקב י, טז [ושם: את ערלת — וכ\"ה גם במאמרי אדה\"ז תקס\"ה־ אוה\"ת־ סה\"מ תרכ\"ו כאן. ואולי היא השמטת הר\"ש סופר]."],["4117","90","<b>מילה מל י\"ה. . בפע\"ח באריכות</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ה כאן ע' תתקלט (בנוסחא א)־ אוה\"ת־ סה\"מ תרכ\"ו כאן. אבל בנוסחא שני' שם ע' תתקלח: בע\"ח שער האונאה ובלק\"ת פ' לך לך בכוונת המילה. ראה ת\"ז תכ\"ב סח, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך יב, א</a>. ביאוה\"ז בראשית ד, ב. סידור שער המילה קמג, ג. תו\"ח מקץ צד, א הערה 2. סהמ\"צ להצ\"צ ח, ב. לקמן (בחלק ההנחות) הנחה ד\"ה היום גלותי על יד הערה 52. ובהנחה כאן על יד הערה 83."]]],[2000450386,"להאיר שם י\"ה בנפש האדם וכמו שנא' באברהם שנק' אברהם בה\"א אחר המילה דוקא כי אב המון גוים<sup data-n=\"4118\">91</sup> כו' וכמ\"ש במ\"א, ועד\"ז יש כוונה זו בכלל בכל מצוה ומצוה בפרט (כמו<sup data-n=\"4119\">92</sup> בד' בתים דתפילין שיעור דקדוקן בד' בתים דוקא הוא להבדיל ולהסתיר האור דקדושה כו' וכמ\"ש במ\"א).\n<b>וזהו</b><sup data-n=\"4120\">93</sup> כי המצוה הזאת, שקאי על מצות התשובה<sup data-n=\"4121\">94</sup> שהיא ג\"כ מצוה, לא נפלאת כו' ולא בשמי'<sup data-n=\"4122\">95</sup> כו' ולא מעבר לים<sup data-n=\"4123\">96</sup> כו' כי גם אם בעוונות נסתלק לעילא ולעילא בבחי' פלא שמעבר לים, או שמי' ע\"ד דרך הנשר בשמים<sup data-n=\"4124\">97</sup> כמ\"ש במ\"א, עכ\"ז ע\"י תשובה בחילא יתיר ממשיכים גם בחי' האור הקדום שנסתלק כו' ולכן לא בשמים היא ולא מעבר לים כ\"א בפיך הוא השופר<sup data-n=\"4125\">98</sup> צעקה בקול פשוט ובלבבך הוא ג' אהבות דק\"ש, ושיבוא לידי פועל אח\"כ בבחי' לעשותו שכ\"ז קרוב אליך מאד, ולכן נא' המצוה סתם, וגם י\"ל על כל המצות וכנ\"ל שבכל מצוה יש תיקון על ב' הפגמי' שבעוונות, ונא' מצוה ל' יחיד להיות כי בכל מצוה יש בחי' זו כנ\"ל השיעור והמדידה, ועצם המצוה כו'.",[["4118","91","<b>כי אב המון גוים</b>: לך יז, ה. ראה גם בהדרושים שבהערה שלפ\"ז שם ואילך."],["4119","92","<b>(כמו</b>: החצע\"ג מופיע גם במאמרי אדה\"ז תקס\"ה כאן."],["4120","93","<b>וזהו</b>: מכאן נכתב בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש."],["4121","94","<b>כי המצוה. . מצות התשובה</b>: ראה רמב\"ן כאן (נצבים ל, יא). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו\"ת נצבים מה, ג</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141124\" data-slug=\"likkutei-sichot\" data-id=\"1300141124\">לקו\"ש נצבים כרך יד ע' 112</a> הערה 24."],["4122","95","<b>ולא בשמי'</b>: נצבים ל, יב [ושם: לא]."],["4123","96","<b>ולא מעבר לים</b>: נצבים שם, יג."],["4124","97","<b>דרך הנשר בשמים</b>: משלי ל, יט. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381036\" data-slug=\"likkutei-torah\" data-id=\"4001381036\">לקו\"ת האזינו עח, ב</a>. מאמרי אדה\"א בראשית ר\"ע שמט. סה\"מ תרל\"ב ח\"א ע' נג. וש\"נ. ע' רכה. המשך תער\"ב ח\"א ס\"ע שמו. ח\"ב ע' עתר. ע' עתרא."],["4125","98","<b>בפיך הוא השופר</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתצו."]]],[2000450387,"<h3>אנכי אנכי כו'</h3>\n<b>בס\"ד, ישעי' מ\"ג ך\"ה </b>\n<b></b><b>יום א' דר\"ה ל\"ט לפ\"ק ליבאוויטש</b>\nתקון פגם העבירות כו' ב' בחי' במקיף\nר\"ה תרל\"ט\n<b>אנכי</b> אנכי<sup data-n=\"4126\">1</sup> הוא מוחה פשעיך למעני וחטאתיך לא אזכור<sup data-n=\"4127\">2</sup>, וצ\"ל מהו שאומר למעני דמשמע שאם<sup data-n=\"4128\">3</sup> היות שבשביל המבקש מחיית הפשעים לא הי' ראוי שימחול עכ\"ז למעני אני עושה זאת, וכמו שפרש\"י לא בזכותך ולא בצדקת אבותיך, ולכאו' זהו כשלא אכשיר, אבל כשאכשיר דרא<sup data-n=\"4129\">4</sup> איך יתפרש אז מ\"ש למעני, וגם לשון למעני פירושו לעצמותי כאדם האומר ע\"ע בשבילי כך כבי' אומר למעני כו', והלא מקרא מלא א' הכתוב אם חטאת מה תפעל בו<sup data-n=\"4130\">5</sup> כו' אם צדקת<sup data-n=\"4131\">6</sup> כו', וגם צ\"ל מאחר שמוחה פשעיך איך יעלה על הדעת שיזכיר החטאים שהם יותר קלים מפשע<sup data-n=\"4132\">7</sup> כידוע מארז\"ל בזה, עד שמצטרך לומר וחטאתיך לא אזכור כו'. והענין יובן ע\"פ מה שכפל לומר ב\"פ אנכי, ולמה במ\"ת שהי' גילוי אלקות וירד ה' על הר סיני ואמר עשה\"ד, ועכדו\"ד פרחה נשמתן<sup data-n=\"4133\">8</sup> והחזירן בטל שעתיד להחיות בו את המתים לע\"ל, ועכ\"ז לא אמר רק פ\"א אנכי כמ\"ש אנכי ה' אלקיך<sup data-n=\"4134\">9</sup>, וכאן אומר אנכי אנכי הוא מוחה פשעיך, וגם צ\"ל דמשיעור הכתוב הוא כמו מי שמודיע שידעו מי הוא המוחה",[["4126","1","<b>אנכי אנכי</b>: הוא דרוש השני מסדרה של ד' מאמרים שבהם נתבאר מאמר ד\"ה להבין וכו' כי המצוה שנאמר ע\"י כ\"ק אדה\"ז בשנת תקס\"ו, ונדפס במאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקלה ואילך. ובשינויים באוה\"ת נצבים ע' א'רכט ואילך. ונאמר גם ע\"י כ\"ק אדמו\"ר מהר\"ש בראשית שנת תרכ\"ז ונדפס בסה\"מ תרכ\"ו ע' רמב ואילך (עם הוספה, וקיצור נדפס שם ע' רנד ואילך).\nבמאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו נדפס גוף המאמר שפתיחתו הוא כי המצוה הזאת והוא משבת פ' נצבים תקס\"ה (ומקבילו נדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380900\" data-slug=\"likkutei-torah\" data-id=\"4001380900\">לקו\"ת נצבים מה, ב</a>). וביאור ראשון (שפתיחתו היא להבין שרשי הדברים) נדפס שם בע' תתפג. וביאור שני (שפתיחתו היא להבין וכו' ע\"פ כי המצוה) נדפס שם ע' תתקלה. ומאמר דידן מיוסד על ביאור שני כנ\"ל.\nמאמר דידן מבאר פרק ג מהמאמר דתקס\"ו (ע' תתקלט — תתקמג שבמאמרי אדה\"ז תקס\"ה הנ\"ל). הנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה להלן בחלק ההנחות. ומשם נעתק התאריך המופיע בריש המאמר.\nהבא בתוך חצאי עיגול בפנים המאמר הם הגהות כ\"ק אדמו\"ר מהר\"ש פרט באם צויין אחרת.\nמאמר זה נזכר בסה\"מ תרמ\"ז ע' לז בשולי הגליון ושם: ”אנכי אנכי לח\". תרנ\"ז ע' רלח ושם: ”ועמ\"ש במ\"א (בס' רל\"ח) בהביאור דכי המצוה הזאת בד\"ה אנכי אנכי כו\"'. לקמן מאמר ד\"ה וכל מאמינים על יד הערות 34־ 36. ד\"ה שהמ\"מ על יד הערות 14-13. 19.\nבבוך זה 1089 מתחלה נכתב הפתיחה וההגהות וסיום בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש למאמר זה ובכותרת ”בס\"ד\", ואח\"כ בא המאמר בהעתקת הר\"ש סופר כשולב בתוכו ההגהות הנ\"ל וכן ניתוספו עוד הגהות בגוכתי\"ק.\nהדרוש נמצא גם בביכלאך כת\"י מעתיקים והם: א 363 ע' עדר בכותרת: בס\"ד ר\"ה תרל\"ט. ב 545 ע' קלו (בכותרת שבפנים). ג 2083 ע' צט כת\"י הר\"ש סופר ונסמן לקמן בהערות: ג. ד מאסקבא 127 ע' 14 בכותרת: בס\"ד ר\"ה."],["4127","2","<b>אנכי. . לא אזכור</b>: ישעי' מג, כה (כנ\"ל בהכותרת)."],["4128","3","<b>שאם</b>: כ\"ה בכ\"מ — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["4129","4","<b>כשאכשיר דרא</b>: ע\"פ יבמות לט, ב. חולין צג, ב."],["4130","5","<b>אם חטאת מה תפעל בו</b>: איוב לה, ו."],["4131","6","<b>אם צדקת</b>: איוב שם, ז."],["4132","7","<b>החטאים שהם יותר קלים מפשע</b>: יומא לו, ב."],["4133","8","<b>ועכדו\"ד פרחה נשמתן</b>: ראה שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג. וש\"נ. נ\"ך ע' שפא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670525\" data-slug=\"torat-chaim\" data-id=\"2300670525\">תו\"ח בראשית יז, ב</a>."],["4134","9","<b>אנכי ה' אלקיך</b>: יתרו כ, ב."]]],[2000450388,"פשעיך אומר לו אנכי אנכי הוא, אשר לכאו' יפלא הלא גם אחר הודעתו אותנו את כל אלה ג\"כ אינו מושג כלל מי הוא, וא\"כ מאי נפ\"מ במה שאומר אנכי אנכי<sup data-n=\"4135\">*10</sup> כו', והענין דהנה נת' בד\"ה כי המצוה<sup data-n=\"4136\">10</sup> שהפגם בחטא ועון הוא ב' דברים הא' במה שעי\"ז מוסיף תוס' יניקה בסט\"א יתר מכפי חוק הקצוב להם כו', הב' והוא העיקר שע\"י פעולת הרע גורם לסילוק אוא\"ס שיסתלקו האורות מהכלים, מפני כי לא יגורך רע כמשנת\"ש באריכות. ונמצא דעת לנבון נקל שבכדי לתקן זה צ\"ל ב' דברים הא' לברר ולהעביר תוס' היניקה שהשפיע להם, הב' להמשיך אוא\"ס בחי' אורות בכלים כו')<sup data-n=\"4137\">*11</sup>.\n<b>ואמנם</b><sup data-n=\"4138\">11</sup> ע\"י מה ממשיכים<sup data-n=\"4139\">12</sup> ב' דברים הנ\"ל הענין הוא כך, דבכדי להעביר יניקת החיצונים צריך תחלה להמשיך בחי' או\"מ דוקא כי ידוע דאור המקיף הוא מסמא עיני החיצוני'<sup data-n=\"4140\">13</sup> כו' כי לעוצם רוממות מעלתו לא יוכלו להסתכל בו וכמ\"ש במ\"א, (ויובן זה ממה שאנו רואים שכאשר יסתכל האדם באור השמש<sup data-n=\"4141\">14</sup> יכהו עיניו ויתקלקלו מאור עיניו, שזהו מפני כי לפי ערך צמצום מאור אור עיניו הנה ריבוי האור המאיר מכדור השמש לארץ ולדרים עליה ג\"כ כבד לקבלו כנראה בחוש כו' אבל להסתכל בגוף כדור השמש ששם אור בריבוי יותר, וגם חומו מרובה ביותר, ולכן ה\"ה שורף ומכלה את חלק הגשם שהיא הצבת אשר בו נאחז אור הראי' הרוחניות עד שבריבוי הסתכלותו באור השמש מכלהו לגמרי עד שיוכל להיות סומא בשתי עיניו אם יתמיד להסתכל בשמש, ועד\"ז יובן שכאשר מאיר האו\"מ שהוא ריבוי אור לכן ממילא מסמא עיני החיצוני' שאינם יכולים להסתכל בו כו'. ולכאו' צ\"ל מדוע כשפגם ובעוונותיו המשיך תוס' יניקה לסט\"א לא די שלא סימא כו' אלא שנבלע בהם כו' כנ\"ל, ומדוע המקיף מסמא עיני החיצוני' כו'. אך הענין הוא דהנה נת\"ל שזה שנמשך תוס' יניקה זהו נחשב לדבר קטן עדיין, והיינו לפי שגם התוס' הוא מן מה שכבר מצומצם ע\"פ קו המדה כמה יומשך בעולם זה, וע' בד\"ה בך\"ה בכסליו<sup data-n=\"4142\">15</sup> בענין מ\"ש מי יקום יעקב<sup data-n=\"4143\">16</sup> כי קטן הוא, שמאחר שיש קצה וקצה ה\"ז נק' קטן, וכמ\"כ יובן שמה שכבר נמדד ה\"ז קטן כו'. וא\"כ לא יפלא כלל מדוע לא",[["4135","*10","<b>הכתוב. . שמודיע. . אינו מושג. . אנכי אנכי</b>: ראה גם בסיום המאמר. לקמן מאמר ד\"ה וידבר וכו' אלה הם מועדי ובהערה 10."],["4136","10","<b>נת' בד\"ה כי המצוה</b>: שנדפס לפני מאמר זה בפ\"ב."],["4137","*11","<b>כו')</b>: בגוכתי\"ק לא נסמן התחלת החצאי עיגול."],["4138","11","<b>ואמנם</b>: מכאן לשון מאמרי אדה\"ז תקס\"ה ע' תתקלט. ושם וכן בסה\"מ תרכ\"ו כאן ע' רמה צויין כאן: פ\"ג. אבל מכאן ואילך נשמטו ציוני הפרקים. אף שבמאמר שלפנ\"ז צויין פ\"ב."],["4139","12","<b>ע\"י מה ממשיכים</b>: שם: במה יתוקן, וכן העתיק הר\"ש סופר כאן. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["4140","13","<b>דאור המקיף הוא מסמא עיני החיצוני'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג. מאמר ד\"ה הוא הי' אומר תרל\"א [קונט' בר מצוה תרנ\"ג ע' לט]."],["4141","14","<b>יסתכל האדם באור השמש</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה *22. ביאוה\"ז בשלח מו, א."],["4142","15","<b>בד\"ה בך\"ה בכסליו</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370138\" data-slug=\"torah-or\" data-id=\"3901370138\">תו\"א וישב כט, סע\"ד</a>. ראה גם לעיל המשך חייב אדם לברך פ\"ה על יד הערה 159."],["4143","16","<b>מי יקום יעקב</b>: עמוס ז, ב. ה."]]],[2000450389,"יתבטלו הסט\"א מצד הלא זהו<sup data-n=\"4144\">17</sup> מן מה שכבר מצומצם ולכן יכולים לקבל ואדרבה בולעי' כו', אבל בחי' המקיף הנה מאחר שהוא בחי' המקיף ה\"ז הוראה שא\"א לו להתלבש בבחי' פנימיות כ\"א נשאר בבחי' מקיף, כמ\"ש בלק\"ת<sup data-n=\"4145\">18</sup> בד\"ה מי אל כמוך בסופו בפי' לשארית נחלתו, שיריים כו', ולכן בהאיר אור המקיף שהוא אור הבלתי מצומצם ע\"ד בחי' האו\"פ אינם יכולים לקבל זאת, וממילא מתבטלים שז\"ע מה שמסמא עיניהם שהסומא חשוב כמת<sup data-n=\"4146\">19</sup> שעבר ובטל כו', ועדיין צ\"ל הלא ארז\"ל במלאכי' שקטרגו על בריאת האדם ואמרו מה אנוש<sup data-n=\"4147\">20</sup> כי תזכרנו שנענשו במה שהושיט הקב\"ה אצבעו<sup data-n=\"4148\">21</sup> הקטנה ביניהם ושרפם, שע\"י שנתגלה בהם אור יתר מכפי המדה נתבטלו הגם כי נק' אצבעו הקטנה שמורה על היותו מצומצם שהרי נק' אצבעו הקטנה, שאצבע מורה על צמצום, הקטנה צמצום שני היותר מצומצם, ומ\"מ נתבטלו, ומכ\"ש בסט\"א כשמאיר עליהם יתר מכפי חוק הקצוב אם היותו מצומצם ה\"צ להבטל כו'. אמנם באמת אינו ענין לזה כלל שפי' אצבעו הקטנה היינו בחי' מל'<sup data-n=\"4149\">22</sup> המהוה היש דבי\"ע שנק' אצבעו ע\"ד אצבע אלקי' היא<sup data-n=\"4150\">23</sup>, הקטנה ע\"ש צמצום מדת המל' יתר<sup data-n=\"4151\">24</sup> מכפי כל הט\"ס שלמעלה ממנה. או י\"ל שיש בבחי' מל' ב' בחי' ים וארץ<sup data-n=\"4152\">25</sup>, כמ\"ש ביאור ד\"ז במ\"א והמל' בכלל נק' אצבע, והבחי' שנק' ארץ ה\"ז נק' אצבעו הקטנה, ונודע כי בריאת יש מאין ה\"ה בדרך העלם והסתר הבורא מהנברא, ולכן בהגלות נגלות עליהם בחי' אצבעו הקטנה היא שרש בחי' המל' שנק' ארץ בלתי העלם הנ\"ל נתבטלו הנבראי', אבל אם<sup data-n=\"4153\">26</sup> הי' מתגלה ע\"ד כל הגילוי' שהצמצום הוא בשביל הגילוי ע\"ד שנא' וידבר אלקי'<sup data-n=\"4154\">27</sup> בעשה\"ד לא היו מתבטלים כלל, וא\"כ גם בענין התוס' יניקה הנמשך לסט\"א ה\"ה נמשך ע\"י חטא ועון שבודאי ההעלם גדול מאד ע\"ד ג'<sup data-n=\"4155\">28</sup> השכינה כו'. א\"כ מובן מה שאינם מתבטלים עי\"ז כו').\n<b>וידוע</b> ג\"כ בע\"ח דאור המקיף מזכך חצי הכלי מבחוץ<sup data-n=\"4156\">29</sup> כו' וזהו העיקר בענין דחיית הסט\"א שהרי קבלתם מאחורי העור כנ\"ל, וי\"ל שגם מה שנמשך",[["4144","17","<b>מצד הלא זהו</b>: תיבת הלא ניתוספה בין השיטין."],["4145","18","<b>כמ\"ש בלק\"ת</b>: דרושים לר\"ה סב, ב."],["4146","19","<b>שהסומא חשיב כמת</b>: נדרים סד, ב."],["4147","20","<b>במלאכי'. . ואמרו מה אנוש</b>: תהלים ח, ה. סנהדרין לח, ב."],["4148","21","<b>שהושיט הקב\"ה אצבעו</b>: ראה סנהדרין שם. לעיל המשך וידבר וגו' ויצוום פי\"ג הערה 231."],["4149","22","<b>אצבעו. . מל'</b>: ראה פרדס שער עשר ולא תשע ש\"א, פ\"א. של\"ה מסכת שבועות קצו, א. סידור הערה לתיקון חצות קנב, א. שער האמונה עט, ב. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 32. המשך תער\"ב ח\"א ע' תקצב. ח\"ב ע' א'קמג. בהערה הבאה."],["4150","23","<b>אצבע אלקי' היא</b>: וארא ח, טו. ראה פרדס שעה\"כ שכ\"ג, פ\"א מערכת אצבעות בסופה."],["4151","24","<b>צמצום מדת המל' יתר</b>: ראה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 33 ואילך."],["4152","25","<b>מל' ב' בחי' ים וארץ</b>: ראה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 34 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380133\" data-slug=\"likkutei-torah\" data-id=\"4001380133\">לקו\"ת צו יד, ב</a>. לעיל המשך וידבר וגו' ויצוום הערה 108."],["4153","26","<b>אם</b>: תוקן ע\"פ גוכתי\"ק. ג ובכת\"י הר\"ש: עם."],["4154","27","<b>וידבר אלקי'</b>: יתרו כ, א."],["4155","28","<b>ג'</b>: גלות."],["4156","29","<b>דאור המקיף מזכך חצי הכלי מבחוץ</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב. שער השתל' הי\"ס ש\"ב, ענף ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' תצט. ח\"ב כאן ע' תתקלט ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550230\" data-slug=\"torat-chaim\" data-id=\"2300550230\">תו\"ח פקודי ח\"ב תמט, ד</a> ואילך."]]],[2000450390,"להם ע\"י החטא ועון נמשך ג\"כ דרך אחורי העור להיות כי נמשך ע\"ד בחי' ג' כנ\"ל לכן זהו העיקר להיות כי עי\"ז<sup data-n=\"4157\">30</sup> אין לחיצוני' יניקה שם באחוריי' דכלים כי יאבדו ויפלו למטה מחמת מאור אור<sup data-n=\"4158\">31</sup> המקיף שמאיר עליהם מלמעלה כו' וכמ\"ש ביאור דבר זה במ\"א<sup data-n=\"4159\">32</sup>, ואחר שנמשך המקיף להעביר חיצוני' מחיצוניות הכלים אזי מאור מקיף זה נמשך לאורות עליונים בבחי' או\"פ להיות יורדין ונמשכין למטה בכלים ולא יסתלקו עוד כמבראשונה כנ\"ל, וא\"כ מובן שהמקיף הזה נחלק לב' חלקים חלק העליון ממנו הוא שיורד להאיר למטה על החיצוני' דכלים לבטל ולבער את החיצוני' וחלק השני התחתון ממנו יורד להיות בבחי' א\"פ לאורות עליונים כו' (וצ\"ל מדוע בשביל לבטל ולבער את הסט\"א נמשך מחלק העליון דוקא, והמשכת אורות בכלים זהו מחלק השני התחתון דוקא, דלכאו' הי' מהראוי להיות בהיפך שבשביל דחיית וביטול הסט\"א הי' מספיק גם חלק התחתון ג\"כ להיותו אור מקיף הבלתי מצומצם ע\"ד האו\"פ כנ\"ל, ולצורך המשכת אורות בכלים הנה אם הי' נמשך מחלק העליון הי' נמשך בבחי' תוס' מרובה כו', אמנם הנה קושי' זו היא ג\"כ בענין ההפרש שבין מ\"ע למצות ל\"ת<sup data-n=\"4160\">33</sup>, שנודע שענין השס\"ה ל\"ת הוא בחי' דחיית הסט\"א לא תאכלו נבלה<sup data-n=\"4161\">34</sup> או לא תלבש שעטנז<sup data-n=\"4162\">35</sup> וכדומה שהוא בשביל שלא יומשך תוס' יניקה לסט\"א כנ\"ל, וענין מ\"ע הוא בשביל המשכת אורות בכלים מכלים שונים כנ\"ל וכמ\"ש בכ\"ד באריכות, וא\"כ יפלא מדוע מ\"ע בו\"ה<sup data-n=\"4163\">36</sup> דש' הוי' ומל\"ת בי\"ה דש' הוי' שנודע מעלת י\"ה שה\"ע מעלת המוחין על המדות כו', וכמ\"ש בת\"ז שמי עם י\"ה שס\"ה ל\"ת זכרי עם ו\"ה רמ\"ח מ\"ע<sup data-n=\"4164\">37</sup>. אך הענין הוא דהיא הנותנת דלהיות שמל\"ת היא בשביל דחיות סט\"א והגבלתה בבחי' צמצום כמו שהי' בתחילת הבריאה קודם חטא עה\"ד וע' בביאור כי עכ\"כ חופה<sup data-n=\"4165\">38</sup>, לכן צ\"ל ע\"י בחי' היותר גבוה, והוא בכדי להעלות הניצוצות שנבלעו בסט\"א שיוכללו ע\"ד הנר שנמשך להאבוקה, וכל שהאבוקה גדולה יותר נמשכת הנר במהירות יותר להאבוקה כו', ולכן מל\"ת שהן למכוון העלאת הניצוצות, וכן לסמא עיני החיצוני' זהו דוקא מבחי' העליונה שבבחי' מקיף כו', ובשביל המשכת אורות",[["4157","30","<b>זהו העיקר. . עי\"ז</b>: ניתוסף בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש."],["4158","31","<b>אור</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן ע' רמה. ובמאמרי אדה\"ז תקס\"ה כאן: ליתא."],["4159","32","<b>וכמ\"ש ביאור דבר זה במ\"א</b>: ראה גם ביאוה\"ז בשלח מו, א."],["4160","33","<b>ההפרש שבין מ\"ע למצות ל\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380067\" data-slug=\"likkutei-torah\" data-id=\"4001380067\">לקו\"ת פקודי ו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">בחוקותי מה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380461\" data-slug=\"likkutei-torah\" data-id=\"4001380461\">שלח לז, ב</a> ואילך."],["4161","34","<b>לא תאכלו נבלה</b>: פ' ראה יד, כא [בדילוג תיבת כל]."],["4162","35","<b>לא תלבש שעטנז</b>: תצא כב, יא."],["4163","36","<b>יפלא מדוע מ\"ע בו\"ה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370235\" data-slug=\"torah-or\" data-id=\"3901370235\">תו\"א שמות נב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380053\" data-slug=\"likkutei-torah\" data-id=\"4001380053\">לקו\"ת פקודי ג, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380057\" data-slug=\"likkutei-torah\" data-id=\"4001380057\">שה\"א בהקדמה ד, ב</a>. ש\"א צד, ב."],["4164","37","<b>שמי. . שס\"ה זכרי. . רמ\"ח מ\"ע</b>: ראה שמות ג, טו. ת\"ז בהקדמה ד, סע\"ב. ה, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380053\" data-slug=\"likkutei-torah\" data-id=\"4001380053\">לקו\"ת פקודי ג, ב</a> ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע תתקי. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540329\" data-slug=\"torat-chaim\" data-id=\"2300540329\">תו\"ח בא ח\"א קיד, א</a>. וש\"נ. סה\"מ תרכ\"ז ע' קכט. וש\"נ."],["4165","38","<b>בביאור כי עכ\"כ חופה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381320\" data-slug=\"likkutei-torah\" data-id=\"4001381320\">לקו\"ת שה\"ש מח, סע\"א</a> ואילך."]]],[2000450391,"בכלים די גם חלק התחתון ג\"כ, ומה גם כי לצורך צמצום באו\"פ ה\"ז מתיישב בכלי יותר כו'.\n<b>ואמנם</b> עדיין צ\"ל מהו שייך בחי' עליון ותחתון בבחי' או\"מ, הלא בכ\"ד נת' שענין המקיף הוא מבחי' עגולים<sup data-n=\"4166\">39</sup> שאינו שייך כלל מעלה ומטה<sup data-n=\"4167\">40</sup> כו', ומ\"ע<sup data-n=\"4168\">41</sup> חלק העליון וחלק התחתון כו', אך המעיין בע\"ח שער עגולי' ויושר<sup data-n=\"4169\">42</sup> ובמ\"ח בתחלתו<sup data-n=\"4170\">43</sup>, יראה שבאמת הגם שהם עיגולי' שייך בהם מעלה ומטה, והוא מפני שיוצאי' דרך הקו, וע' בע\"ח שביאר שיש מעלה לעיגול הראשון נגד עיגול השני מפני שהוא בבחי' היותר עליונה מהקו דהיינו סמוך לראשית הקו יותר (שבקו בודאי שייך לומר מעלה על ראשיתו שהוא דבוקו לא\"ס כו' ע\"ש), וא\"כ כמ\"כ נא' שבעיגול הראשון עצמו ג\"כ ראשיתו שמקבל מהקו הוא עליון, והתפשטות עיגולו סביב זהו תחתון בערך ראשיתו, ועכ\"ז נק' עיגול שאין בו מעלה ומטה חלוקי', ע\"ש בע\"ח שיש לומר בהם גם ימין ושמאל מצד הע\"ס שבהם. ועוי\"ל ע\"פ משית\"ל שהמקיף הוא לפ\"ע כל עולם, וא\"כ גם בו יש חילוקי מדריגות, וכמשנ\"ת במ\"א שזהו כמו הלבושים<sup data-n=\"4171\">44</sup> שהם מקיפי', ועכ\"ז צ\"ל כפי מדת הגוף שהרי לבוש הקטן אם היותו מקיף מ\"מ לא יצדק להיות מקיף לגדול וכן לבוש הגדול לקטן, ועד\"ז נוכל לומר בלבוש המקיף בגדול עצמו ג\"כ עליון ותחתון שהוא עד\"מ מה שמקיף הראש והכתפי' זהו עליון, והמקיף לשאר אברי הגוף הוא תחתון שלפ\"ז י\"ל שההתחלקות אינו רק מצד המקיף כ\"א מצד הניקף, ואפ\"ל שגם לפ\"ז יש חילוקי מדריגות במקיף עצמו, וצ\"ע. ועוי\"ל שיש במקיף ב' בחי' הא' מה שא\"א שיתהוה ממנו בחי' עולם שהוא מקיף, והב' מה שהוא בערך עולם הניקף, ועכ\"ז הוא מקיף ולא או\"פ כו', וכמשי\"ת. ועכ\"פ מובן איך ששייך לומר עליון ותחתון גם בבחי' המקיף, ועכ\"ז הנה מקיף שבכלל אין בו התחלקות). ולפ\"ז אור מקיף זה שמעביר החיצוני' ירד תחלה קודם שירד חצי השני באורות כו' דאם הי' יורד חצי השני קודם להיות בבחי' א\"פ כו' הרי עדיין היו החיצוני' ג\"כ מקבלי' יניקה בתוס' כמקודם והי' בהכרח להם להסתלק למעלה אלא מטעם זה ירד אור מקיף העליון תחלה כדי לעשות למטה העברת החיצוני' מן הכלים תחלה בכדי שיהיו ראוים אח\"כ לקבל המשכות האורות בהן ולא יסתלקו האורות עוד מהם ואחר שנתקנו הכלים למטה אח\"כ ירד חצי השני מהמקיף להיות על ידו המשכת האורות בכלים גם בבחי' א\"פ ויתקיימו שם כי כבר נתבער הרע דחיצוני' כו'.",[["4166","39","<b>המקיף הוא מבחי' עגולים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380524\" data-slug=\"likkutei-torah\" data-id=\"4001380524\">לקו\"ת קרח נב, רע\"ג</a>."],["4167","40","<b>עגולים שאינו שייך כלל מעלה ומטה</b>: ראה מאמרי אדה\"א נ\"ך ע' תמז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540048\" data-slug=\"torat-chaim\" data-id=\"2300540048\">תו\"ח שמות ח\"א לז, ד</a>. וש\"נ."],["4168","41","<b>ומ\"ע</b>: ומהו ענין."],["4169","42","<b>בע\"ח שער עגולי' ויושר. . בתחלתו</b>: ענף ב מ\"ב [ מהדורא בתרא]."],["4170","43","<b>ובמ\"ח בתחלתו</b>: ראה שם (ד, ב) סדר זרעים מסכת צמצום א\"ס פ\"א, מ\"ג. מסכת בריאת אדם קדמון פ\"א, מ\"א."],["4171","44","<b>שהמקיף. . כמו הלבושים</b>: ראה גם המשך מים רבים תרל\"ו פ\"ר ע' רלא."]]],[2000450392,"<b>ולהבין</b> ביאור ענין אור מקיף זה שנחלק לשנים כו', יובן ע\"פ הקדמה<sup data-n=\"4172\">45</sup> שיש בחי' או\"פ ואו\"מ בכל עולם ועולם לפי ערכו<sup data-n=\"4173\">46</sup> דהיינו כמו בעולם הבריאה האור המקיף דבריאה הוא רק לפ\"ע עולם האו\"פ דבריאה כו', ועד\"ז בעולם האצי' ג\"כ בחי' המקיף דאצי' הוא לפ\"ע האצי' כו', ובכל מקום פי' המקיף הוא ענין אותה ההארה שאינה מתלבשת בכלים כלל<sup data-n=\"4174\">47</sup>, וגם לא בא בהשגה שהוא בחי' א\"פ כידוע אלא נשאר למעלה כו' וכמ\"ש במ\"א, וע' בדרושי ר\"ה בד\"ה מי אל כמוך<sup data-n=\"4175\">48</sup> בסופו בפי' לשארית נחלתו, והנה בחי' או\"מ דאצי' הכללי ידוע שהוא בחי' עתיק, וגם בחי' א\"א והוא הנק' אנכי מי שאנכי<sup data-n=\"4176\">49</sup> כו', ויש בזה אור המקיף ב' מדרגות ע\"ד הנ\"ל והוא שנחלק לשנים, חצי העליון ממנו הוא בחי' עתיק שהוא בחי' תחתונה שבמאציל והחצי השני הוא בחי' א\"א שהוא שרש וראש כל הנאצלי' (וכמבואר<sup data-n=\"4177\">50</sup> בע\"ח בהיכל הז'<sup data-n=\"4178\">51</sup> דמה שבחי' כתר לפעמים נמנה עם ע\"ס ולפעמים לא הוא לפי שב' מדרגות יש בו והוא בחי' ע\"י וא\"א ובחי' ע\"י אינו נמנה כו' ע\"ש) והיינו בחי' כתר עליון בכלל אך שנחלק לב' פרצופי' ע\"י וא\"א כנ\"ל. והנה ביאור הדברים ידוע דפי' עתיק הוא מלשון נעתק כמו המעתיק הרים<sup data-n=\"4179\">52</sup> כו', וענין פי' מלת מעתיק<sup data-n=\"4180\">53</sup> ידוע עד\"מ שקורין למעתיק איזה ספר<sup data-n=\"4181\">54</sup> מכתב לכתב אחר בשם מעתיק שהוא פי'<sup data-n=\"4182\">55</sup> שנעתק הספר ממקומו הראשון ובא לכתב אחר כי ענין ההעתק הוא ע\"ד ענין העברה והסרה ממקום למקום כמו אילן שהעבירוהו ממקומו<sup data-n=\"4183\">56</sup> למקום אחר יקרא גם בשם נעתק שנעתק ממקומו כך גם בהעתקת ספר לפי שהעביר הדבר הכתוב מכתבו הראשון לכתב אחר כו' נק' מעתיק וכן ענין המעתיק הרים שנעתקו ממקומם כו', וכך יובן למעלה דלהיות שבחי' עתיק הוא בחי' התחתונה שבעצמות המאציל עדיין ע\"כ לא נחשב בערך א' עם ענין האצי' גם להיות להן לבחי' מקור ושרש אלא מובדל הוא בערך לגמרי וכאלו נעתק והועבר מהם לגמרי לעוצם בחי' ההבדל הגדול בערך כו' ולכך נק' עת\"י פי' יומין הוא",[["4172","45","<b>ע\"פ הקדמה</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תתקמ: בהקדמה בתחלה. וכן העתיק הר\"ש סופר. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["4173","46","<b>או\"פ ואו\"מ בכל עולם ועולם לפי ערכו</b>: ראה גם סהמ\"צ להצ\"צ ע' פה. מאמרי אדה\"ז תקס\"ג ח\"א ע' רמג. [ומקבילו ב] תקס\"ד ע' פד."],["4174","47","<b>בכלים כלל</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן ע' רמה. ובמאמרי אדה\"ז תקס\"ה כאן: כלל בכלים."],["4175","48","<b>בד\"ה מי אל כמוך</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380968\" data-slug=\"likkutei-torah\" data-id=\"4001380968\">לקו\"ת</a> דרושים לר\"ה סב, ב."],["4176","49","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["4177","50","<b>(וכמבואר</b>: הסוגר נמצא במאמרי אדה\"ז תקס\"ה כאן ע' תתקמא."],["4178","51","<b>בע\"ח בהיכל הז'</b>: שער דרושי אבי\"ע שמ\"ב, פ\"א."],["4179","52","<b>עתיק. . המעתיק הרים</b>: איוב ט, ה. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רמה. וש\"נ. שעה\"י קכו, א ובהערה 5. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540180\" data-slug=\"torat-chaim\" data-id=\"2300540180\">תו\"ח בשלח ח\"א קמב, סע\"ב</a>. וש\"נ."],["4180","53","<b>מעתיק</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן: עתיק."],["4181","54","<b>עתיק. . למעתיק איזה ספר</b>: ראה גם לקו\"ת חוקת סז, ב. מאמר שני המאורות להרי\"א עפשטיין ע' 34."],["4182","55","<b>פי'</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן ע' רמו. ובמאמרי אדה\"ז תקס\"ה כאן: לפי."],["4183","56","<b>אילן שהעבירוהו ממקומו</b>: ראה לקמן (בחלק ההנחות) בהנחה כאן ד\"ה וביאור הענין."]]],[2000450393,"בחי' האצי' בכללות ובחי' עתיק הוא אור שמובדל ומרומם מבחי' יומין דאצי'<sup data-n=\"4184\">57</sup> בתכלית וכמ\"ש המתנשא מימות עולם<sup data-n=\"4185\">58</sup> פי' מתנשא ומובדל ומועתק מהם וזהו עתיק יומין כלומר שנעתק ונבדל מבחי' יומין לעוצם הרוממות כו', והנה בחי' זו דעתיק הוא בחי' פנימיות כתר עליון והוא חלק העליון מאור מקיף הכללי דאצי' אשר איננו מתלבש כלל וכלל באצי' ולכך נק' עתיק יומין כנ\"ל, מפני שאינו מתלבש כלל ביומין דאצי' רק הוא היורד להאיר מלמעלה מרחוק על בחי' חיצוניות הכלים לזככם מיניקת החיצוני' כנ\"ל, אבל בחי' אריך הוא חצי השני ממנו שנכנס באצי' קצת והוא להיות להם לראש ומקור כנ\"ל ואינו נק' עתיק יומין לגמרי להיותו רחוק יותר מעצמיות המאציל כו' (וכנ\"ל בשם הע\"ח שהעיגול הראשון שמתעגל מהקו יש לו יתרון על השני, מפני שקרוב יותר לראשית הקו הדבוק בא\"ס, וא\"כ מובן שבו עצמו מה שנק' ע\"י וא\"א, ע\"י היינו ראשית העיגול כשמתחיל להתעגל מהקו ה\"ה קרוב לא\"ס עצמיות המאציל של הקו, והבחי' שבו עצמו הנק' בש' א\"א להיותו מקור לאצי' ה\"ז עצמו הוראה שהוא רחוק מעט יותר מחלק העליון שהוא נק' ע\"י כו').\n<b>וזהו</b> שרש האצי' מתחיל שרשו מהארות והשפעות<sup data-n=\"4186\">59</sup> א\"א דוקא וכידוע המאמר דאור אבא שהוא אור הראשון דאצי' יונק<sup data-n=\"4187\">60</sup> מן בחי' מזל השמיני דא\"א והוא מזל ונוצר חסד ונק' בשם מזל העליון ומדרגה השני' דאצי' והוא אור אימא יונק ממזל הי\"ג דא\"א והוא מזל ונקה ונק' בשם מזל התחתון כידוע והארות הללו דאו\"א שמקבלים ממזלות דא\"א הן הן שרשי כל האצי' כידוע. והנה פי' יונק הוא בבחי' א\"פ כמשל היונק שמקבל לפ\"ע ע\"י צמצום כו' והאור והשפע מתלבש בתוכו ממש ולא בהעלם עליו כו', וגם כאן שאור אבא יונק ממזל הח' ענינו הוא שמקבל בבחי' א\"פ בגילוי השפע וזהו דוקא מבחי' א\"א הוא שמקבל כך, אבל מבחי' ע\"י לא יוכל לקבל להיותו נק' עת\"י שנעתק ומובדל בערך כנ\"ל. וא\"כ מובן דמה שע\"י התשובה ומע\"ט בכלל ניתקנו ב' דברים הנ\"ל הענין הוא כך דע\"י התשו' מעומקא דלבא כמ\"ש ממעמקים<sup data-n=\"4188\">61</sup> כו' וכמשי\"ת בסמוך<sup data-n=\"4189\">62</sup> מעורר למעלה בחי' המשכת אור המקיף דאנכי מי שאנכי כו' שהוא בחי' עתיק הנ\"ל להיות יורד למטה להעביר החיצוני' ואח\"כ יורד חצי השני והוא בחי' א\"א להיות שרש וראש לנאצלים בבחי' יניקה ממש כמו או\"א שמקבלים ממזלות דא\"א וכיוצא ונמשך האור והשפע עד\"ז לכל האורות והכלים דאצי' וישכנו שם בלתי הסתלקות וגרעון אור ח\"ו והוא ע\"י המצות מעשיות כנ\"ל.",[["4184","57","<b>עתיק. . שמובדל ומרומם מבחי' יומין דאצי'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540202\" data-slug=\"torat-chaim\" data-id=\"2300540202\">תו\"ח וארא ח\"א נג, רע\"א</a>. וש\"נ."],["4185","58","<b>המתנשא מימות עולם</b>: ע\"פ ברכת יוצר אור."],["4186","59","<b>מהארות והשפעות</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן ע' תתקמב: מהארת והשפעת."],["4187","60","<b>דאור אבא. . יונק</b>: ראה זהר אד\"ז האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540755\" data-slug=\"torat-chaim\" data-id=\"2300540755\">תו\"ח שמות ח\"א לו, א</a> ובהערה 455. לעיל המשך וידבר וגו' ויצוום פי\"ב ובהערה 216."],["4188","61","<b>ממעמקים</b>: תהלים קל, א."],["4189","62","<b>וכמשי\"ת בסמוך</b>: בפיסקא הבאה."]]],[2000450394,"<b>וזהו</b> אנכי אנכי הוא מוחה פשעיך, פי' ב\"פ אנכי אנכי הראשון בחי' אור דעתיק שמובדל לגמרי ונק' אנכי מי שאנכי והוא שיורד ע\"י התשו' למחות העוונות ולהעביר הפשעים שלא יקבלו החיצוני' יניקה מהם כו'<sup data-n=\"4190\">63</sup> מטעם הנ\"ל. ואח\"כ יורד האור מבחי' א\"א להאיר את האורות דאצי' כנ\"ל והוא בחי' אנכי השני וע\"י אמצעית שניהם נמחל העון, וזהו שמסיים למעני למען שם הוי' דאצי' בכלל שמקבל מא\"א וגם למען העברת החיצוני' לזה ירדו ב' בחי' אנכי כו', משא\"כ בשעת מ\"ת שלא הי' צריך שם אלא ענין א' בלבד והוא כדי שיאיר אור כתר עליון דא\"א בנאצלים כו' ע\"י המצות שנק' בש' הוי' כמ\"ש ארחות הוי'<sup data-n=\"4191\">64</sup> כו' לכך לא נא' שם אלא אנכי א' והוא אנכי הוי' אלקיך כו', פי' בחי' א\"א שמאיר בחו\"ב שנק' ה' אלקיך ע\"י ב' מזלות הנ\"ל אבל א\"צ לאנכי דבחי' עתיק אלא למצות התשובה דוקא מטעם העברת החיצוני' וכנ\"ל (ובא\"א<sup data-n=\"4192\">65</sup> עצמו יש הבדל ב' מדרגות הללו והוא בחי' י\"ג חוורתי<sup data-n=\"4193\">66</sup> כו' שהוא בחי' הלבנונית כו' ונק' תליסר ארחין<sup data-n=\"4194\">67</sup> כו' שהוא ממדריגת בחי' עתיק למעלה משרש המצות ובחי' השערות דא\"א מהן מתחיל שרש המצות<sup data-n=\"4195\">68</sup> והוא באנכי דמ\"ת כידוע), ועוי\"ל<sup data-n=\"4196\">69</sup> בפי' למעני, כי הנה יש ב' שמות הוי' כמ\"ש ויקרא ה' ה'<sup data-n=\"4197\">70</sup>, ונודע כי ש' הוי' הא' הוא לפני האצי', והב' הוא ש' הוי' שבסדר השתל' והיינו בע\"ס או בז\"א דאצי', וכאן שאומר למעני היינו למען בחי' ש' הוי' שלפני האצי', שממשיכים ע\"י התשובה ומעש\"ט שאחר התשובה, וזהו יפה שעה א'<sup data-n=\"4198\">71</sup> בתשומע\"ט פי' שעה הוא מל' וישע<sup data-n=\"4199\">72</sup> ה' אל הבל<sup data-n=\"4200\">73</sup>, שפונה כבי' א\"ע לקבל מנחת הבל, וכן כאן מה שפונה א\"ע לשוב מדרכו הרעה להדבק ביוצרו חיי החיים<sup data-n=\"4201\">74</sup> זהו בחי' תשו' ואז אח\"כ המעשים<sup data-n=\"4202\">75</sup> הם טובים ומאירים יותר<sup data-n=\"4203\">76</sup> כו', וכ\"מ ממה שא' אנכי אנכי ב\"פ וע\"ז הוא שאומר למעני, א\"כ מובן שהכוונה הוא על ש' הוי' דלעילא כו', ונמצא שהכוונה במה שאו' למעני לא כדיוק הפשוט ולא למענכם ולא מפני שאינכם ראוים ח\"ו אלא כנ\"ל בשביל ש' הוי' דלעילא, ואם היות שבשם אם חטאת כו' אם",[["4190","63","<b>כו'</b>: כ\"ה בכת\"י הר\"ש סופר. ב. במאמרי אדה\"ז תקס\"ה כאן ע' תתקמג־ ובסה\"מ תרכ\"ו כאן: ליתא."],["4191","64","<b>ארחות הוי'</b>: תהלים כה, י."],["4192","65","<b>(ובא\"א</b>: הסוגר נמצא במאמרי אדה\"ז תקס\"ה כאן ע' תתקמג."],["4193","66","<b>י\"ג חיוורתי</b>: ראה זהר נשא אד\"ר קכח, ב. ראה ע\"ח שער א\"א שי\"ג, פ\"ה. פי\"ג. ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' פב. תקס\"ו ע' רנה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380471\" data-slug=\"likkutei-torah\" data-id=\"4001380471\">לקו\"ת שלח לט, ד</a>. אגה\"ק להבין מ\"ש בפע\"ח [תניא קנה, ב]."],["4194","67","<b>תליסר ארחין</b>: ראה ע\"ח שם פ\"ה. מ\"ח סדר קדשים מס' אריך ספ\"ד."],["4195","68","<b>השערות דא\"א מהן מתחיל שרש המצות</b>: ראה בהדרושים שבהערה 66."],["4196","69","<b>ועוי\"ל</b>: מכאן ואילך נכתב בגוכתי\"ק."],["4197","70","<b>ויקרא ה' ה'</b>: תשא לד, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380955\" data-slug=\"likkutei-torah\" data-id=\"4001380955\">לקו\"ת ר\"ה נט, סע\"א</a> ואילך. לעיל המשך אם כסף תלוה ספי\"ד ובהערה 319."],["4198","71","<b>יפה שעה א'</b>: אבות פ\"ד, מי\"ז."],["4199","72","<b>שעה הוא מל' וישע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381302\" data-slug=\"likkutei-torah\" data-id=\"4001381302\">לקו\"ת שה\"ש מג, ג</a>. מאמרי אדה\"א קונטרסים ע' רנג. סה\"מ תרל\"ו ח\"ב ע' שמז."],["4200","73","<b>וישע ה' אל הבל</b>: בראשית ד, ד."],["4201","74","<b>חיי החיים</b>: יומא עא, א."],["4202","75","<b>תשו' ואז אח\"כ המעשים</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'קעט. וש\"נ. תו\"ח וארא ח\"א ר\"ע סו. וש\"נ."],["4203","76","<b>המעשים הם טובים ומאירים יותר</b>: ראה גם שע\"ת עב, ד ובהערה 26."]]],[2000450395,"צדקת כו' כנ\"ל, עכ\"ז הלא פי' בזהר ע\"פ בכל צרתם לא צר<sup data-n=\"4204\">77</sup> שגם להתם מגיע עקתא דישראל כו', וע\"ד ונפלינו אני ועמך<sup data-n=\"4205\">78</sup> כמ\"ש בפ' צו בד\"ה מצה זו<sup data-n=\"4206\">79</sup> ע\"ש.\n<b>אמנם</b> מהו שא' וחטאתיך לא אזכור מאחר שימחה הפשעי' האיך יעלה עה\"ד שיזכור החטאי' שהם יותר קלים, ויש לפרש בב' דרכי' שלהיות כי חטאתיך הם קלים מפשעים לכן לא יהי' מהם שום זכר כלל, משא\"כ מחיית הפשע אם כי מוחלים עכ\"ז י\"ל שמקום המחי' ניכר או י\"ל שהפשעים צריכים מחיה עכ\"פ, ומ\"מ ע\"י התשובה אמחה אותם שלא יהי' רישומם ניכר כלל, אבל חטאתיך לא יעלו על זכרוני כלל וא\"כ א\"צ למחיה כלל, וע\"ד עבר על מ\"ע ושב<sup data-n=\"4207\">80</sup> אינו זז משם עד שמוחלי' לו כו', ואמנם עדיין צ\"ל מה שאו' אנכי אנכי דמשמע שידוע מי הוא כו' ובאמת אינו מושג כלל. אך הענין הוא ע\"ד שאו' בהרבה מצות אני הוי' שגם בשם צ\"ל הלא אינו מושג כו' אלא שזהו בכדי להודיע לנו שכל מצותיו שהם מצות המ'<sup data-n=\"4208\">81</sup> ה\"ה בחי' רצונו העליון א\"ס ב\"ה ולכן אני היינו עצמותו ית' כו' ועד\"ז א' כאן אנכי אנכי היינו אנכי מי שאנכי שאינו מושג ורק הידוע מציאותו ועכ\"פ מציאותו ידוע שהרי גם התינוקות וע\"ה ש\"ש שגור כמ\"ש בסש\"ב<sup data-n=\"4209\">82</sup>, ולא מהותו הוא רומז על בחי' ההעלם היינו שאינו מושג הנה אני הוא המוחה הפשעי' וחטאתיך לא יעלו על זכרוני כלל וכלל כו'.",[["4204","77","<b>בכל צרתם לא צר</b>: ישעי' סג, ט. זהר וירא קכ, ב."],["4205","78","<b>ונפלינו אני ועמך</b>: תשא לג, טז."],["4206","79","<b>בפ' צו בד\"ה מצה זו</b>: לקו\"ת שם יב, ג."],["4207","80","<b>עבר על מ\"ע ושב</b>: יומא פו, א."],["4208","81","<b>המ'</b>: המלך."],["4209","82","<b>כמ\"ש בסש\"ב</b>: ראה גם מאמרי אדה\"א קונטרסים ע' קמב. וש\"נ. שע\"ת ח, ב ובהערה 24. סה\"מ תרל\"ב ח\"ב ע' תלו. ע' תס. וש\"נ. <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a> (ע' כד)."]]],[2000450396,"<h3>וכל מאמינים שהוא שופט צדק כו'</h3>\n<b></b><b>בס\"ד מוצאי ר\"ה ל\"ט לפ\"ק</b>\nמ\"ה וב\"ן\nר\"ה\n<b>וכל</b> מאמינים<sup data-n=\"4210\">1</sup> שהוא שופט צדק<sup data-n=\"4211\">2</sup>, פי' שופט צדק עש\"ה ישבת לכסא שופט צדק (תילי' ט' ה') וכתי' וה' צבאות שופט צדק בוחן כליות ולב (ירמי' י\"א ך') וזהו שיסד השוה<sup data-n=\"4212\">3</sup> ומשוה כו' פי' השוה שהוא לא שניתי כמ\"ש אני הוי' לא שניתי<sup data-n=\"4213\">5</sup>, ומשוה קטן וגדול<sup data-n=\"4214\">4</sup> כמ\"ש ולא נכר שוע לפני דל (איוב ל\"ד<sup data-n=\"4215\">6</sup> ) ולהיותו משוה קטן וגדול כמ\"ש אשר לא ישא פנים<sup data-n=\"4216\">7</sup> כו' לכן וכל מאמיני' שהוא שופט צדק, ובכדי להעלות לבחי' זו דשופט צדק שמשוה קטן וגדול צ\"ל ההעלאה ג\"כ עד\"ז במה שכולם שוה, והיא התשובה שהיא שוה לכל נפש קטן וגדול, ויובן זה בשני דרכי' הא' שכשם שהקטן צריך לתשובה שפי' קטן הוא קטן המעלה כו' כן גם הגדול צריך לתשובה שהרי התשובה אינה על עבירות דוקא<sup data-n=\"4217\">8</sup> כ\"א לשוב מבחי' שהוא עומד שם לבוא למדריגה היותר נעלה, ולכן מ'<sup data-n=\"4218\">9</sup> אתי לאתבא<sup data-n=\"4219\">10</sup> צדיקיי' בתיובתא שנמצא גם הצדיקים שלא חטאו כלל צריכים ג\"כ לבחי' תשובה, ונמצא היא שוה לכל נפש מישראל, הב' שעיקר התשובה היא לבוא לבחי' בכל מאדך<sup data-n=\"4220\">11</sup> וכמשי\"ת שבבחי' זו שוה קטן וגדול, שהרי זהו למעלה מהגבלת הכלי, שבזה אינו שייך כלל קטן וגדול,",[["4210","1","<b>וכל מאמינים</b>: הוא דרוש השלישי מסדרה של ד' מאמרים שבהם נתבאר מאמר ד\"ה להבין וכו' כי המצוה שנאמר ע\"י כ\"ק אדה\"ז בשנת תקס\"ו, ונדפס במאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקלה ואילך. ובשינויים באוה\"ת נצבים ע' א'רכט ואילך. ונאמר גם ע\"י כ\"ק אדמו\"ר מהר\"ש בראשית שנת תרכ\"ז ונדפס בסה\"מ תרכ\"ו ע' רמב ואילך (עם הוספה, וקיצור נדפס שם ע' רנד ואילך).\nבמאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו נדפס גוף המאמר שפתיחתו היא כי המצוה הזאת והוא משבת פ' נצבים תקס\"ה (ומקבילו נדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380900\" data-slug=\"likkutei-torah\" data-id=\"4001380900\">לקו\"ת נצבים מה, ב</a>). וביאור ראשון (שפתיחתו היא להבין שרשי הדברים) נדפס שם בע' תתפג. וביאור שני (שפתיחתו היא להבין וכו' ע\"פ כי המצוה) נדפס שם ע' תתקלה. ומאמר דידן מיוסד על ביאור שני כנ\"ל.\nמאמר דידן מבאר פרק ד וחלק מפ\"ה מהמאמר דתקס\"ו (ע' תתקמג — תתקמו שבמאמרי אדה\"ז תקס\"ה הנ\"ל).\nהנחת כ\"ק אדמו\"ר מהורש\"ב נדפסה להלן בחלק ההנחות. ומשם לוקח התאריך המופיע בריש המאמר (פרט לתיבת בס\"ד).\nהבא בתוך חצאי עיגול בפנים המאמר הם הגהות מכ\"ק אדמו\"ר מהר\"ש פרט באם צויין אחרת.\nמאמר זה נזכר לקמן במאמר ד\"ה שהמ\"מ על יד הערה 3. ד\"ה וידבר כו' אלה הם מועדי על יד הערה 76.\nהפתיחה־ ההגהות והסיום נכתב בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש.\nהדרוש נמצא גם בכת\"י מעתיקים והם: א 363 ע' רעו בכותרת: בס\"ד ר\"ה תרל\"ט. ב 545 ע' קמד. ג 690 ע' קטו בכותרת: בס\"ד ר\"ה תרל\"ט [וההמשך קשה לפענח]. ד 2083 ע' קג כת\"י הר\"ש סופר. ה מאסקבא 127 ע' 21 בכותרת: בס\"ד ר\"ה."],["4211","2","<b>וכל מאמינים שהוא שופט צדק</b>: חרוז בפיוט (לימים נוראים) ”האוחז ביד מדת משפט\"."],["4212","3","<b>שיסד השוה</b>: אוצ\"ל: שיסד הפייטן השוה."],["4213","5","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["4214","4","<b>השוה ומשוה. . קטן וגדול</b>: חרוז בהמשך לוכל מאמינים הנ\"ל."],["4215","6","<b>ל\"ד</b>: פסוק יט."],["4216","7","<b>אשר לא ישא פנים</b>: עקב י, יז."],["4217","8","<b>התשובה אינה על עבירות דוקא</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה על חומותיך ובהערה 100."],["4218","9","<b>מ'</b>: משיח — ראה גם לעיל המשך אם כסף תלוה פי\"ד ובהערה 307."],["4219","10","<b>מ' אתי לאתבא</b>: ראה זהר רע\"מ בהעלותך קנג, ב. מאמרי אדה\"א קונטרסים ע' רפא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540450\" data-slug=\"torat-chaim\" data-id=\"2300540450\">תו\"ח שמות ח\"א מא, ב</a>. וש\"נ."],["4220","11","<b>בכל מאדך</b>: ואתחנן ו, ה."]]]]});
